window.PATHOLOGY_DATA={"questions":[{"id":"g001","name":"脾霍奇金淋巴瘤","kind":"大体","system":"淋巴造血系统","image":"assets/g001.jpg","points":["脾切面多个灰白结节造成斑岩样外观。","先认出脾的外形及切面。","切面散在多个灰白色结节，与暗红褐色脾实质相间。"],"caution":"斑岩样外观不是独立确诊依据；淋巴瘤分型需要组织学及免疫表型。","review":"reviewed","options":[{"text":"脾霍奇金淋巴瘤","reason":"符合本图：脾切面多个灰白结节造成斑岩样外观。"},{"text":"脾粟粒性结核","reason":"鉴别要点：典型为散在细小、相对一致的灰白结节，可有干酪样坏死；不能把所有脾结节直接归为结核。"},{"text":"脾淀粉样变","reason":"鉴别要点：常见蜡样、半透明改变，可呈西米脾或火腿脾；没有这种多发斑岩样结节模式。"},{"text":"脾梗死","reason":"鉴别要点：典型为苍白楔形灶，尖端指向血管、底部朝向脾被膜。"}],"scope":"core","imageWidth":724,"imageHeight":764,"annotations":{"marks":[{"x":45,"y":31,"rx":17,"ry":14,"label":"灰白结节与脾实质相间","detail":"圈内为代表区域：多个灰白结节散布于较深色脾实质中，整体形成斑岩样外观。"}],"note":"需要结合整个脾切面的结节分布；此形态本身不能完成淋巴瘤分型。"}},{"id":"g002","name":"霍奇金淋巴瘤（陷窝细胞）","kind":"镜下","system":"淋巴造血系统","image":"assets/g002.jpg","points":["抓住陷窝样大细胞和混合炎细胞背景，不仅数细胞核。","背景可见多种炎细胞，瘤细胞散在其中。","大细胞胞质较丰富，周围出现明显空隙，形成陷窝样外观。"],"caution":"本图以陷窝样细胞为主，不能仅凭有两个核就等同典型 R-S 细胞；双核对称且大核仁醒目才是典型线索。","review":"reviewed","options":[{"text":"霍奇金淋巴瘤（陷窝细胞）","reason":"符合本图：抓住陷窝样大细胞和混合炎细胞背景，不仅数细胞核。"},{"text":"反应性淋巴组织增生","reason":"鉴别要点：以保留反应性淋巴组织结构和多样成熟细胞为主；不能据一般活化大细胞替代霍奇金特征细胞。"},{"text":"弥漫大B细胞淋巴瘤","reason":"鉴别要点：通常为较成片、弥漫增生的异型大淋巴细胞；应与散在特征大细胞和混合炎细胞背景比较。"},{"text":"结核性肉芽肿","reason":"鉴别要点：中央干酪样坏死，外围细胞性肉芽肿。"}],"scope":"core","imageWidth":695,"imageHeight":420,"annotations":{"marks":[{"x":47,"y":55,"rx":22,"ry":34,"label":"陷窝样大细胞","detail":"大细胞核明显大于周围小细胞，胞质周围有宽阔透明空隙，是本图主要识别线索。"},{"x":82,"y":57,"rx":12,"ry":31,"label":"背景小细胞","detail":"周围较小深染细胞衬托出中央异常大细胞的体积差异。"}],"note":"不能仅凭细胞双核判作典型 R-S 细胞，仍需核仁和背景等证据。"}},{"id":"g003","name":"白血病骨髓浸润","kind":"大体","system":"淋巴造血系统","image":"assets/g003.jpg","points":["长骨髓腔灰白浸润是原标本线索，白血病分型不能由大体判定。","先辨认剖开的长骨和髓腔。","髓腔内组织呈灰白色、较均匀，替代正常脂肪性骨髓。"],"caution":"本题为已知诊断标本。图像狭窄、分辨率有限，且大体表现不特异，不能据此独立诊断白血病或判断分型。","review":"reviewed","options":[{"text":"白血病骨髓浸润","reason":"符合本图：长骨髓腔灰白浸润是原标本线索，白血病分型不能由大体判定。"},{"text":"正常脂肪性骨髓","reason":"鉴别要点：髓腔富含黄色脂肪，不呈灰白肿瘤细胞替代样外观。"},{"text":"再生障碍性贫血骨髓","reason":"鉴别要点：骨髓造血组织减少、脂肪增多，主要表现为黄色脂肪化而非灰白浸润。"},{"text":"骨髓纤维化","reason":"鉴别要点：髓腔可被纤维组织替代并较致密，但需切片和网状纤维染色证实，单张大体不能据颜色确诊。"}],"scope":"core","imageWidth":121,"imageHeight":423,"annotations":{"marks":[{"x":42,"y":61,"rx":15,"ry":31,"label":"长骨髓腔灰白组织","detail":"沿长骨中央髓腔观察灰白、较均匀的组织，区别外侧致密骨皮质。"}],"note":"髓腔改变不能确定白血病分型。"}},{"id":"g004","name":"卵巢黏液性囊腺瘤","kind":"大体","system":"生殖与乳腺","image":"assets/g004.jpg","points":["多房囊性肿物加黏液样内容物。","肿物呈多房囊性，各囊腔大小不等。","囊内可见较黏稠、混浊或胶冻样内容物。"],"caution":"","review":"reviewed","options":[{"text":"卵巢黏液性囊腺瘤","reason":"符合本图：多房囊性肿物加黏液样内容物。"},{"text":"卵巢浆液性囊性肿瘤","reason":"鉴别要点：囊内明显乳头增生提示浆液性肿瘤类别，良恶性另判。"},{"text":"成熟性畸胎瘤","reason":"鉴别要点：囊实混合肿物内有多种成熟组织成分。"},{"text":"卵巢纤维瘤","reason":"鉴别要点：典型为实性灰白肿块，切面纤维束状，不以多房黏液囊腔或囊内乳头为主。"}],"scope":"core","imageWidth":677,"imageHeight":907,"annotations":{"marks":[{"x":43,"y":33,"rx":24,"ry":19,"label":"大小不等的囊腔","detail":"多个囊腔被薄壁分隔，形成多房囊性结构。"},{"x":52,"y":57,"rx":15,"ry":13,"label":"囊内黏液样内容物","detail":"圈内可见较混浊、胶冻样的囊内物，结合多房结构识别。"}],"note":""}},{"id":"g005","name":"卵巢浆液性囊性肿瘤","kind":"大体","system":"生殖与乳腺","image":"assets/g005.jpg","points":["囊内明显乳头增生提示浆液性肿瘤类别，良恶性另判。","囊壁内面可见大量分支状、颗粒状乳头突起。","整体为囊性肿物，重点观察囊内乳头而不是子宫肌壁。"],"caution":"乳头明显，但仅凭大体照片不能可靠区分良性、交界性及恶性；本题只考浆液性肿瘤类别。","review":"reviewed","options":[{"text":"卵巢浆液性囊性肿瘤","reason":"符合本图：囊内明显乳头增生提示浆液性肿瘤类别，良恶性另判。"},{"text":"卵巢黏液性囊腺瘤","reason":"鉴别要点：多房囊性肿物加黏液样内容物。"},{"text":"成熟性畸胎瘤","reason":"鉴别要点：囊实混合肿物内有多种成熟组织成分。"},{"text":"卵巢纤维瘤","reason":"鉴别要点：典型为实性灰白肿块，切面纤维束状，不以多房黏液囊腔或囊内乳头为主。"}],"scope":"core","imageWidth":899,"imageHeight":917,"annotations":{"marks":[{"x":40,"y":48,"rx":22,"ry":28,"label":"囊内乳头状突起","detail":"囊壁内面生出大量不规则、分支及颗粒状突起，是识别浆液性肿瘤类别的重点。"}],"note":"乳头增生不能单独区分良性、交界性与恶性。"}},{"id":"g006","name":"子宫平滑肌瘤","kind":"大体","system":"生殖与乳腺","image":"assets/g006.jpg","points":["界清实性结节、旋涡样切面、推挤宫腔。","先识别子宫肌壁及中央宫腔。","肌壁内有界限清楚、圆形的实性灰白结节，推挤宫腔。"],"caution":"","review":"reviewed","options":[{"text":"子宫平滑肌瘤","reason":"符合本图：界清实性结节、旋涡样切面、推挤宫腔。"},{"text":"子宫内膜癌","reason":"鉴别要点：病变以宫体内膜为中心，形成不规则增厚与隆起。"},{"text":"子宫腺肌病（大体）","reason":"鉴别要点：多为肌壁弥漫或局部增厚，界限不清，可有小囊腔及出血点；不同于规则、界清的旋涡样肌瘤结节。"},{"text":"子宫平滑肌肉瘤","reason":"鉴别要点：常为不规则、较软的肌壁肿物，可有出血坏死及浸润；确定需核异型、核分裂和肿瘤细胞坏死等证据。"}],"scope":"core","imageWidth":843,"imageHeight":824,"annotations":{"marks":[{"x":55,"y":27,"rx":14,"ry":17,"label":"界清实性结节","detail":"上方圆形灰白结节边界清楚，与周围子宫肌壁分开并向宫腔突出。"},{"x":43,"y":49,"rx":10,"ry":14,"label":"被推挤的宫腔","detail":"结节下方狭长宫腔发生偏移和挤压，帮助判断肿物与子宫壁的关系。"}],"note":""}},{"id":"g007","name":"葡萄胎","kind":"大体","system":"生殖与乳腺","image":"assets/g007.jpg","points":["宫腔内葡萄串样水泡，本质是水肿绒毛。","宫腔内充满大小不等的半透明囊泡。","囊泡由细蒂相连，整体呈葡萄串样。"],"caution":"","review":"reviewed","options":[{"text":"葡萄胎","reason":"符合本图：宫腔内葡萄串样水泡，本质是水肿绒毛。"},{"text":"侵蚀性葡萄胎","reason":"鉴别要点：重点是水肿绒毛进入子宫肌壁。"},{"text":"绒毛膜癌","reason":"鉴别要点：子宫肌壁内明显出血坏死的滋养细胞肿瘤。"},{"text":"子宫内膜癌","reason":"鉴别要点：病变以宫体内膜为中心，形成不规则增厚与隆起。"}],"scope":"core","imageWidth":1268,"imageHeight":961,"annotations":{"marks":[{"x":49,"y":49,"rx":11,"ry":30,"label":"宫腔内成串水泡","detail":"大小不等的囊泡沿宫腔聚集，可见细蒂相连，呈葡萄串样。"}],"note":""}},{"id":"g008","name":"葡萄胎","kind":"镜下","system":"生殖与乳腺","image":"assets/g008.jpg","points":["绒毛间质水肿并伴滋养细胞增生。","绒毛体积增大，间质疏松、明显水肿。","部分绒毛中央形成空腔样水肿池。"],"caution":"","review":"reviewed","options":[{"text":"葡萄胎","reason":"符合本图：绒毛间质水肿并伴滋养细胞增生。"},{"text":"侵蚀性葡萄胎","reason":"鉴别要点：肌层内出现真正绒毛，是侵蚀性葡萄胎的关键。"},{"text":"绒毛膜癌（镜下）","reason":"鉴别要点：异型滋养细胞增生，常伴出血坏死，关键是没有真正绒毛结构。"},{"text":"正常妊娠绒毛","reason":"鉴别要点：可见绒毛及滋养细胞，但不应出现葡萄胎式显著绒毛水肿和异常滋养细胞增生。"}],"scope":"core","imageWidth":1268,"imageHeight":822,"annotations":{"marks":[{"x":68,"y":60,"rx":17,"ry":35,"label":"水肿增大的绒毛","detail":"这个巨大淡染绒毛间质疏松、细胞稀少，与周围较小绒毛形成对比。"},{"x":20,"y":67,"rx":9,"ry":13,"label":"增生的滋养细胞","detail":"绒毛表面的深染细胞增多、成团，需与绒毛间质水肿一起观察。"}],"note":""}},{"id":"g009","name":"侵蚀性葡萄胎","kind":"大体","system":"生殖与乳腺","image":"assets/g009.jpg","points":["重点是水肿绒毛进入子宫肌壁。","子宫壁增厚，肌壁内可见水泡样病灶。","病变进入子宫肌层，常伴出血、坏死。"],"caution":"本题为已知诊断标本；侵蚀的确认仍需镜下见绒毛进入肌层或血管。","review":"reviewed","options":[{"text":"侵蚀性葡萄胎","reason":"符合本图：重点是水肿绒毛进入子宫肌壁。"},{"text":"葡萄胎","reason":"鉴别要点：宫腔内葡萄串样水泡，本质是水肿绒毛。"},{"text":"绒毛膜癌","reason":"鉴别要点：子宫肌壁内明显出血坏死的滋养细胞肿瘤。"},{"text":"子宫平滑肌瘤","reason":"鉴别要点：界清实性结节、旋涡样切面、推挤宫腔。"}],"scope":"core","imageWidth":1015,"imageHeight":929,"annotations":{"marks":[{"x":33,"y":71,"rx":6,"ry":8,"label":"肌壁附近水泡样病灶","detail":"原箭头所指灰白水泡样结构位于子宫壁病变区域，应结合邻近肌壁关系观察。"}],"note":"绒毛侵入肌层需镜下确认。"}},{"id":"g010","name":"侵蚀性葡萄胎","kind":"镜下","system":"生殖与乳腺","image":"assets/g010.jpg","points":["肌层内出现真正绒毛，是侵蚀性葡萄胎的关键。","肌层平滑肌束之间出现绒毛结构。","绒毛间质明显水肿，表面滋养细胞增生。"],"caution":"","review":"reviewed","options":[{"text":"侵蚀性葡萄胎","reason":"符合本图：肌层内出现真正绒毛，是侵蚀性葡萄胎的关键。"},{"text":"葡萄胎","reason":"鉴别要点：绒毛间质水肿并伴滋养细胞增生。"},{"text":"绒毛膜癌（镜下）","reason":"鉴别要点：异型滋养细胞增生，常伴出血坏死，关键是没有真正绒毛结构。"},{"text":"子宫内膜癌肌层浸润","reason":"鉴别要点：浸润性癌腺体常有结构/细胞异型及间质反应；不能把带正常内膜间质的异位腺体直接认成癌。"}],"scope":"core","imageWidth":1268,"imageHeight":645,"annotations":{"marks":[{"x":40,"y":35,"rx":9,"ry":13,"label":"绒毛结构","detail":"可见有间质核心和表面细胞包覆的绒毛，不能把它与单纯肿瘤细胞团混淆。"},{"x":50,"y":48,"rx":5,"ry":18,"label":"滋养细胞增生","detail":"绒毛附近深染细胞成团聚集，衬托绒毛结构。"},{"x":79,"y":14,"rx":14,"ry":10,"label":"周围平滑肌束","detail":"嗜酸性成束肌组织围绕病变，结合肌组织内出现绒毛识别侵蚀。"}],"note":""}},{"id":"g011","name":"绒毛膜癌","kind":"大体","system":"生殖与乳腺","image":"assets/g011.jpg","points":["子宫肌壁内明显出血坏死的滋养细胞肿瘤。","子宫壁内可见不规则肿瘤结节。","病变明显出血坏死，形成暗褐色、灰白色交错区域。"],"caution":"本题为已知诊断标本。大体出血、坏死不具特异性，确诊仍需镜下证据。","review":"reviewed","options":[{"text":"绒毛膜癌","reason":"符合本图：子宫肌壁内明显出血坏死的滋养细胞肿瘤。"},{"text":"侵蚀性葡萄胎","reason":"鉴别要点：重点是水肿绒毛进入子宫肌壁。"},{"text":"葡萄胎","reason":"鉴别要点：宫腔内葡萄串样水泡，本质是水肿绒毛。"},{"text":"子宫内膜癌","reason":"鉴别要点：病变以宫体内膜为中心，形成不规则增厚与隆起。"}],"scope":"core","imageWidth":330,"imageHeight":599,"annotations":{"marks":[{"x":38,"y":29,"rx":22,"ry":16,"label":"出血坏死性结节","detail":"子宫上部灰白与暗褐色区域交错，病灶不规则并伴明显出血坏死。"}],"note":"出血、坏死不特异，组织类型需镜下证实。"}},{"id":"g012","name":"子宫内膜癌","kind":"大体","system":"生殖与乳腺","image":"assets/g012.jpg","points":["病变以宫体内膜为中心，形成不规则增厚与隆起。","子宫腔内见灰白或灰黄色不规则增厚、隆起组织。","病变主要位于宫体内膜，向肌壁浸润，宫腔轮廓不规则。"],"caution":"大体图可识别内膜来源肿瘤；腺癌组织类型需组织学确认。","review":"reviewed","options":[{"text":"子宫内膜癌","reason":"符合本图：病变以宫体内膜为中心，形成不规则增厚与隆起。"},{"text":"子宫颈癌（菜花型）","reason":"鉴别要点：宫颈部位的外生性菜花状肿块。"},{"text":"子宫平滑肌瘤","reason":"鉴别要点：界清实性结节、旋涡样切面、推挤宫腔。"},{"text":"绒毛膜癌","reason":"鉴别要点：子宫肌壁内明显出血坏死的滋养细胞肿瘤。"}],"scope":"core","imageWidth":456,"imageHeight":371,"annotations":{"marks":[{"x":74,"y":42,"rx":11,"ry":21,"label":"宫腔内不规则增厚","detail":"宫体腔面出现粗糙、灰黄隆起组织，正常光整内膜轮廓被破坏。"}],"note":""}},{"id":"g013","name":"子宫颈癌（菜花型）","kind":"大体","system":"生殖与乳腺","image":"assets/g013.jpg","points":["宫颈部位的外生性菜花状肿块。","先认出上方宫体与下方宫颈。","宫颈部位突出巨大、表面不平的菜花样肿物。"],"caution":"单凭大体图不能确定鳞状细胞癌等组织学类型，需结合镜下表现。","review":"reviewed","options":[{"text":"子宫颈癌（菜花型）","reason":"符合本图：宫颈部位的外生性菜花状肿块。"},{"text":"子宫内膜癌","reason":"鉴别要点：病变以宫体内膜为中心，形成不规则增厚与隆起。"},{"text":"子宫平滑肌瘤","reason":"鉴别要点：界清实性结节、旋涡样切面、推挤宫腔。"},{"text":"葡萄胎","reason":"鉴别要点：宫腔内葡萄串样水泡，本质是水肿绒毛。"}],"scope":"core","imageWidth":677,"imageHeight":1091,"annotations":{"marks":[{"x":45,"y":62,"rx":22,"ry":17,"label":"宫颈菜花状肿物","detail":"下方宫颈区域有外生、表面凹凸不平的大块肿物，与上方较完整宫体形成对比。"}],"note":""}},{"id":"g015","name":"乳腺导管原位癌（粉刺型）","kind":"镜下","system":"生殖与乳腺","image":"assets/g015.jpg","points":["导管内肿瘤细胞充填，中央粉刺样坏死。","多个导管腔被密集增生的肿瘤细胞充填。","导管中心出现大片粉红色坏死物，呈粉刺样坏死。"],"caution":"“原位”需完整组织切片证实未浸润；中心坏死是粉刺型的识别重点。","review":"reviewed","options":[{"text":"乳腺导管原位癌（粉刺型）","reason":"符合本图：导管内肿瘤细胞充填，中央粉刺样坏死。"},{"text":"乳腺纤维腺瘤","reason":"鉴别要点：纤维间质增生把腺管挤成裂隙。"},{"text":"乳腺导管内乳头状瘤","reason":"鉴别要点：导管内出现具有纤维血管轴心的乳头，而非导管中心大块粉刺样坏死。"},{"text":"浸润性乳腺癌（镜下）","reason":"鉴别要点：癌细胞突破原有导管边界侵入间质，形成不规则腺管、细胞团或条索。"}],"scope":"core","imageWidth":1269,"imageHeight":458,"annotations":{"marks":[{"x":49,"y":43,"rx":6,"ry":12,"label":"导管中央粉刺样坏死","detail":"圆形导管内中央为均匀粉红坏死物，周围有深染肿瘤细胞带。"},{"x":79,"y":52,"rx":6,"ry":13,"label":"另一处同类导管","detail":"另一扩张导管重复出现中央坏死和外周细胞增生，提示该形态并非孤立一点。"}],"note":"原位性质需完整组织取材确认。"}},{"id":"g016","name":"乳腺纤维腺瘤","kind":"大体","system":"生殖与乳腺","image":"assets/g016.jpg","points":["界清、分叶、灰白切面伴裂隙。","肿块境界清楚，呈分叶状。","切面灰白、较均匀，可见裂隙样结构。"],"caution":"","review":"reviewed","options":[{"text":"乳腺纤维腺瘤","reason":"符合本图：界清、分叶、灰白切面伴裂隙。"},{"text":"浸润性乳腺癌","reason":"鉴别要点：不规则灰白病灶伴浸润、牵拉乳头。"},{"text":"乳腺脂肪坏死","reason":"鉴别要点：可见坏死脂肪和瘢痕，临床上可模仿癌；切面常有油性囊腔、钙化或周边纤维化，仍需镜下鉴别。"},{"text":"急性乳腺炎","reason":"鉴别要点：以红肿和化脓、脓腔为主，不呈典型星芒状实性癌性浸润。"}],"scope":"core","imageWidth":704,"imageHeight":939,"annotations":{"marks":[{"x":63,"y":66,"rx":6,"ry":8,"label":"裂隙样结构","detail":"灰白实性切面内出现狭长裂隙，是纤维腺瘤大体识别线索之一。"},{"x":26,"y":65,"rx":14,"ry":19,"label":"较均匀的分叶切面","detail":"圈内代表区域较均一、灰白，结合外缘分叶和界清特点观察。"}],"note":""}},{"id":"g017","name":"乳腺纤维腺瘤","kind":"镜下","system":"生殖与乳腺","image":"assets/g017.jpg","points":["纤维间质增生把腺管挤成裂隙。","肿瘤含增生的纤维间质和腺管两种成分。","纤维间质挤压腺管，使其狭长、弯曲，形成裂隙。"],"caution":"","review":"reviewed","options":[{"text":"乳腺纤维腺瘤","reason":"符合本图：纤维间质增生把腺管挤成裂隙。"},{"text":"乳腺导管原位癌（粉刺型）","reason":"鉴别要点：导管内肿瘤细胞充填，中央粉刺样坏死。"},{"text":"乳腺导管内乳头状瘤","reason":"鉴别要点：导管内出现具有纤维血管轴心的乳头，而非导管中心大块粉刺样坏死。"},{"text":"浸润性乳腺癌（镜下）","reason":"鉴别要点：癌细胞突破原有导管边界侵入间质，形成不规则腺管、细胞团或条索。"}],"scope":"core","imageWidth":1269,"imageHeight":523,"annotations":{"marks":[{"x":18,"y":38,"rx":11,"ry":26,"label":"受压的裂隙样腺管","detail":"深染上皮围成细长、弯曲甚至分支的腺管腔，显示间质对腺管的挤压。"},{"x":48,"y":42,"rx":6,"ry":20,"label":"增生的纤维间质","detail":"腺管之间大片淡粉色纤维性组织增多，与腺上皮共同构成病变。"}],"note":""}},{"id":"g018","name":"浸润性乳腺癌","kind":"大体","system":"生殖与乳腺","image":"assets/g018.jpg","points":["不规则灰白病灶伴浸润、牵拉乳头。","乳腺切面可见灰白、不规则的实性病变。","病灶边界不清，呈条索或星芒样浸润。"],"caution":"橘皮样改变是皮肤淋巴管受阻的表现，并非每一张切面图都能清楚显示；本图重点看浸润与乳头牵拉。","review":"reviewed","options":[{"text":"浸润性乳腺癌","reason":"符合本图：不规则灰白病灶伴浸润、牵拉乳头。"},{"text":"乳腺纤维腺瘤","reason":"鉴别要点：界清、分叶、灰白切面伴裂隙。"},{"text":"乳腺脂肪坏死","reason":"鉴别要点：可见坏死脂肪和瘢痕，临床上可模仿癌；切面常有油性囊腔、钙化或周边纤维化，仍需镜下鉴别。"},{"text":"急性乳腺炎","reason":"鉴别要点：以红肿和化脓、脓腔为主，不呈典型星芒状实性癌性浸润。"}],"scope":"core","imageWidth":393,"imageHeight":539,"annotations":{"marks":[{"x":47,"y":42,"rx":17,"ry":10,"label":"灰白浸润性病灶","detail":"灰白组织与周围黄色脂肪交界不整齐，呈不规则浸润轮廓。"},{"x":80,"y":38,"rx":5,"ry":8,"label":"乳头区域","detail":"右侧乳头与下方灰白病灶相连，观察其牵拉及轮廓改变。"}],"note":"此切面不能直接确认橘皮样改变。"}},{"id":"g019","name":"结节性甲状腺肿","kind":"大体","system":"内分泌系统","image":"assets/g019.jpg","points":["大小不等的多个甲状腺结节，伴退变。","甲状腺两叶内存在多个大小不等的结节。","切面斑杂，部分结节发生囊性变、出血或纤维化。"],"caution":"","review":"reviewed","options":[{"text":"结节性甲状腺肿","reason":"符合本图：大小不等的多个甲状腺结节，伴退变。"},{"text":"弥漫性毒性甲状腺肿","reason":"鉴别要点：甲状腺弥漫、较均一增大，切面较实。"},{"text":"弥漫性胶样甲状腺肿","reason":"鉴别要点：胶质丰富，切面细蜂窝样、胶冻样。"},{"text":"甲状腺滤泡性肿瘤","reason":"鉴别要点：一般为较孤立、有包膜的结节；滤泡癌需见包膜或血管侵犯，不能只由大体增大判断。"}],"scope":"core","imageWidth":798,"imageHeight":1015,"annotations":{"marks":[{"x":31,"y":24,"rx":12,"ry":17,"label":"多发结节","detail":"甲状腺切面有多个大小不等的结节，结节之间界限可辨。"},{"x":56,"y":66,"rx":14,"ry":14,"label":"囊性退变区域","detail":"较大结节内部形成不规则囊腔及残留组织，体现结节性甲状腺肿的斑杂退变。"}],"note":""}},{"id":"g020","name":"结节性甲状腺肿","kind":"镜下","system":"内分泌系统","image":"assets/g020.jpg","points":["滤泡大小悬殊、胶质多，区域不均一。","甲状腺滤泡大小悬殊，许多滤泡显著扩张。","滤泡内胶质丰富，周围上皮较扁平。"],"caution":"","review":"reviewed","options":[{"text":"结节性甲状腺肿","reason":"符合本图：滤泡大小悬殊、胶质多，区域不均一。"},{"text":"弥漫性毒性甲状腺肿","reason":"鉴别要点：上皮增高乳头样突起，加胶质边缘吸收空泡。"},{"text":"桥本甲状腺炎","reason":"鉴别要点：镜下显著淋巴细胞浸润、淋巴滤泡及嗜酸性细胞改变；不同于胶质充盈或吸收空泡的模式。"},{"text":"甲状腺乳头状癌","reason":"鉴别要点：诊断依赖乳头状或滤泡状肿瘤及特征核改变，如核沟、核内假包涵体；单纯滤泡上皮乳头样增生不等于乳头状癌。"}],"scope":"core","imageWidth":1268,"imageHeight":793,"annotations":{"marks":[{"x":83,"y":43,"rx":8,"ry":12,"label":"扩张的含胶质滤泡","detail":"大滤泡内充满均匀粉红色胶质，滤泡边缘上皮较薄。"},{"x":45,"y":37,"rx":7,"ry":9,"label":"邻近小滤泡群","detail":"与大滤泡相比，这一区滤泡细小而密集，突出滤泡大小悬殊。"}],"note":""}},{"id":"g021","name":"弥漫性毒性甲状腺肿","kind":"镜下","system":"内分泌系统","image":"assets/g021.jpg","points":["上皮增高乳头样突起，加胶质边缘吸收空泡。","滤泡上皮增高、拥挤，并向腔内作乳头状突起。","胶质边缘出现扇贝样吸收空泡。"],"caution":"滤泡内物质为胶质；乳头样突起通常没有真正的纤维血管轴心。","review":"reviewed","options":[{"text":"弥漫性毒性甲状腺肿","reason":"符合本图：上皮增高乳头样突起，加胶质边缘吸收空泡。"},{"text":"结节性甲状腺肿","reason":"鉴别要点：滤泡大小悬殊、胶质多，区域不均一。"},{"text":"桥本甲状腺炎","reason":"鉴别要点：镜下显著淋巴细胞浸润、淋巴滤泡及嗜酸性细胞改变；不同于胶质充盈或吸收空泡的模式。"},{"text":"甲状腺乳头状癌","reason":"鉴别要点：诊断依赖乳头状或滤泡状肿瘤及特征核改变，如核沟、核内假包涵体；单纯滤泡上皮乳头样增生不等于乳头状癌。"}],"scope":"core","imageWidth":1203,"imageHeight":835,"annotations":{"marks":[{"x":56,"y":21,"rx":12,"ry":19,"label":"上皮增高及乳头样突起","detail":"滤泡上皮拥挤、增高并向腔内突出，和扁平静止上皮不同。"},{"x":18,"y":12,"rx":5,"ry":6,"label":"胶质边缘吸收空泡","detail":"原箭头附近胶质与上皮交界处出现较大透明空泡，结合上皮增生活动观察。"}],"note":"不要把胶质内部细小均匀裂纹都当作吸收空泡；重点看贴近上皮的边缘改变。"}},{"id":"g022","name":"弥漫性毒性甲状腺肿","kind":"大体","system":"内分泌系统","image":"assets/g022.jpg","points":["甲状腺弥漫、较均一增大，切面较实。","甲状腺呈较对称的弥漫性增大。","表面较光滑、切面灰红或红褐，整体较均匀。"],"caution":"本题为已知诊断标本。固定后颜色会改变，甲状腺功能状态需结合临床判断。","review":"reviewed","options":[{"text":"弥漫性毒性甲状腺肿","reason":"符合本图：甲状腺弥漫、较均一增大，切面较实。"},{"text":"结节性甲状腺肿","reason":"鉴别要点：大小不等的多个甲状腺结节，伴退变。"},{"text":"弥漫性胶样甲状腺肿","reason":"鉴别要点：胶质丰富，切面细蜂窝样、胶冻样。"},{"text":"甲状腺滤泡性肿瘤","reason":"鉴别要点：一般为较孤立、有包膜的结节；滤泡癌需见包膜或血管侵犯，不能只由大体增大判断。"}],"scope":"core","imageWidth":821,"imageHeight":845,"annotations":{"marks":[{"x":29,"y":49,"rx":17,"ry":27,"label":"较均一的甲状腺切面","detail":"圈内为代表区域：实质较均匀，缺少结节性甲状腺肿那种大小悬殊的独立结节。"}],"note":"仍须整体看两叶外形和切面；功能亢进不能由照片单独确认。"}},{"id":"g023","name":"弥漫性胶样甲状腺肿","kind":"大体","system":"内分泌系统","image":"assets/g023.jpg","points":["胶质丰富，切面细蜂窝样、胶冻样。","甲状腺弥漫性增大，切面遍布细小蜂窝样结构。","胶质丰富时呈棕褐、半透明或胶冻样外观。"],"caution":"","review":"reviewed","options":[{"text":"弥漫性胶样甲状腺肿","reason":"符合本图：胶质丰富，切面细蜂窝样、胶冻样。"},{"text":"结节性甲状腺肿","reason":"鉴别要点：大小不等的多个甲状腺结节，伴退变。"},{"text":"弥漫性毒性甲状腺肿","reason":"鉴别要点：甲状腺弥漫、较均一增大，切面较实。"},{"text":"甲状腺滤泡性肿瘤","reason":"鉴别要点：一般为较孤立、有包膜的结节；滤泡癌需见包膜或血管侵犯，不能只由大体增大判断。"}],"scope":"core","imageWidth":1095,"imageHeight":1131,"annotations":{"marks":[{"x":32,"y":39,"rx":17,"ry":23,"label":"细蜂窝样切面","detail":"圈内密布细小含胶质的腔隙，形成较均一的细蜂窝样外观。"}],"note":""}},{"id":"g024","name":"原发性肺结核综合征","kind":"大体","system":"感染与寄生虫","image":"assets/g024.jpg","points":["肺原发灶配同侧引流淋巴结结核。","在肺内寻找胸膜下原发病灶。","同时观察同侧肺门及邻近引流淋巴结肿大。"],"caution":"三组成分不一定都能在单张照片中清楚辨认，尤其淋巴管炎。","review":"reviewed","options":[{"text":"原发性肺结核综合征","reason":"符合本图：肺原发灶配同侧引流淋巴结结核。"},{"text":"肺粟粒性结核","reason":"鉴别要点：全肺散在密集、大小近似的粟粒样结节。"},{"text":"继发性空洞型肺结核","reason":"鉴别要点：重点为肺内不规则空洞及周围纤维化、干酪样坏死，不是原发灶与引流淋巴结成套组合。"},{"text":"肺癌","reason":"鉴别要点：常见不规则实性或浸润性肿块，可坏死；应与结核球的干酪样核心、纤维包裹鉴别，最终需镜下。"}],"scope":"core","imageWidth":609,"imageHeight":1008,"annotations":{"marks":[{"x":88,"y":70,"rx":4,"ry":4,"label":"肺外周局灶病变","detail":"原箭头所示病变靠近胸膜，应与同侧引流淋巴结一起寻找。"},{"x":63,"y":53,"rx":6,"ry":7,"label":"引流淋巴结肿大","detail":"气管旁、肺门附近可见突出的灰白结节，提示引流淋巴结受累。"}],"note":"本图未清楚显示完整的结核性淋巴管炎。"}},{"id":"g025","name":"肺粟粒性结核","kind":"大体","system":"感染与寄生虫","image":"assets/g025.jpg","points":["全肺散在密集、大小近似的粟粒样结节。","肺切面弥漫分布大量细小灰白结节。","结节大小较一致，类似撒满粟粒。"],"caution":"","review":"reviewed","options":[{"text":"肺粟粒性结核","reason":"符合本图：全肺散在密集、大小近似的粟粒样结节。"},{"text":"肺结核球","reason":"鉴别要点：肺内界清圆形结节、灰黄干酪样核心。"},{"text":"小叶性肺炎（支气管肺炎）","reason":"鉴别要点：散在、大小不等的支气管周围斑片实变。"},{"text":"肺癌","reason":"鉴别要点：常见不规则实性或浸润性肿块，可坏死；应与结核球的干酪样核心、纤维包裹鉴别，最终需镜下。"}],"scope":"core","imageWidth":609,"imageHeight":579,"annotations":{"marks":[{"x":22,"y":29,"rx":9,"ry":19,"label":"弥漫粟粒样小结节","detail":"代表区域内散布密集、大小近似的灰白小结节，需放眼全肺确认分布。"}],"note":"应与肺转移瘤大小悬殊的球形结节作整体比较。"}},{"id":"g026","name":"溃疡型肠结核","kind":"大体","system":"感染与寄生虫","image":"assets/g026.jpg","points":["肠溃疡横行或环形，长轴与肠长轴垂直。","肠黏膜见横行或环形溃疡。","溃疡长轴大致与肠管长轴垂直。"],"caution":"","review":"reviewed","options":[{"text":"溃疡型肠结核","reason":"符合本图：肠溃疡横行或环形，长轴与肠长轴垂直。"},{"text":"肠阿米巴病","reason":"鉴别要点：散在小口溃疡，黏膜下破坏可比开口宽。"},{"text":"肠伤寒","reason":"鉴别要点：长椭圆形肠溃疡，其长轴平行肠管。"},{"text":"细菌性痢疾（假膜性肠炎）","reason":"鉴别要点：弥漫肠黏膜假膜及浅表不规则溃疡。"}],"scope":"core","imageWidth":785,"imageHeight":1073,"annotations":{"marks":[{"x":47,"y":53,"rx":29,"ry":13,"label":"横行溃疡区域","detail":"主要黏膜缺损横向展开，长轴与图中上下走行的肠管长轴大致垂直。"}],"note":""}},{"id":"g027","name":"结核性肉芽肿","kind":"镜下","system":"感染与寄生虫","image":"assets/g027.jpg","points":["中央干酪样坏死，外围细胞性肉芽肿。","组织中出现多发结节状肉芽肿。","中心可见淡染、无结构的干酪样坏死。"],"caution":"本图倍率较低，朗汉斯巨细胞细节需高倍确认；干酪样坏死并非结核独有。","review":"reviewed","options":[{"text":"结核性肉芽肿","reason":"符合本图：中央干酪样坏死，外围细胞性肉芽肿。"},{"text":"血吸虫虫卵肉芽肿","reason":"鉴别要点：虫卵位于结节中心，周围为肉芽肿反应。"},{"text":"异物肉芽肿","reason":"鉴别要点：通常围绕可辨异物形成多核巨细胞反应；本图应先确认有无干酪样坏死及上皮样细胞结节。"},{"text":"结节病肉芽肿","reason":"鉴别要点：典型为界清、非坏死性上皮样细胞肉芽肿；大片干酪样坏死更支持其他病因。"}],"scope":"core","imageWidth":1269,"imageHeight":1036,"annotations":{"marks":[{"x":40,"y":25,"rx":8,"ry":7,"label":"中央淡染坏死","detail":"肉芽肿中心较淡、缺少正常组织结构，符合干酪样坏死的低倍外观。"},{"x":52,"y":35,"rx":6,"ry":10,"label":"外围细胞性组织","detail":"坏死周围更深染、细胞较密集，体现坏死核心与外围肉芽肿反应的层次。"}],"note":"此倍率不能可靠辨认单个朗汉斯巨细胞；干酪样坏死并非结核独有。"}},{"id":"g028","name":"肺结核球","kind":"大体","system":"感染与寄生虫","image":"assets/g028.jpg","points":["肺内界清圆形结节、灰黄干酪样核心。","肺切面有圆形或类圆形、界限较清楚的结节。","结节中心为灰黄、干燥样坏死物，可有层状外观。"],"caution":"","review":"reviewed","options":[{"text":"肺结核球","reason":"符合本图：肺内界清圆形结节、灰黄干酪样核心。"},{"text":"肺粟粒性结核","reason":"鉴别要点：全肺散在密集、大小近似的粟粒样结节。"},{"text":"小叶性肺炎（支气管肺炎）","reason":"鉴别要点：散在、大小不等的支气管周围斑片实变。"},{"text":"肺癌","reason":"鉴别要点：常见不规则实性或浸润性肿块，可坏死；应与结核球的干酪样核心、纤维包裹鉴别，最终需镜下。"}],"scope":"core","imageWidth":929,"imageHeight":1008,"annotations":{"marks":[{"x":35,"y":48,"rx":9,"ry":9,"label":"灰黄干酪样结节","detail":"圆形病灶与周围肺组织界限较清，内部呈灰黄坏死样物，可见层状外观。"}],"note":""}},{"id":"g029","name":"肠阿米巴病","kind":"大体","system":"感染与寄生虫","image":"assets/g029.jpg","points":["散在小口溃疡，黏膜下破坏可比开口宽。","肠黏膜有散在、大小不等的小口状或针孔样溃疡。","溃疡之间可保留较多正常黏膜。"],"caution":"烧瓶状是断面/镜下特征；本照片主要显示黏膜面的小溃疡口，不能声称已直接见到完整烧瓶形。","review":"reviewed","options":[{"text":"肠阿米巴病","reason":"符合本图：散在小口溃疡，黏膜下破坏可比开口宽。"},{"text":"溃疡型肠结核","reason":"鉴别要点：肠溃疡横行或环形，长轴与肠长轴垂直。"},{"text":"肠伤寒","reason":"鉴别要点：长椭圆形肠溃疡，其长轴平行肠管。"},{"text":"细菌性痢疾（假膜性肠炎）","reason":"鉴别要点：弥漫肠黏膜假膜及浅表不规则溃疡。"}],"scope":"core","imageWidth":1053,"imageHeight":939,"annotations":{"marks":[{"x":48,"y":53,"rx":19,"ry":15,"label":"散在小溃疡口","detail":"黏膜表面可见多个深色小口状缺损，开口之间保留较多黏膜。"}],"note":"本图为黏膜面，未显示完整的烧瓶状溃疡断面。"}},{"id":"g030","name":"阿米巴肝脓肿","kind":"大体","system":"感染与寄生虫","image":"assets/g030.jpg","points":["肝内不规则坏死腔，壁呈破絮状。","肝内形成较大的坏死空腔。","腔壁粗糙、参差不齐，可呈破絮状。"],"caution":"本题为已知诊断标本。图中仅见腔壁与坏死，不能独立确定病原；固定后内容物和颜色可能缺失。","review":"reviewed","options":[{"text":"阿米巴肝脓肿","reason":"符合本图：肝内不规则坏死腔，壁呈破絮状。"},{"text":"化脓性肝脓肿","reason":"鉴别要点：常为黄色或黄绿色脓液，单发或多发；病原需进一步检查，不能仅凭空腔认定阿米巴。"},{"text":"肝囊肿","reason":"鉴别要点：囊壁通常薄而平滑，内为液体，不见这种不规则、坏死破絮状腔壁。"},{"text":"原发性肝癌（巨块型）","reason":"鉴别要点：肝切面由一个巨大、边界不规则的肿块主导。"}],"scope":"core","imageWidth":863,"imageHeight":1031,"annotations":{"marks":[{"x":58,"y":55,"rx":19,"ry":25,"label":"破絮状坏死腔壁","detail":"肝内大空腔的壁面粗糙、碎絮状，正常致密肝组织在这里被破坏。"}],"note":"坏死腔壁不能独立确定病原。"}},{"id":"g031","name":"肠伤寒","kind":"大体","system":"感染与寄生虫","image":"assets/g031.jpg","points":["长椭圆形肠溃疡，其长轴平行肠管。","肠壁见长椭圆形溃疡，常沿集合淋巴小结分布。","溃疡的长轴与肠管长轴平行。"],"caution":"","review":"reviewed","options":[{"text":"肠伤寒","reason":"符合本图：长椭圆形肠溃疡，其长轴平行肠管。"},{"text":"溃疡型肠结核","reason":"鉴别要点：肠溃疡横行或环形，长轴与肠长轴垂直。"},{"text":"肠阿米巴病","reason":"鉴别要点：散在小口溃疡，黏膜下破坏可比开口宽。"},{"text":"细菌性痢疾（假膜性肠炎）","reason":"鉴别要点：弥漫肠黏膜假膜及浅表不规则溃疡。"}],"scope":"core","imageWidth":569,"imageHeight":879,"annotations":{"marks":[{"x":54,"y":44,"rx":7,"ry":10,"label":"长椭圆形肠壁病灶","detail":"原箭头所指病灶长轴沿肠管上下方向，与肠结核横行病变作比较。"}],"note":"隆起表面不全是黏膜已脱落的溃疡底。"}},{"id":"g032","name":"细菌性痢疾（假膜性肠炎）","kind":"大体","system":"感染与寄生虫","image":"assets/g032.jpg","points":["弥漫肠黏膜假膜及浅表不规则溃疡。","结肠黏膜表面广泛粗糙，覆盖灰白色假膜样物。","假膜脱落后可出现浅表、不规则溃疡。"],"caution":"本题为已知诊断标本。假膜性肠炎有多种病因，单靠大体不能确定痢疾杆菌。","review":"reviewed","options":[{"text":"细菌性痢疾（假膜性肠炎）","reason":"符合本图：弥漫肠黏膜假膜及浅表不规则溃疡。"},{"text":"溃疡型肠结核","reason":"鉴别要点：肠溃疡横行或环形，长轴与肠长轴垂直。"},{"text":"肠阿米巴病","reason":"鉴别要点：散在小口溃疡，黏膜下破坏可比开口宽。"},{"text":"肠伤寒","reason":"鉴别要点：长椭圆形肠溃疡，其长轴平行肠管。"}],"scope":"core","imageWidth":383,"imageHeight":839,"annotations":{"marks":[{"x":51,"y":78,"rx":23,"ry":14,"label":"粗糙的黏膜与覆膜","detail":"圈内为代表区域：黏膜面广泛粗糙、灰白覆盖，与光整黏膜形成区别。"}],"note":"原图清晰度有限，适合看整体覆膜模式，不宜精确区分每个浅溃疡；病原不能由此确定。"}},{"id":"g033","name":"血吸虫虫卵肉芽肿","kind":"镜下","system":"感染与寄生虫","image":"assets/g033.jpg","points":["虫卵位于结节中心，周围为肉芽肿反应。","结节中心聚集数个椭圆形虫卵断面。","虫卵周围有炎细胞、上皮样细胞及纤维组织反应。"],"caution":"","review":"reviewed","options":[{"text":"血吸虫虫卵肉芽肿","reason":"符合本图：虫卵位于结节中心，周围为肉芽肿反应。"},{"text":"结核性肉芽肿","reason":"鉴别要点：中央干酪样坏死，外围细胞性肉芽肿。"},{"text":"风湿小体（Aschoff 小体）","reason":"鉴别要点：心肌间质风湿细胞围绕中央纤维素样坏死。"},{"text":"硅肺（硅结节）","reason":"鉴别要点：致密胶原玻璃样变形成同心圆或旋涡状硅结节。"}],"scope":"core","imageWidth":1267,"imageHeight":836,"annotations":{"marks":[{"x":41,"y":50,"rx":9,"ry":13,"label":"结节中心虫卵断面","detail":"中央深染区内有多个圆形或椭圆形虫卵轮廓，是这类肉芽肿的关键定位点。"},{"x":71,"y":45,"rx":10,"ry":25,"label":"外围肉芽肿反应","detail":"虫卵外围可见细胞性反应及纤维组织，形成围绕病原的结节结构。"}],"note":""}},{"id":"g034","name":"肝梅毒树胶样肿","kind":"大体","system":"感染与寄生虫","image":"assets/g034.jpg","points":["灰白坏死结节伴纤维瘢痕牵拉，病因依原标本。","肝表面及切面有灰白、灰黄色结节状病灶。","病灶可有中央坏死及周边纤维化，牵拉肝脏变形。"],"caution":"本题为已知诊断标本。照片所见并非梅毒特异，需结合病原学或临床背景。","review":"reviewed","options":[{"text":"肝梅毒树胶样肿","reason":"符合本图：灰白坏死结节伴纤维瘢痕牵拉，病因依原标本。"},{"text":"阿米巴肝脓肿","reason":"鉴别要点：肝内不规则坏死腔，壁呈破絮状。"},{"text":"原发性肝癌（巨块型）","reason":"鉴别要点：肝切面由一个巨大、边界不规则的肿块主导。"},{"text":"大结节性肝硬化","reason":"鉴别要点：肝表面及切面被较大的结节分割。"}],"scope":"core","imageWidth":649,"imageHeight":1045,"annotations":{"marks":[{"x":40,"y":31,"rx":17,"ry":14,"label":"灰白结节与纤维分隔","detail":"肝内多个浅色结节被纤维性条带分隔，并造成局部轮廓不规则。"}],"note":"这些大体改变不特异，不能仅凭结节确诊梅毒。"}},{"id":"g035","name":"尖锐湿疣","kind":"镜下","system":"感染与寄生虫","image":"assets/g035.jpg","points":["鳞状上皮凹空细胞：核周晕加核异常。","鳞状上皮中可见核周透明晕，形成凹空细胞。","核增大、深染，可见双核；伴棘层增厚。"],"caution":"","review":"reviewed","options":[{"text":"尖锐湿疣","reason":"符合本图：鳞状上皮凹空细胞：核周晕加核异常。"},{"text":"皮肤鳞状乳头状瘤","reason":"鉴别要点：可有乳头状增生，但缺少典型 HPV 相关凹空细胞的核周晕、核深染和双核组合。"},{"text":"单纯鳞状上皮增生","reason":"鉴别要点：主要为上皮层次增多；有增厚不等于已经见到凹空细胞或癌。"},{"text":"食管鳞状细胞癌","reason":"鉴别要点：浸润性鳞状癌巢内形成角化珠。"}],"scope":"core","imageWidth":1019,"imageHeight":913,"annotations":{"marks":[{"x":33,"y":35,"rx":4,"ry":5,"label":"凹空细胞","detail":"细胞核周围出现明显透明晕，同时核较大、深染，不能只看空泡。"},{"x":46,"y":13,"rx":4,"ry":5,"label":"另一处核周透明晕","detail":"同类改变在鳞状上皮中反复出现，结合核异常识别。"}],"note":""}},{"id":"g036","name":"高血压性心脏肥大","kind":"大体","system":"心血管系统","image":"assets/g036.jpg","points":["左室壁和肉柱增厚，表现为压力负荷性肥厚。","左心室壁及肉柱明显增厚。","心室肌呈同心性肥大表现，室腔早期可相对狭小。"],"caution":"本题给定长期高血压背景；主动脉瓣狭窄等也可造成左室肥厚。","review":"reviewed","options":[{"text":"高血压性心脏肥大","reason":"符合本图：左室壁和肉柱增厚，表现为压力负荷性肥厚。"},{"text":"肥厚型心肌病","reason":"鉴别要点：可有不对称室间隔肥厚、流出道梗阻，显微镜下肌纤维排列紊乱；仅心肌厚不能排定病因。"},{"text":"扩张型心肌病","reason":"鉴别要点：主要表现为心腔显著扩张、心脏球形增大，与同心性压力负荷肥厚不同。"},{"text":"心肌梗死","reason":"鉴别要点：主要见局灶心肌坏死或瘢痕，通常不是单纯均匀左室壁增厚。"}],"scope":"core","imageWidth":484,"imageHeight":534,"annotations":{"marks":[{"x":33,"y":61,"rx":10,"ry":22,"label":"增厚的左心室壁","detail":"左室游离壁呈厚实肌层，与内侧狭长心室腔作对照。"},{"x":54,"y":65,"rx":7,"ry":12,"label":"粗大的乳头肌与肉柱","detail":"腔内肌性结构粗大，与室壁肥厚共同支持心肌肥大。"}],"note":"照片显示压力负荷性肥厚；高血压为本题给定背景。"}},{"id":"g037","name":"脾中央小动脉玻璃样变","kind":"镜下","system":"心血管系统","image":"assets/g037.jpg","points":["淋巴组织内小动脉壁均质粉红、无结构，明显增厚，管腔缩窄。"],"caution":"","review":"reviewed","options":[{"text":"脾中央小动脉玻璃样变","reason":"符合本图：小动脉壁均质红染增厚、管腔缩窄。"},{"text":"小动脉纤维素样坏死","reason":"鉴别要点：管壁出现强嗜酸性坏死物及壁结构破坏，常有急性损伤背景，不同于均质玻璃样增厚。"},{"text":"增生性小动脉硬化","reason":"鉴别要点：可见管壁同心圆洋葱皮样增生，而不是单一均质玻璃样物沉积。"},{"text":"血管腔内血栓","reason":"鉴别要点：病变位于管腔内，由血小板、纤维蛋白及血细胞等组成；玻璃样变主要在血管壁。"}],"scope":"core","imageWidth":1161,"imageHeight":819,"annotations":{"marks":[{"x":50,"y":57,"rx":15,"ry":21,"label":"玻璃样增厚的小动脉","detail":"中央血管壁均质粉红、明显增厚，残留管腔很小，周围为深染淋巴细胞。"}],"note":""}},{"id":"g038","name":"肾细动脉硬化（玻璃样变）","kind":"镜下","system":"心血管系统","image":"assets/g038.jpg","points":["肾细动脉壁玻璃样增厚加肾缺血改变。","肾实质中小血管壁增厚、均质红染，管腔缩窄。","周围可伴肾小球缺血性萎缩及小管改变。"],"caution":"高血压和糖尿病等均可出现细动脉玻璃样变；本题不靠单张图判断唯一病因。","review":"reviewed","options":[{"text":"肾细动脉硬化（玻璃样变）","reason":"符合本图：肾细动脉壁玻璃样增厚加肾缺血改变。"},{"text":"小动脉纤维素样坏死","reason":"鉴别要点：管壁出现强嗜酸性坏死物及壁结构破坏，常有急性损伤背景，不同于均质玻璃样增厚。"},{"text":"增生性小动脉硬化","reason":"鉴别要点：可见管壁同心圆洋葱皮样增生，而不是单一均质玻璃样物沉积。"},{"text":"膜性肾病","reason":"鉴别要点：毛细血管壁弥漫增厚，细胞增生不突出。"}],"scope":"core","imageWidth":1233,"imageHeight":985,"annotations":{"marks":[{"x":50,"y":20,"rx":4,"ry":4,"label":"细动脉玻璃样增厚","detail":"原箭头所指小血管壁呈均质粉红色，厚壁包围狭小管腔。"},{"x":46,"y":62,"rx":4,"ry":3,"label":"另一处同类细动脉","detail":"下方另一小血管也呈厚壁、窄腔，提示应寻找血管而非把所有粉红小管都当成病灶。"}],"note":"玻璃样变不等于高血压的唯一特异证据。"}},{"id":"g039","name":"动脉粥样硬化（粥样斑块）","kind":"镜下","system":"心血管系统","image":"assets/g039.jpg","points":["针状胆固醇裂隙和坏死脂质核心。","病变区见大量细长针状裂隙，为胆固醇结晶溶出后的空隙。","周围有无结构坏死物，可伴蓝紫色钙盐沉积。"],"caution":"","review":"reviewed","options":[{"text":"动脉粥样硬化（粥样斑块）","reason":"符合本图：针状胆固醇裂隙和坏死脂质核心。"},{"text":"小动脉纤维素样坏死","reason":"鉴别要点：管壁出现强嗜酸性坏死物及壁结构破坏，常有急性损伤背景，不同于均质玻璃样增厚。"},{"text":"血管腔内血栓","reason":"鉴别要点：病变位于管腔内，由血小板、纤维蛋白及血细胞等组成；玻璃样变主要在血管壁。"},{"text":"脾中央小动脉玻璃样变","reason":"鉴别要点：小动脉壁均质红染增厚、管腔缩窄。"}],"scope":"core","imageWidth":1269,"imageHeight":650,"annotations":{"marks":[{"x":35,"y":39,"rx":13,"ry":16,"label":"针状胆固醇裂隙","detail":"浅染坏死区有成束细长空隙，是制片时胆固醇溶出所留下的轮廓。"},{"x":86,"y":73,"rx":10,"ry":8,"label":"深染钙盐沉积","detail":"斑块底部出现深蓝紫色团块状沉积，与上方裂隙共同提示复杂粥样斑块。"}],"note":""}},{"id":"g040","name":"主动脉粥样硬化","kind":"大体","system":"心血管系统","image":"assets/g040.jpg","points":["动脉内膜多发黄白色隆起斑块。","主动脉内膜出现多发隆起的灰黄或黄白色斑块。","斑块可融合，表面不平，伴溃疡及钙化。"],"caution":"","review":"reviewed","options":[{"text":"主动脉粥样硬化","reason":"符合本图：动脉内膜多发黄白色隆起斑块。"},{"text":"冠状动脉粥样硬化","reason":"鉴别要点：病变沿冠状动脉内膜分布并使管腔变窄。"},{"text":"血管腔内血栓","reason":"鉴别要点：病变位于管腔内，由血小板、纤维蛋白及血细胞等组成；玻璃样变主要在血管壁。"},{"text":"增生性小动脉硬化","reason":"鉴别要点：可见管壁同心圆洋葱皮样增生，而不是单一均质玻璃样物沉积。"}],"scope":"core","imageWidth":559,"imageHeight":781,"annotations":{"marks":[{"x":73,"y":56,"rx":9,"ry":10,"label":"黄白隆起斑块","detail":"原指针附近黄白斑块高出较平坦的内膜，并与其他斑块融合。"}],"note":"应看全段动脉内膜的多发分布，孔状血管开口本身不是溃疡。"}},{"id":"g041","name":"冠状动脉粥样硬化","kind":"大体","system":"心血管系统","image":"assets/g041.jpg","points":["病变沿冠状动脉内膜分布并使管腔变窄。","先沿心外膜表面辨认冠状动脉走行。","冠状动脉壁有黄白色增厚斑块，管腔狭窄或闭塞。"],"caution":"","review":"reviewed","options":[{"text":"冠状动脉粥样硬化","reason":"符合本图：病变沿冠状动脉内膜分布并使管腔变窄。"},{"text":"血管腔内血栓","reason":"鉴别要点：病变位于管腔内，由血小板、纤维蛋白及血细胞等组成；玻璃样变主要在血管壁。"},{"text":"主动脉粥样硬化","reason":"鉴别要点：动脉内膜多发黄白色隆起斑块。"},{"text":"心肌梗死","reason":"鉴别要点：主要见局灶心肌坏死或瘢痕，通常不是单纯均匀左室壁增厚。"}],"scope":"core","imageWidth":1071,"imageHeight":1159,"annotations":{"marks":[{"x":46,"y":45,"rx":7,"ry":8,"label":"剖开的冠状动脉病变","detail":"原指针附近暴露的血管壁灰黄增厚，沿冠状动脉走行辨认病变。"}],"note":"周围黄色组织包括心外膜脂肪，不能都当作粥样斑块；照片不宜用于量化狭窄百分比。"}},{"id":"g042","name":"纤维素性心包炎（绒毛心）","kind":"大体","system":"心血管系统","image":"assets/g042.jpg","points":["心包表面粗糙绒毛状纤维蛋白渗出。","心外膜表面覆盖灰白、粗糙的渗出物。","渗出物形成绒毛状、丝絮状或面包黄油样外观。"],"caution":"传统教材称纤维素性炎，此处物质实为纤维蛋白；绒毛心并非风湿病独有。","review":"reviewed","options":[{"text":"纤维素性心包炎（绒毛心）","reason":"符合本图：心包表面粗糙绒毛状纤维蛋白渗出。"},{"text":"化脓性心包炎","reason":"鉴别要点：心包内及表面以黄白脓性渗出为主，而非典型细长绒毛状纤维蛋白。"},{"text":"缩窄性心包炎","reason":"鉴别要点：主要为慢性心包纤维增厚、粘连及钙化，限制心脏舒张。"},{"text":"风湿性心内膜炎","reason":"鉴别要点：瓣膜关闭缘细小、串珠状赘生物。"}],"scope":"core","imageWidth":673,"imageHeight":907,"annotations":{"marks":[{"x":54,"y":51,"rx":22,"ry":20,"label":"心外膜粗糙覆膜","detail":"心脏表面被灰黄、粗糙的纤维蛋白性物质覆盖，失去光滑外观。"}],"note":"纤维素性心包炎并非风湿病独有。"}},{"id":"g043","name":"风湿性心内膜炎","kind":"大体","system":"心血管系统","image":"assets/g043.jpg","points":["瓣膜关闭缘细小、串珠状赘生物。","瓣膜关闭缘附近附着细小疣状赘生物。","赘生物较整齐，呈串珠样排列。"],"caution":"","review":"reviewed","options":[{"text":"风湿性心内膜炎","reason":"符合本图：瓣膜关闭缘细小、串珠状赘生物。"},{"text":"感染性心内膜炎（大体）","reason":"鉴别要点：常为较大、脆、形态不规则的赘生物，伴瓣膜破坏；与沿关闭缘细小串珠样赘生物比较。"},{"text":"风湿性二尖瓣狭窄","reason":"鉴别要点：瓣叶增厚粘连，瓣口缩窄呈鱼口状。"},{"text":"纤维素性心包炎（绒毛心）","reason":"鉴别要点：心包表面粗糙绒毛状纤维蛋白渗出。"}],"scope":"core","imageWidth":957,"imageHeight":1085,"annotations":{"marks":[{"x":64,"y":50,"rx":8,"ry":3,"label":"瓣膜关闭缘小赘生物","detail":"原箭头下方一列细小黄褐色结节沿瓣膜关闭缘排列，呈串珠样。"}],"note":"此处应放大观察，避免把下方细长腱索当作赘生物。"}},{"id":"g044","name":"风湿性二尖瓣狭窄","kind":"大体","system":"心血管系统","image":"assets/g044.jpg","points":["瓣叶增厚粘连，瓣口缩窄呈鱼口状。","从心房侧观察，二尖瓣口明显缩窄。","瓣叶增厚、粘连，瓣口可呈鱼口状。"],"caution":"","review":"reviewed","options":[{"text":"风湿性二尖瓣狭窄","reason":"符合本图：瓣叶增厚粘连，瓣口缩窄呈鱼口状。"},{"text":"感染性心内膜炎（大体）","reason":"鉴别要点：常为较大、脆、形态不规则的赘生物，伴瓣膜破坏；与沿关闭缘细小串珠样赘生物比较。"},{"text":"风湿性心内膜炎","reason":"鉴别要点：瓣膜关闭缘细小、串珠状赘生物。"},{"text":"扩张型心肌病","reason":"鉴别要点：主要表现为心腔显著扩张、心脏球形增大，与同心性压力负荷肥厚不同。"}],"scope":"core","imageWidth":985,"imageHeight":873,"annotations":{"marks":[{"x":53,"y":47,"rx":12,"ry":5,"label":"狭窄的二尖瓣口","detail":"原箭头附近仅剩狭小开口，周围瓣叶厚实并粘连，呈鱼口样狭窄。"}],"note":""}},{"id":"g045","name":"风湿小体（Aschoff 小体）","kind":"镜下","system":"心血管系统","image":"assets/g045.jpg","points":["心肌间质风湿细胞围绕中央纤维素样坏死。","心肌间质出现局灶性肉芽肿样病变。","中心为嗜酸性纤维素样坏死，周围有较大的风湿细胞。"],"caution":"此处为纤维素样坏死（纤维蛋白样坏死），须与心包表面的纤维蛋白渗出区分。","review":"reviewed","options":[{"text":"风湿小体（Aschoff 小体）","reason":"符合本图：心肌间质风湿细胞围绕中央纤维素样坏死。"},{"text":"感染性心内膜炎","reason":"鉴别要点：赘生物内细菌菌落加破坏性炎症。"},{"text":"结核性肉芽肿","reason":"鉴别要点：中央干酪样坏死，外围细胞性肉芽肿。"},{"text":"巨细胞性心肌炎","reason":"鉴别要点：可见巨细胞伴较广泛心肌坏死及炎症，不以典型 Aschoff 小体结构为核心。"}],"scope":"core","imageWidth":830,"imageHeight":963,"annotations":{"marks":[{"x":52,"y":52,"rx":10,"ry":12,"label":"小体内较大的风湿细胞","detail":"心肌间质反应区中有胞体、核明显增大的细胞，是寻找风湿小体的线索。"},{"x":14,"y":39,"rx":8,"ry":16,"label":"邻近心肌","detail":"左侧保留条带状嗜酸性心肌纤维，帮助确认异常细胞团位于心肌间质。"}],"note":"此图核纹理模糊，不能可靠辨认典型毛虫核。"}},{"id":"g046","name":"感染性心内膜炎","kind":"镜下","system":"心血管系统","image":"assets/g046.jpg","points":["赘生物内细菌菌落加破坏性炎症。","瓣膜表面形成由纤维蛋白、坏死物及炎细胞构成的赘生物。","赘生物内可见深染的团块状细菌菌落。"],"caution":"","review":"reviewed","options":[{"text":"感染性心内膜炎","reason":"符合本图：赘生物内细菌菌落加破坏性炎症。"},{"text":"风湿小体（Aschoff 小体）","reason":"鉴别要点：心肌间质风湿细胞围绕中央纤维素样坏死。"},{"text":"血管腔内血栓","reason":"鉴别要点：病变位于管腔内，由血小板、纤维蛋白及血细胞等组成；玻璃样变主要在血管壁。"},{"text":"动脉粥样硬化（粥样斑块）","reason":"鉴别要点：针状胆固醇裂隙和坏死脂质核心。"}],"scope":"core","imageWidth":1154,"imageHeight":584,"annotations":{"marks":[{"x":67,"y":15,"rx":8,"ry":6,"label":"赘生物内深染菌落","detail":"表浅部见多团蓝紫色致密小团块，区别于周围粉红色纤维蛋白和坏死物。"},{"x":45,"y":51,"rx":20,"ry":21,"label":"纤维蛋白与坏死背景","detail":"大片淡粉红、结构模糊的物质构成赘生物主体，需与其内菌落一起看。"}],"note":"这是低倍定位，单个细菌形态不由此图判定。"}},{"id":"g047","name":"大叶性肺炎（灰色肝样变期）","kind":"大体","system":"呼吸系统","image":"assets/g047.jpg","points":["整叶较均匀灰色实变、呈肝样。","病变肺叶大片、较均匀地实变，灰白或灰褐色。","切面致密、颗粒样，质地呈肝样。"],"caution":"","review":"reviewed","options":[{"text":"大叶性肺炎（灰色肝样变期）","reason":"符合本图：整叶较均匀灰色实变、呈肝样。"},{"text":"小叶性肺炎（支气管肺炎）","reason":"鉴别要点：散在、大小不等的支气管周围斑片实变。"},{"text":"肺粟粒性结核","reason":"鉴别要点：全肺散在密集、大小近似的粟粒样结节。"},{"text":"单纯肺淤血","reason":"鉴别要点：主要见肺泡隔毛细血管充血、肺泡内红细胞及含铁血黄素细胞；不等于充满纤维蛋白的细菌性肺炎。"}],"scope":"core","imageWidth":783,"imageHeight":957,"annotations":{"marks":[{"x":58,"y":62,"rx":17,"ry":22,"label":"大片灰色实变","detail":"下方肺叶切面较均一、灰白而致密，与上方深色肺组织形成明显对比。"}],"note":""}},{"id":"g049","name":"大叶性肺炎（灰色肝样变期）","kind":"镜下","system":"呼吸系统","image":"assets/g049.jpg","points":["肺泡腔充满中性粒细胞和纤维蛋白。","肺泡腔内充满中性粒细胞及纤维蛋白渗出。","肺泡隔仍可辨认，渗出主要在肺泡腔。"],"caution":"","review":"reviewed","options":[{"text":"大叶性肺炎（灰色肝样变期）","reason":"符合本图：肺泡腔充满中性粒细胞和纤维蛋白。"},{"text":"大叶性肺炎（红色肝样变期）","reason":"鉴别要点：红色肝样变重点是充血、肺泡腔红细胞与纤维蛋白。"},{"text":"间质性肺炎","reason":"鉴别要点：肺泡隔宽、炎细胞多，肺泡腔相对较空。"},{"text":"肺水肿","reason":"鉴别要点：肺泡腔内多为淡红色、较均匀的水肿液，不以大量中性粒细胞及支气管周围化脓为主。"}],"scope":"core","imageWidth":1108,"imageHeight":1007,"annotations":{"marks":[{"x":50,"y":49,"rx":28,"ry":29,"label":"肺泡腔内炎性渗出","detail":"肺泡腔被大量分叶核炎细胞与粉红纤维状物充填，重点在腔内而非仅肺泡隔。"},{"x":9,"y":49,"rx":4,"ry":15,"label":"可辨认的肺泡隔","detail":"左侧细长肺泡壁仍可辨，帮助划清肺泡腔与肺泡间隔的位置。"}],"note":""}},{"id":"g050","name":"小叶性肺炎（支气管肺炎）","kind":"大体","system":"呼吸系统","image":"assets/g050.jpg","points":["散在、大小不等的支气管周围斑片实变。","肺切面散布多个灰黄、灰白色斑片状实变灶。","病灶常以细支气管为中心，大小不一，可相互融合。"],"caution":"","review":"reviewed","options":[{"text":"小叶性肺炎（支气管肺炎）","reason":"符合本图：散在、大小不等的支气管周围斑片实变。"},{"text":"大叶性肺炎（灰色肝样变期）","reason":"鉴别要点：整叶较均匀灰色实变、呈肝样。"},{"text":"肺粟粒性结核","reason":"鉴别要点：全肺散在密集、大小近似的粟粒样结节。"},{"text":"肺癌","reason":"鉴别要点：常见不规则实性或浸润性肿块，可坏死；应与结核球的干酪样核心、纤维包裹鉴别，最终需镜下。"}],"scope":"core","imageWidth":469,"imageHeight":1019,"annotations":{"marks":[{"x":55,"y":29,"rx":20,"ry":13,"label":"散在斑片实变灶","detail":"多个灰黄灶围绕小气道分布，大小不一且病灶间尚有较深色肺组织。"}],"note":"与大叶性肺炎整叶较均匀的实变作分布比较。"}},{"id":"g051","name":"小叶性肺炎（支气管肺炎）","kind":"镜下","system":"呼吸系统","image":"assets/g051.jpg","points":["支气管和周围肺泡内中性粒细胞渗出。","细支气管腔内及周围肺泡充满炎性渗出物。","炎细胞以中性粒细胞为主，呈化脓性炎症。"],"caution":"","review":"reviewed","options":[{"text":"小叶性肺炎（支气管肺炎）","reason":"符合本图：支气管和周围肺泡内中性粒细胞渗出。"},{"text":"大叶性肺炎（灰色肝样变期）","reason":"鉴别要点：肺泡腔充满中性粒细胞和纤维蛋白。"},{"text":"间质性肺炎","reason":"鉴别要点：肺泡隔宽、炎细胞多，肺泡腔相对较空。"},{"text":"肺水肿","reason":"鉴别要点：肺泡腔内多为淡红色、较均匀的水肿液，不以大量中性粒细胞及支气管周围化脓为主。"}],"scope":"core","imageWidth":1267,"imageHeight":653,"annotations":{"marks":[{"x":68,"y":55,"rx":7,"ry":10,"label":"细支气管腔内脓性渗出","detail":"圆形小气道腔内充满深染炎细胞，外围仍可辨气道壁。"},{"x":59,"y":28,"rx":11,"ry":17,"label":"周围肺泡炎性实变","detail":"邻近肺泡也被炎细胞占据，与远处较空的肺泡对比，体现以气道为中心的分布。"}],"note":""}},{"id":"g052","name":"间质性肺炎","kind":"镜下","system":"呼吸系统","image":"assets/g052.jpg","points":["肺泡隔宽、炎细胞多，肺泡腔相对较空。","肺泡隔弥漫增宽，细胞增多。","炎细胞主要位于肺泡隔内，而肺泡腔相对较空。"],"caution":"间质性肺炎是形态模式，单凭此图不能确定某一种病毒或病原体。","review":"reviewed","options":[{"text":"间质性肺炎","reason":"符合本图：肺泡隔宽、炎细胞多，肺泡腔相对较空。"},{"text":"大叶性肺炎（灰色肝样变期）","reason":"鉴别要点：肺泡腔充满中性粒细胞和纤维蛋白。"},{"text":"小叶性肺炎（支气管肺炎）","reason":"鉴别要点：支气管和周围肺泡内中性粒细胞渗出。"},{"text":"硅肺（硅结节）","reason":"鉴别要点：致密胶原玻璃样变形成同心圆或旋涡状硅结节。"}],"scope":"core","imageWidth":1267,"imageHeight":886,"annotations":{"marks":[{"x":40,"y":28,"rx":6,"ry":13,"label":"增宽的肺泡隔","detail":"肺泡之间的组织带变宽，深染细胞增多，炎症重点位于间隔内。"},{"x":29,"y":23,"rx":7,"ry":10,"label":"相对空的肺泡腔","detail":"邻近肺泡腔仍大多空白，与腔内大量化脓性渗出的肺炎作对照。"}],"note":"形态模式不能确定具体病毒或其他病原。"}},{"id":"g053","name":"硅肺（硅结节）","kind":"镜下","system":"呼吸系统","image":"assets/g053.jpg","points":["致密胶原玻璃样变形成同心圆或旋涡状硅结节。","肺组织内可见多个界限较清楚的结节。","结节由致密、玻璃样变的胶原构成，可呈同心圆或旋涡状。"],"caution":"","review":"reviewed","options":[{"text":"硅肺（硅结节）","reason":"符合本图：致密胶原玻璃样变形成同心圆或旋涡状硅结节。"},{"text":"结核性肉芽肿","reason":"鉴别要点：中央干酪样坏死，外围细胞性肉芽肿。"},{"text":"间质性肺炎","reason":"鉴别要点：肺泡隔宽、炎细胞多，肺泡腔相对较空。"},{"text":"血吸虫虫卵肉芽肿","reason":"鉴别要点：虫卵位于结节中心，周围为肉芽肿反应。"}],"scope":"core","imageWidth":1267,"imageHeight":832,"annotations":{"marks":[{"x":47,"y":62,"rx":14,"ry":14,"label":"旋涡样胶原结节","detail":"结节内致密粉红胶原呈旋涡或同心性排列，周围还能看到肺泡结构。"}],"note":""}},{"id":"g054","name":"慢性萎缩性胃炎","kind":"大体","system":"消化系统","image":"assets/g054.jpg","points":["胃黏膜变薄、皱襞减少，血管可透见。","胃黏膜皱襞变低、减少或消失。","黏膜较薄、平坦，严重时可透见黏膜下血管。"],"caution":"","review":"reviewed","options":[{"text":"慢性萎缩性胃炎","reason":"符合本图：胃黏膜变薄、皱襞减少，血管可透见。"},{"text":"慢性胃溃疡","reason":"鉴别要点：规则溃疡加皱襞向中心集中。"},{"text":"胃癌（弥漫浸润型，革囊胃）","reason":"鉴别要点：胃壁弥漫性增厚，整个胃轮廓变得僵硬、收缩。"},{"text":"慢性非萎缩性胃炎","reason":"鉴别要点：胃腺体保留较多，主要为慢性炎细胞浸润；不能把胃黏膜腺体消失及皱襞变平归为非萎缩。"}],"scope":"core","imageWidth":955,"imageHeight":951,"annotations":{"marks":[{"x":52,"y":37,"rx":15,"ry":19,"label":"平坦、皱襞减少的黏膜","detail":"上部黏膜较平坦，正常高耸胃皱襞减少，可隐约见深色血管纹理。"}],"note":"照片不能量化腺体丢失程度。"}},{"id":"g055","name":"胃黏膜肠上皮化生","kind":"镜下","system":"消化系统","image":"assets/g055.jpg","points":["胃黏膜里找杯状细胞，识别肠型分化。","胃腺上皮中出现胞质淡染、含黏液的杯状细胞。","腺体呈肠型上皮分化，可伴慢性炎细胞浸润。"],"caution":"肠化生常伴慢性萎缩性胃炎，但这张局部高倍图不能单独量化全部胃腺萎缩。","review":"reviewed","options":[{"text":"胃黏膜肠上皮化生","reason":"符合本图：胃黏膜里找杯状细胞，识别肠型分化。"},{"text":"胃腺癌（管状型）","reason":"鉴别要点：以异型腺体浸润性生长为主，不能用正常杯状细胞或表面炎症替代癌性结构和细胞异型。"},{"text":"印戒细胞（胃癌）","reason":"鉴别要点：胞内黏液把核挤到一侧，形成印戒形态。"},{"text":"胃黏液腺癌","reason":"鉴别要点：细胞外大片黏液湖中漂浮癌细胞。"}],"scope":"core","imageWidth":1269,"imageHeight":967,"annotations":{"marks":[{"x":77,"y":73,"rx":3,"ry":4,"label":"杯状细胞","detail":"原指针附近腺上皮内有胞质膨大、黏液淡染的杯状细胞，是肠型分化的核心线索。"},{"x":38,"y":59,"rx":7,"ry":9,"label":"成群肠型黏液细胞","detail":"同一腺体上皮内反复出现黏液丰富的细胞，结合胃标本来源识别肠化生。"}],"note":""}},{"id":"g056","name":"慢性胃溃疡","kind":"大体","system":"消化系统","image":"assets/g056.jpg","points":["规则溃疡加皱襞向中心集中。","胃黏膜见较规则圆形或椭圆形缺损。","溃疡周围黏膜皱襞向中心放射状集中。"],"caution":"仅凭外观不能完全排除恶性，需取材检查。","review":"reviewed","options":[{"text":"慢性胃溃疡","reason":"符合本图：规则溃疡加皱襞向中心集中。"},{"text":"胃癌（溃疡型）","reason":"鉴别要点：胃壁见不规则溃疡性病灶。"},{"text":"慢性萎缩性胃炎","reason":"鉴别要点：胃黏膜变薄、皱襞减少，血管可透见。"},{"text":"胃癌（蕈伞型）","reason":"鉴别要点：胃腔内可见局限、明显隆起的肿块。"}],"scope":"core","imageWidth":1269,"imageHeight":843,"annotations":{"marks":[{"x":48,"y":49,"rx":6,"ry":6,"label":"较规则的溃疡底","detail":"中央圆形至椭圆形黏膜缺损轮廓较规则，是主要病灶。"},{"x":56,"y":31,"rx":9,"ry":15,"label":"向溃疡集中的皱襞","detail":"邻近胃皱襞向中央缺损放射状集中，需与溃疡形态一并判断。"}],"note":""}},{"id":"g057","name":"胃溃疡穿孔","kind":"大体","system":"消化系统","image":"assets/g057.jpg","points":["溃疡形成贯穿胃壁的孔洞。","胃壁可见贯穿全层的孔洞。","孔洞周围可见溃疡及向病灶集中的黏膜皱襞。"],"caution":"","review":"reviewed","options":[{"text":"胃溃疡穿孔","reason":"符合本图：溃疡形成贯穿胃壁的孔洞。"},{"text":"胃憩室","reason":"鉴别要点：胃壁向外形成袋状囊腔，通常有相对完整的壁，不是溃疡破坏后贯穿全层的孔洞。"},{"text":"胃癌（溃疡型）","reason":"鉴别要点：胃壁见不规则溃疡性病灶。"},{"text":"胃癌（弥漫浸润型，革囊胃）","reason":"鉴别要点：胃壁弥漫性增厚，整个胃轮廓变得僵硬、收缩。"}],"scope":"core","imageWidth":1268,"imageHeight":865,"annotations":{"marks":[{"x":43,"y":45,"rx":8,"ry":10,"label":"溃疡及穿孔口","detail":"溃疡中心出现贯通的孔洞，周围黏膜及皱襞向病灶汇集。"}],"note":"应识别中央孔口，不把标本切开形成的长切缝全部当作穿孔。"}},{"id":"g058","name":"慢性胃溃疡","kind":"镜下","system":"消化系统","image":"assets/g058.jpg","points":["黏膜缺损，溃疡底依次见渗出、坏死、肉芽和瘢痕组织。"],"caution":"","review":"reviewed","options":[{"text":"慢性胃溃疡","reason":"符合本图：溃疡底依次有渗出、坏死、肉芽和瘢痕层。"},{"text":"胃腺癌（管状型）","reason":"鉴别要点：以异型腺体浸润性生长为主，不能用正常杯状细胞或表面炎症替代癌性结构和细胞异型。"},{"text":"胃黏膜肠上皮化生","reason":"鉴别要点：胃黏膜里找杯状细胞，识别肠型分化。"},{"text":"慢性非萎缩性胃炎","reason":"鉴别要点：胃腺体保留较多，主要为慢性炎细胞浸润；不能把胃黏膜腺体消失及皱襞变平归为非萎缩。"}],"scope":"core","imageWidth":1377,"imageHeight":697,"annotations":{"marks":[{"x":40,"y":83,"rx":9,"ry":2.5,"label":"溃疡表面坏死/渗出区","detail":"贴近下方溃疡腔面的薄带状区域，需与深面的肉芽和瘢痕层对照；本倍率不精确区分坏死层与炎性渗出层。"},{"x":44.5,"y":70,"rx":2.5,"ry":7,"label":"肉芽组织层","detail":"坏死带深面可见较细胞性、含细小血管的组织，代表修复中的肉芽组织。"},{"x":40,"y":51,"rx":8,"ry":10,"label":"较深的瘢痕组织","detail":"更深部组织较淡、纤维性成分占主导，和表面的坏死及肉芽层构成分层。"}],"note":"溃疡腔面朝下，深部朝上；此倍率适合辨认分层，不能辨认单个炎细胞。"}},{"id":"g059","name":"急性蜂窝织炎性阑尾炎","kind":"大体","system":"消化系统","image":"assets/g059.jpg","points":["阑尾肿胀增厚并出现脓性渗出。","阑尾增粗、壁增厚，切面或腔内可见脓性渗出物。","管腔可有粪石阻塞，但粪石并非诊断必需。"],"caution":"","review":"reviewed","options":[{"text":"急性蜂窝织炎性阑尾炎","reason":"符合本图：阑尾肿胀增厚并出现脓性渗出。"},{"text":"阑尾黏液性肿瘤","reason":"鉴别要点：可使阑尾扩张、充满黏液，判断需上皮及壁结构；不以中性粒细胞浸润肌层为核心。"},{"text":"坏疽性阑尾炎","reason":"鉴别要点：以阑尾壁广泛坏死、暗黑或暗绿色改变为主，可伴穿孔；蜂窝织炎性主要是壁内弥漫化脓。"},{"text":"阑尾淋巴组织增生","reason":"鉴别要点：阑尾本来就富含淋巴组织，滤泡多不能单独诊断急性化脓性阑尾炎。"}],"scope":"core","imageWidth":660,"imageHeight":902,"annotations":{"marks":[{"x":36,"y":45,"rx":6,"ry":17,"label":"增厚的阑尾壁","detail":"剖开后可见厚实肿胀的管壁，与中央管腔分开观察。"},{"x":74,"y":27,"rx":9,"ry":11,"label":"管腔内灰白内容物","detail":"腔内有粗糙灰白物，应结合原标本所示炎症与管壁改变判断。"}],"note":"不能只凭固定后灰白颜色认定某一部分一定是脓；粪石也不是阑尾炎的必备条件。"}},{"id":"g060","name":"急性蜂窝织炎性阑尾炎","kind":"镜下","system":"消化系统","image":"assets/g060.jpg","points":["中性粒细胞进入阑尾肌层是关键。","先认出阑尾管腔、黏膜及丰富淋巴组织。","阑尾壁弥漫炎细胞浸润，关键是中性粒细胞进入肌层。"],"caution":"","review":"reviewed","options":[{"text":"急性蜂窝织炎性阑尾炎","reason":"符合本图：中性粒细胞进入阑尾肌层是关键。"},{"text":"阑尾淋巴组织增生","reason":"鉴别要点：阑尾本来就富含淋巴组织，滤泡多不能单独诊断急性化脓性阑尾炎。"},{"text":"坏疽性阑尾炎","reason":"鉴别要点：以阑尾壁广泛坏死、暗黑或暗绿色改变为主，可伴穿孔；蜂窝织炎性主要是壁内弥漫化脓。"},{"text":"阑尾黏液性肿瘤","reason":"鉴别要点：可使阑尾扩张、充满黏液，判断需上皮及壁结构；不以中性粒细胞浸润肌层为核心。"}],"scope":"core","imageWidth":1269,"imageHeight":964,"annotations":{"marks":[{"x":51,"y":52,"rx":14,"ry":14,"label":"管腔内渗出物","detail":"中央管腔内聚集颗粒状、细胞性物质，先定位管腔和阑尾壁。"},{"x":20,"y":52,"rx":7,"ry":16,"label":"需重点高倍检查的肌层","detail":"圈内粉红肌束位于淋巴组织外侧，诊断关键是在肌层寻找中性粒细胞浸润。"}],"note":"此倍率不能准确辨认单个中性粒细胞；淋巴滤泡丰富本身不等于急性阑尾炎。"}},{"id":"g061","name":"食管癌（溃疡型）","kind":"大体","system":"消化系统","image":"assets/g061.jpg","points":["先辨认纵行皱襞构成的食管管壁。","病变区为不规则溃疡，边缘隆起、底部不平。","以破坏性溃疡为主，区别向腔内突出的蕈伞型和环形缩窄型。"],"caution":"","review":"reviewed","options":[{"text":"食管癌（溃疡型）","reason":"符合本图：先辨认纵行皱襞构成的食管管壁。"},{"text":"食管癌（缩窄型）","reason":"鉴别要点：食管局部管壁环形收缩，管腔明显变窄。"},{"text":"食管癌（蕈伞型）","reason":"鉴别要点：食管腔内有大块向腔内突起的肿物。"},{"text":"食管癌（髓质型）","reason":"鉴别要点：食管壁较长范围被肿瘤浸润、明显增厚。"}],"scope":"core","imageWidth":546,"imageHeight":615,"annotations":{"marks":[{"x":44,"y":61,"rx":17,"ry":20,"label":"不规则溃疡性病灶","detail":"食管黏膜出现破坏性缺损，底面粗糙、边缘不规则隆起，和上方纵行皱襞作对照。"}],"note":""}},{"id":"g062","name":"食管癌（缩窄型）","kind":"大体","system":"消化系统","image":"assets/g062.jpg","points":["食管局部管壁环形收缩，管腔明显变窄。","狭窄段上下可保留相对正常的纵行黏膜。","核心是短段环形缩窄，常与纤维组织反应和浸润有关。"],"caution":"","review":"reviewed","options":[{"text":"食管癌（缩窄型）","reason":"符合本图：食管局部管壁环形收缩，管腔明显变窄。"},{"text":"食管癌（溃疡型）","reason":"鉴别要点：先辨认纵行皱襞构成的食管管壁。"},{"text":"食管癌（蕈伞型）","reason":"鉴别要点：食管腔内有大块向腔内突起的肿物。"},{"text":"食管癌（髓质型）","reason":"鉴别要点：食管壁较长范围被肿瘤浸润、明显增厚。"}],"scope":"core","imageWidth":1024,"imageHeight":1023,"annotations":{"marks":[{"x":57,"y":55,"rx":13,"ry":12,"label":"短段环形缩窄","detail":"中段管壁明显收紧、腔隙狭小，上下食管相对较宽，是缩窄型的关键。"}],"note":""}},{"id":"g063","name":"食管癌（蕈伞型）","kind":"大体","system":"消化系统","image":"assets/g063.jpg","points":["食管腔内有大块向腔内突起的肿物。","肿物表面凹凸不平，边缘较显著，呈蕈伞或息肉样。","以外生性隆起为主，区别食管壁广泛增厚的髓质型。"],"caution":"","review":"reviewed","options":[{"text":"食管癌（蕈伞型）","reason":"符合本图：食管腔内有大块向腔内突起的肿物。"},{"text":"食管癌（溃疡型）","reason":"鉴别要点：先辨认纵行皱襞构成的食管管壁。"},{"text":"食管癌（缩窄型）","reason":"鉴别要点：食管局部管壁环形收缩，管腔明显变窄。"},{"text":"食管癌（髓质型）","reason":"鉴别要点：食管壁较长范围被肿瘤浸润、明显增厚。"}],"scope":"core","imageWidth":797,"imageHeight":1099,"annotations":{"marks":[{"x":47,"y":54,"rx":21,"ry":27,"label":"向腔内突出的实性肿物","detail":"大块肿物凸入食管腔，占据明显空间，外生性隆起比单纯壁增厚更突出。"}],"note":""}},{"id":"g064","name":"食管癌（髓质型）","kind":"大体","system":"消化系统","image":"assets/g064.jpg","points":["食管壁较长范围被肿瘤浸润、明显增厚。","黏膜表面不规则，管腔因壁厚而变形、狭窄。","以壁内浸润性生长为主，不是单个外生性蕈伞状肿物。"],"caution":"重点识别浸润性生长；大体分型边界可有重叠。","review":"reviewed","options":[{"text":"食管癌（髓质型）","reason":"符合本图：食管壁较长范围被肿瘤浸润、明显增厚。"},{"text":"食管癌（溃疡型）","reason":"鉴别要点：先辨认纵行皱襞构成的食管管壁。"},{"text":"食管癌（缩窄型）","reason":"鉴别要点：食管局部管壁环形收缩，管腔明显变窄。"},{"text":"食管癌（蕈伞型）","reason":"鉴别要点：食管腔内有大块向腔内突起的肿物。"}],"scope":"core","imageWidth":847,"imageHeight":1056,"annotations":{"marks":[{"x":40,"y":35,"rx":12,"ry":20,"label":"增厚的食管壁","detail":"该段壁组织灰白、粗厚，原有黏膜纹理变得不规则。"},{"x":35,"y":61,"rx":12,"ry":12,"label":"表面不规则破坏","detail":"局部可见凹陷与粗糙破坏，需结合整段管壁浸润增厚观察。"}],"note":""}},{"id":"g065","name":"食管鳞状细胞癌","kind":"镜下","system":"消化系统","image":"assets/g065.jpg","points":["浸润性鳞状癌巢内形成角化珠。","异型上皮细胞呈巢状浸润性分布。","癌巢中央可见同心层状、嗜酸性角化物，形成角化珠。"],"caution":"本题给定食管部位；局部视野未展示全部食管壁，形态识别重点是鳞癌。","review":"reviewed","options":[{"text":"食管鳞状细胞癌","reason":"符合本图：浸润性鳞状癌巢内形成角化珠。"},{"text":"尖锐湿疣","reason":"鉴别要点：鳞状上皮凹空细胞：核周晕加核异常。"},{"text":"胃黏液腺癌","reason":"鉴别要点：细胞外大片黏液湖中漂浮癌细胞。"},{"text":"乳头状尿路上皮癌","reason":"鉴别要点：乳头轴心外覆盖拥挤、异常的尿路上皮。"}],"scope":"core","imageWidth":909,"imageHeight":901,"annotations":{"marks":[{"x":18,"y":60,"rx":8,"ry":9,"label":"角化珠","detail":"癌巢中可见较强嗜酸性的层状角化物，是鳞状分化的重要线索。"},{"x":72,"y":55,"rx":18,"ry":20,"label":"浸润性癌巢","detail":"深染异型上皮细胞组成不规则细胞巢，周围有间质。"}],"note":""}},{"id":"g066","name":"胃癌（蕈伞型）","kind":"大体","system":"消化系统","image":"assets/g066.jpg","points":["胃腔内可见局限、明显隆起的肿块。","肿物呈结节或蕈伞样，表面不平，可伴坏死。","重点是向腔内突出的实体肿瘤，不是单纯溃疡凹陷。"],"caution":"","review":"reviewed","options":[{"text":"胃癌（蕈伞型）","reason":"符合本图：胃腔内可见局限、明显隆起的肿块。"},{"text":"胃癌（溃疡型）","reason":"鉴别要点：胃壁见不规则溃疡性病灶。"},{"text":"胃癌（弥漫浸润型，革囊胃）","reason":"鉴别要点：胃壁弥漫性增厚，整个胃轮廓变得僵硬、收缩。"},{"text":"慢性胃溃疡","reason":"鉴别要点：规则溃疡加皱襞向中心集中。"}],"scope":"core","imageWidth":979,"imageHeight":1086,"annotations":{"marks":[{"x":65,"y":28,"rx":19,"ry":15,"label":"蕈伞状隆起肿块","detail":"灰白分叶状肿块突出于胃腔，呈较明确的外生性隆起。"}],"note":"观察肿块与旁侧胃黏膜皱襞的高低关系。"}},{"id":"g067","name":"胃癌（溃疡型）","kind":"大体","system":"消化系统","image":"assets/g067.jpg","points":["胃壁见不规则溃疡性病灶。","周围边缘隆起、外翻，底部粗糙不平。","黏膜皱襞在病变边缘中断、破坏，区别规则向中心集中的慢性良性溃疡。"],"caution":"","review":"reviewed","options":[{"text":"胃癌（溃疡型）","reason":"符合本图：胃壁见不规则溃疡性病灶。"},{"text":"慢性胃溃疡","reason":"鉴别要点：规则溃疡加皱襞向中心集中。"},{"text":"胃癌（蕈伞型）","reason":"鉴别要点：胃腔内可见局限、明显隆起的肿块。"},{"text":"胃癌（弥漫浸润型，革囊胃）","reason":"鉴别要点：胃壁弥漫性增厚，整个胃轮廓变得僵硬、收缩。"}],"scope":"core","imageWidth":743,"imageHeight":871,"annotations":{"marks":[{"x":58,"y":32,"rx":24,"ry":23,"label":"不规则癌性溃疡","detail":"中央凹陷，边缘厚而不整齐，周围皱襞在病变附近改变。"}],"note":"大体图只能显示溃疡及边缘形态，恶性仍须组织学确认。"}},{"id":"g068","name":"胃癌（弥漫浸润型，革囊胃）","kind":"大体","system":"消化系统","image":"assets/g068.jpg","points":["胃壁弥漫性增厚，整个胃轮廓变得僵硬、收缩。","胃腔变小，黏膜皱襞可粗大、固定或消失。","“壁厚、腔小、质硬”构成革囊胃的记忆组合。"],"caution":"革囊胃是大体形态，不可自动等同每例都是印戒细胞癌；组织学类型另判。","review":"reviewed","options":[{"text":"胃癌（弥漫浸润型，革囊胃）","reason":"符合本图：胃壁弥漫性增厚，整个胃轮廓变得僵硬、收缩。"},{"text":"胃癌（蕈伞型）","reason":"鉴别要点：胃腔内可见局限、明显隆起的肿块。"},{"text":"胃癌（溃疡型）","reason":"鉴别要点：胃壁见不规则溃疡性病灶。"},{"text":"慢性萎缩性胃炎","reason":"鉴别要点：胃黏膜变薄、皱襞减少，血管可透见。"}],"scope":"core","imageWidth":715,"imageHeight":977,"annotations":{"marks":[{"x":38,"y":42,"rx":23,"ry":29,"label":"弥漫增厚的胃壁","detail":"大片胃壁灰白粗厚、皱襞形态受破坏，观察其广泛性而非孤立肿块。"}],"note":""}},{"id":"g069","name":"胃黏液腺癌","kind":"镜下","system":"消化系统","image":"assets/g069.jpg","points":["细胞外大片黏液湖中漂浮癌细胞。","组织内出现大片浅染的细胞外黏液湖。","黏液湖中可有漂浮的癌细胞、细胞团或腺体。"],"caution":"黏液腺癌通常要求细胞外黏液占肿瘤面积超过一半；单个视野无法量化全部肿瘤，本图用于识别黏液湖。","review":"reviewed","options":[{"text":"胃黏液腺癌","reason":"符合本图：细胞外大片黏液湖中漂浮癌细胞。"},{"text":"印戒细胞（胃癌）","reason":"鉴别要点：胞内黏液把核挤到一侧，形成印戒形态。"},{"text":"胃腺癌（管状型）","reason":"鉴别要点：以异型腺体浸润性生长为主，不能用正常杯状细胞或表面炎症替代癌性结构和细胞异型。"},{"text":"胃黏膜肠上皮化生","reason":"鉴别要点：胃黏膜里找杯状细胞，识别肠型分化。"}],"scope":"core","imageWidth":1075,"imageHeight":1055,"annotations":{"marks":[{"x":60,"y":73,"rx":18,"ry":18,"label":"淡染黏液样区","detail":"此处组织淡染、黏液样成分丰富，可见散在细胞或小细胞群。"},{"x":75,"y":9,"rx":11,"ry":8,"label":"异型腺样结构","detail":"腺样细胞群核深染且排列不整齐，与周围黏液样区域共同观察。"}],"note":""}},{"id":"g070","name":"印戒细胞（胃癌）","kind":"镜下","system":"消化系统","image":"assets/g070.jpg","points":["胞内黏液把核挤到一侧，形成印戒形态。","癌细胞胞质内充满黏液，胞质淡染或空泡样。","细胞核被挤至一侧，外形像带印面的戒指。"],"caution":"本题只考印戒细胞形态，不能将其与黏液腺癌直接等同；完整分类需结合细胞比例及组织结构。","review":"reviewed","options":[{"text":"印戒细胞（胃癌）","reason":"符合本图：胞内黏液把核挤到一侧，形成印戒形态。"},{"text":"胃黏液腺癌","reason":"鉴别要点：细胞外大片黏液湖中漂浮癌细胞。"},{"text":"胃腺癌（管状型）","reason":"鉴别要点：以异型腺体浸润性生长为主，不能用正常杯状细胞或表面炎症替代癌性结构和细胞异型。"},{"text":"胃黏膜肠上皮化生","reason":"鉴别要点：胃黏膜里找杯状细胞，识别肠型分化。"}],"scope":"core","imageWidth":623,"imageHeight":967,"annotations":{"marks":[{"x":29,"y":12,"rx":11,"ry":7,"label":"印戒样细胞","detail":"胞质出现较大的淡染空泡，深染细胞核被挤向一侧。"}],"note":"放大观察核与胞质空泡的关系。"}},{"id":"g071","name":"结肠癌（浸润型）","kind":"大体","system":"消化系统","image":"assets/g071.jpg","points":["肠壁局部呈环形或较长段浸润性增厚。","管壁变硬、黏膜破坏，管腔缩窄。","核心为壁内浸润和狭窄，不是向腔内突出的单个菜花样肿块。"],"caution":"","review":"reviewed","options":[{"text":"结肠癌（浸润型）","reason":"符合本图：肠壁局部呈环形或较长段浸润性增厚。"},{"text":"结肠癌（溃疡型）","reason":"鉴别要点：结肠黏膜形成不规则、较大的溃疡性缺损。"},{"text":"结肠癌（隆起型）","reason":"鉴别要点：结肠腔内有大块菜花状或分叶状隆起。"},{"text":"结肠多发性息肉病","reason":"鉴别要点：结肠黏膜广泛密布多发息肉。"}],"scope":"core","imageWidth":646,"imageHeight":882,"annotations":{"marks":[{"x":61,"y":61,"rx":25,"ry":21,"label":"浸润增厚区域","detail":"肠壁中段明显增厚、表面不规则，正常黏膜纹理在病变处中断。"}],"note":"结合上下相对保留的黏膜，对照局部壁增厚和腔道受累。"}},{"id":"g072","name":"结肠癌（溃疡型）","kind":"大体","system":"消化系统","image":"assets/g072.jpg","points":["结肠黏膜形成不规则、较大的溃疡性缺损。","溃疡边缘隆起，底部不平，周围黏膜被破坏。","与结核溃疡相比，更强调不规则肿块性边缘及浸润。"],"caution":"","review":"reviewed","options":[{"text":"结肠癌（溃疡型）","reason":"符合本图：结肠黏膜形成不规则、较大的溃疡性缺损。"},{"text":"结肠癌（浸润型）","reason":"鉴别要点：肠壁局部呈环形或较长段浸润性增厚。"},{"text":"结肠癌（隆起型）","reason":"鉴别要点：结肠腔内有大块菜花状或分叶状隆起。"},{"text":"溃疡型肠结核","reason":"鉴别要点：肠溃疡横行或环形，长轴与肠长轴垂直。"}],"scope":"core","imageWidth":807,"imageHeight":1003,"annotations":{"marks":[{"x":32,"y":40,"rx":18,"ry":12,"label":"溃疡及隆起边缘","detail":"可见局灶凹陷，周围边缘隆起且不规则。"}],"note":""}},{"id":"g073","name":"结肠癌（隆起型）","kind":"大体","system":"消化系统","image":"assets/g073.jpg","points":["结肠腔内有大块菜花状或分叶状隆起。","表面粗糙、不规则，与邻近黏膜形成明显高低差。","以外生性肿块为主，区别弥漫细小息肉和环形浸润狭窄。"],"caution":"","review":"reviewed","options":[{"text":"结肠癌（隆起型）","reason":"符合本图：结肠腔内有大块菜花状或分叶状隆起。"},{"text":"结肠癌（浸润型）","reason":"鉴别要点：肠壁局部呈环形或较长段浸润性增厚。"},{"text":"结肠癌（溃疡型）","reason":"鉴别要点：结肠黏膜形成不规则、较大的溃疡性缺损。"},{"text":"结肠多发性息肉病","reason":"鉴别要点：结肠黏膜广泛密布多发息肉。"}],"scope":"core","imageWidth":737,"imageHeight":1001,"annotations":{"marks":[{"x":50,"y":53,"rx":30,"ry":20,"label":"菜花样隆起","detail":"肿块呈粗颗粒、分叶状，向肠腔突出。"}],"note":""}},{"id":"g074","name":"结肠多发性息肉病","kind":"大体","system":"消化系统","image":"assets/g074.jpg","points":["结肠黏膜广泛密布多发息肉。","结肠黏膜面密布数量众多的息肉样突起。","突起大小不等，广泛分布，而非单个癌性肿块。"],"caution":"多发性息肉不能直接等同于某种遗传综合征，仍需家族史或分子证据。","review":"reviewed","options":[{"text":"结肠多发性息肉病","reason":"符合本图：结肠黏膜广泛密布多发息肉。"},{"text":"结肠癌（隆起型）","reason":"鉴别要点：结肠腔内有大块菜花状或分叶状隆起。"},{"text":"结肠单发腺瘤","reason":"鉴别要点：通常为单个有蒂或无蒂息肉，不是广泛密布大量息肉的模式。"},{"text":"肠阿米巴病","reason":"鉴别要点：散在小口溃疡，黏膜下破坏可比开口宽。"}],"scope":"core","imageWidth":625,"imageHeight":1105,"annotations":{"marks":[{"x":41,"y":23,"rx":16,"ry":13,"label":"较大息肉样隆起","detail":"多个较大的结节状或带蒂样隆起突出于黏膜表面。"},{"x":43,"y":64,"rx":19,"ry":14,"label":"密集小息肉","detail":"此区域可见众多大小不等的黏膜隆起，体现多发性。"}],"note":"大体图不能单独判定每个息肉的组织类型。"}},{"id":"g075","name":"直肠黏液腺癌（胶样型）","kind":"大体","system":"消化系统","image":"assets/g075.jpg","points":["直肠壁内肿瘤呈灰白、半透明或胶冻样外观。","切面可见黏液样区域，肠壁增厚、组织结构破坏。","“胶样”提示富含黏液，最终组织类型需镜下证实黏液湖及癌细胞。"],"caution":"本题为已知诊断标本；大体胶冻样物不能替代组织学诊断。","review":"reviewed","options":[{"text":"直肠黏液腺癌（胶样型）","reason":"符合本图：直肠壁内肿瘤呈灰白、半透明或胶冻样外观。"},{"text":"结肠癌（浸润型）","reason":"鉴别要点：肠壁局部呈环形或较长段浸润性增厚。"},{"text":"结肠癌（溃疡型）","reason":"鉴别要点：结肠黏膜形成不规则、较大的溃疡性缺损。"},{"text":"结肠癌（隆起型）","reason":"鉴别要点：结肠腔内有大块菜花状或分叶状隆起。"}],"scope":"core","imageWidth":833,"imageHeight":929,"annotations":{"marks":[{"x":44,"y":61,"rx":27,"ry":23,"label":"灰白胶样肿块","detail":"肿块切面大片灰白、略呈胶样，与周边残余腔壁形成对照。"}],"note":"胶样外观需结合题目中的镜下黏液证据理解。"}},{"id":"g076","name":"亚急性重型肝炎","kind":"大体","system":"肝胆系统","image":"assets/g076.jpg","points":["肝切面斑杂，坏死萎陷区与结节状隆起区交错。","存活肝细胞增生形成再生结节，与大片坏死并存。","重点是大范围坏死背景中的不均匀再生，而非均匀细小结节。"],"caution":"大体图可显示坏死与再生模式，不能据此确定病毒类型或临床肝衰竭程度。","review":"reviewed","options":[{"text":"亚急性重型肝炎","reason":"符合本图：肝切面斑杂，坏死萎陷区与结节状隆起区交错。"},{"text":"大结节性肝硬化","reason":"鉴别要点：肝表面及切面被较大的结节分割。"},{"text":"小结节性肝硬化","reason":"鉴别要点：肝表面弥漫密布细小结节。"},{"text":"急性大块肝坏死","reason":"鉴别要点：肝实质广泛丧失，肝体积可缩小；亚急性阶段更强调坏死与再生结节并存。"}],"scope":"core","imageWidth":765,"imageHeight":1223,"annotations":{"marks":[{"x":40,"y":53,"rx":16,"ry":29,"label":"斑杂的肝切面","detail":"切面内浅深不一、局部高低不平，整体比较萎陷区与残存结节。"}],"note":"照片不足以逐一确定小结节的性质。"}},{"id":"g077","name":"肝细胞水样变性（气球样变）","kind":"镜下","system":"肝胆系统","image":"assets/g077.jpg","points":["肝细胞肿胀、胞质疏松淡染的气球样改变。","肝细胞体积明显增大，胞质疏松、淡染。","细胞轮廓仍在，部分呈气球样肿胀。"],"caution":"水样变性可见于多种肝损伤，不能单独确定肝炎病因。","review":"reviewed","options":[{"text":"肝细胞水样变性（气球样变）","reason":"符合本图：肝细胞肿胀、胞质疏松淡染的气球样改变。"},{"text":"肝细胞脂肪变性","reason":"鉴别要点：肝细胞内圆形透明脂滴空泡。"},{"text":"肝细胞点状坏死","reason":"鉴别要点：肝小叶内少数肝细胞丧失和局灶炎细胞聚集。"},{"text":"淤血性肝病（镜下）","reason":"鉴别要点：主要为中央静脉及肝窦扩张淤血，严重时小叶中央肝细胞坏死；不同于规则脂滴空泡或假小叶形成。"}],"scope":"core","imageWidth":1179,"imageHeight":1049,"annotations":{"marks":[{"x":80,"y":61,"rx":11,"ry":15,"label":"肿胀淡染肝细胞","detail":"细胞体积增大，胞质疏松淡染，仍可见细胞核。"}],"note":""}},{"id":"g079","name":"肝细胞点状坏死","kind":"镜下","system":"肝胆系统","image":"assets/g079.jpg","points":["肝小叶内少数肝细胞丧失和局灶炎细胞聚集。","肝小叶内局灶性少数肝细胞消失或坏死。","坏死灶有小团炎细胞及巨噬细胞聚集。"],"caution":"","review":"reviewed","options":[{"text":"肝细胞点状坏死","reason":"符合本图：肝小叶内少数肝细胞丧失和局灶炎细胞聚集。"},{"text":"肝细胞水样变性（气球样变）","reason":"鉴别要点：肝细胞肿胀、胞质疏松淡染的气球样改变。"},{"text":"亚急性重型肝炎","reason":"鉴别要点：肝组织存在较大片或桥接样坏死、塌陷区域。"},{"text":"淤血性肝病（镜下）","reason":"鉴别要点：主要为中央静脉及肝窦扩张淤血，严重时小叶中央肝细胞坏死；不同于规则脂滴空泡或假小叶形成。"}],"scope":"core","imageWidth":529,"imageHeight":705,"annotations":{"marks":[{"x":42,"y":51,"rx":21,"ry":25,"label":"局灶细胞破坏与炎细胞","detail":"少量肝细胞原有排列被深染小炎细胞及细胞碎屑打断，形成点状病灶。"}],"note":""}},{"id":"g080","name":"大结节性肝硬化","kind":"大体","system":"肝胆系统","image":"assets/g080.jpg","points":["肝表面及切面被较大的结节分割。","结节大小不一，纤维间隔粗细不均。","以结节大小悬殊对比小结节性肝硬化的细小、均一结节。"],"caution":"大结节、小结节是形态分类，不能仅凭结节大小反推唯一病因。","review":"reviewed","options":[{"text":"大结节性肝硬化","reason":"符合本图：肝表面及切面被较大的结节分割。"},{"text":"小结节性肝硬化","reason":"鉴别要点：肝表面弥漫密布细小结节。"},{"text":"原发性肝癌（弥漫型）","reason":"鉴别要点：肝切面弥漫分布许多细小肿瘤结节。"},{"text":"原发性肝癌（结节型）","reason":"鉴别要点：肝内可见多个较大的肿瘤结节，大小不等。"}],"scope":"core","imageWidth":909,"imageHeight":1155,"annotations":{"marks":[{"x":65,"y":24,"rx":19,"ry":17,"label":"大小不等的结节","detail":"肝表面呈多个明显隆起结节，结节大小差异较大。"}],"note":"对照整件标本观察结节大小分布，不从照片推算实际毫米数。"}},{"id":"g081","name":"小结节性肝硬化","kind":"大体","system":"肝胆系统","image":"assets/g081.jpg","points":["肝表面弥漫密布细小结节。","结节大小较一致，排列较均匀，表面颗粒状。","通常以约3毫米作为大小结节的形态分界；本图无精确尺标，不做实际测量。"],"caution":"","review":"reviewed","options":[{"text":"小结节性肝硬化","reason":"符合本图：肝表面弥漫密布细小结节。"},{"text":"大结节性肝硬化","reason":"鉴别要点：肝表面及切面被较大的结节分割。"},{"text":"原发性肝癌（弥漫型）","reason":"鉴别要点：肝切面弥漫分布许多细小肿瘤结节。"},{"text":"肝脂肪变性","reason":"鉴别要点：肝弥漫黄变、边缘圆钝。"}],"scope":"core","imageWidth":1268,"imageHeight":942,"annotations":{"marks":[{"x":67,"y":35,"rx":18,"ry":20,"label":"弥漫细小结节","detail":"表面遍布相对均匀、细小的结节，使肝表面细颗粒样不平。"}],"note":"结节的实际大小需结合标本尺度判断。"}},{"id":"g082","name":"肝硬化（假小叶）","kind":"镜下","system":"肝胆系统","image":"assets/g082.jpg","points":["纤维间隔包绕再生结节，正常肝小叶结构重塑。","增生纤维间隔将肝实质分割成结节。","结节内为再生肝细胞，原正常小叶结构重塑。"],"caution":"","review":"reviewed","options":[{"text":"肝硬化（假小叶）","reason":"符合本图：纤维间隔包绕再生结节，正常肝小叶结构重塑。"},{"text":"亚急性重型肝炎","reason":"鉴别要点：肝组织存在较大片或桥接样坏死、塌陷区域。"},{"text":"肝细胞癌（肝硬化背景）","reason":"鉴别要点：纤维分隔的肝组织中出现局灶性细胞密集的肿瘤结节。"},{"text":"肝细胞脂肪变性","reason":"鉴别要点：肝细胞内圆形透明脂滴空泡。"}],"scope":"core","imageWidth":1093,"imageHeight":1015,"annotations":{"marks":[{"x":44,"y":37,"rx":23,"ry":21,"label":"假小叶与纤维间隔","detail":"肝细胞团被较淡染的纤维条带包绕，形成不规则结节结构。"}],"note":"低倍重点看整体分隔结构，不能仅凭单个细胞判断肝硬化。"}},{"id":"g083","name":"肝细胞脂肪变性","kind":"镜下","system":"肝胆系统","image":"assets/g083.jpg","points":["肝细胞内圆形透明脂滴空泡。","肝细胞胞质内出现大量圆形、大小不等的透明空泡。","大脂滴可将细胞核挤到边缘，小脂滴可多发。"],"caution":"","review":"reviewed","options":[{"text":"肝细胞脂肪变性","reason":"符合本图：肝细胞内圆形透明脂滴空泡。"},{"text":"肝细胞水样变性（气球样变）","reason":"鉴别要点：肝细胞肿胀、胞质疏松淡染的气球样改变。"},{"text":"淤血性肝病（镜下）","reason":"鉴别要点：主要为中央静脉及肝窦扩张淤血，严重时小叶中央肝细胞坏死；不同于规则脂滴空泡或假小叶形成。"},{"text":"肝硬化（假小叶）","reason":"鉴别要点：纤维间隔包绕再生结节，正常肝小叶结构重塑。"}],"scope":"core","imageWidth":1163,"imageHeight":985,"annotations":{"marks":[{"x":52,"y":42,"rx":23,"ry":24,"label":"胞质内脂滴空泡","detail":"肝细胞内出现大量大小不等的圆形透明空泡。"}],"note":""}},{"id":"g084","name":"原发性肝癌（弥漫型）","kind":"大体","system":"肝胆系统","image":"assets/g084.jpg","points":["肝切面弥漫分布许多细小肿瘤结节。","病灶累及范围广，不由单个巨大肿块主导。","本题为已知诊断标本，识别弥漫型；需结合组织学与肝硬化再生结节区别。"],"caution":"弥漫型肝癌与结节性肝硬化可有大体相似性；病灶性质依赖镜下。","review":"reviewed","options":[{"text":"原发性肝癌（弥漫型）","reason":"符合本图：肝切面弥漫分布许多细小肿瘤结节。"},{"text":"原发性肝癌（巨块型）","reason":"鉴别要点：肝切面由一个巨大、边界不规则的肿块主导。"},{"text":"原发性肝癌（结节型）","reason":"鉴别要点：肝内可见多个较大的肿瘤结节，大小不等。"},{"text":"小结节性肝硬化","reason":"鉴别要点：肝表面弥漫密布细小结节。"}],"scope":"core","imageWidth":739,"imageHeight":1103,"annotations":{"marks":[{"x":39,"y":40,"rx":20,"ry":23,"label":"弥漫分布的结节","detail":"多个小结节遍及肝切面，未形成单一占主导的巨大肿块。"}],"note":"肝癌与肝硬化结节的区别仍需组织学确认。"}},{"id":"g085","name":"原发性肝癌（巨块型）","kind":"大体","system":"肝胆系统","image":"assets/g085.jpg","points":["肝切面由一个巨大、边界不规则的肿块主导。","肿块灰白或黄白，与周围肝组织形成明显差异。","可有坏死出血，重点是单个巨大或融合成巨块的癌灶。"],"caution":"巨块型肝癌也可合并肝硬化。","review":"reviewed","options":[{"text":"原发性肝癌（巨块型）","reason":"符合本图：肝切面由一个巨大、边界不规则的肿块主导。"},{"text":"原发性肝癌（弥漫型）","reason":"鉴别要点：肝切面弥漫分布许多细小肿瘤结节。"},{"text":"原发性肝癌（结节型）","reason":"鉴别要点：肝内可见多个较大的肿瘤结节，大小不等。"},{"text":"阿米巴肝脓肿","reason":"鉴别要点：肝内不规则坏死腔，壁呈破絮状。"}],"scope":"core","imageWidth":1165,"imageHeight":915,"annotations":{"marks":[{"x":57,"y":64,"rx":30,"ry":26,"label":"占主导的巨大肿块","detail":"大片灰白肿块占据切面显著部分，与周围较暗的肝组织形成对照。"}],"note":""}},{"id":"g086","name":"原发性肝癌（结节型）","kind":"大体","system":"肝胆系统","image":"assets/g086.jpg","points":["肝内可见多个较大的肿瘤结节，大小不等。","癌结节与周围肝组织不同，可伴出血、坏死。","常见肝硬化背景，但不能把所有再生结节都当癌结节。"],"caution":"","review":"reviewed","options":[{"text":"原发性肝癌（结节型）","reason":"符合本图：肝内可见多个较大的肿瘤结节，大小不等。"},{"text":"原发性肝癌（弥漫型）","reason":"鉴别要点：肝切面弥漫分布许多细小肿瘤结节。"},{"text":"原发性肝癌（巨块型）","reason":"鉴别要点：肝切面由一个巨大、边界不规则的肿块主导。"},{"text":"大结节性肝硬化","reason":"鉴别要点：肝表面及切面被较大的结节分割。"}],"scope":"core","imageWidth":873,"imageHeight":843,"annotations":{"marks":[{"x":23,"y":69,"rx":16,"ry":15,"label":"灰白癌结节","detail":"此处可见较明确的灰白结节，与周围组织颜色和结构不同。"},{"x":51,"y":54,"rx":22,"ry":23,"label":"另一较大结节","detail":"切面存在多个大小不一的结节，观察其多灶分布。"}],"note":"结节的病理性质需镜下确认。"}},{"id":"g087","name":"肝细胞癌（肝硬化背景）","kind":"镜下","system":"肝胆系统","image":"assets/g087.jpg","points":["纤维分隔的肝组织中出现局灶性细胞密集的肿瘤结节。","瘤细胞排列为增厚梁索、团块或假腺样结构。","需结合结构异常和细胞异型，区别周围规则再生假小叶。"],"caution":"本图倍率偏低，仅展示肿瘤结节结构；细胞异型性需高倍确认，不能以“结节”一词独立判癌。","review":"reviewed","options":[{"text":"肝细胞癌（肝硬化背景）","reason":"符合本图：纤维分隔的肝组织中出现局灶性细胞密集的肿瘤结节。"},{"text":"肝硬化（假小叶）","reason":"鉴别要点：纤维间隔包绕再生结节，正常肝小叶结构重塑。"},{"text":"亚急性重型肝炎","reason":"鉴别要点：肝组织存在较大片或桥接样坏死、塌陷区域。"},{"text":"胃黏液腺癌","reason":"鉴别要点：细胞外大片黏液湖中漂浮癌细胞。"}],"scope":"core","imageWidth":1141,"imageHeight":982,"annotations":{"marks":[{"x":48,"y":36,"rx":25,"ry":23,"label":"细胞密集的结节内部","detail":"结节内细胞形成较厚的梁索或团块，与外侧肝组织结构对照。"},{"x":23,"y":16,"rx":15,"ry":8,"label":"结节周围纤维组织","detail":"外围可见弧形纤维分隔，先定位结节再比较内外结构。"}],"note":"单细胞异型需更高倍视野观察。"}},{"id":"g088","name":"新月体性肾小球肾炎","kind":"镜下","system":"泌尿系统","image":"assets/g088.jpg","points":["肾小囊腔新月体从外侧挤压毛细血管丛。","肾小囊腔内出现新月形细胞及基质堆积。","新月体从外侧包绕并挤压肾小球毛细血管丛。"],"caution":"新月体由壁层上皮细胞、单核巨噬细胞等组成；快速进展性肾炎是临床综合征，不能仅凭一处新月体断定病因。","review":"reviewed","options":[{"text":"新月体性肾小球肾炎","reason":"符合本图：肾小囊腔新月体从外侧挤压毛细血管丛。"},{"text":"膜性肾病","reason":"鉴别要点：毛细血管壁弥漫增厚，细胞增生不突出。"},{"text":"慢性硬化性肾小球肾炎","reason":"鉴别要点：肾小球硬化加小管萎缩、间质纤维化。"},{"text":"肾细动脉硬化（玻璃样变）","reason":"鉴别要点：肾细动脉壁玻璃样增厚加肾缺血改变。"}],"scope":"core","imageWidth":829,"imageHeight":785,"annotations":{"marks":[{"x":38,"y":70,"rx":28,"ry":20,"label":"新月体样细胞增生","detail":"肾小囊周边出现多层细胞，弧形包绕并挤压内部毛细血管丛。"},{"x":47,"y":37,"rx":21,"ry":22,"label":"受挤压的毛细血管丛","detail":"中央残留的肾小球血管丛与外围细胞性新月体作对照。"}],"note":""}},{"id":"g089","name":"膜性肾病","kind":"镜下","system":"泌尿系统","image":"assets/g089.jpg","points":["毛细血管壁弥漫增厚，细胞增生不突出。","肾小球毛细血管壁较弥漫地增厚。","毛细血管袢仍较开放，明显细胞增生不突出。"],"caution":"本 HE 图只能显示膜性改变的线索；不能声称图中已见银染钉突或电镜上皮下沉积。","review":"reviewed","options":[{"text":"膜性肾病","reason":"符合本图：毛细血管壁弥漫增厚，细胞增生不突出。"},{"text":"新月体性肾小球肾炎","reason":"鉴别要点：肾小囊腔新月体从外侧挤压毛细血管丛。"},{"text":"慢性硬化性肾小球肾炎","reason":"鉴别要点：肾小球硬化加小管萎缩、间质纤维化。"},{"text":"肾细动脉硬化（玻璃样变）","reason":"鉴别要点：肾细动脉壁玻璃样增厚加肾缺血改变。"}],"scope":"core","imageWidth":909,"imageHeight":657,"annotations":{"marks":[{"x":67,"y":53,"rx":13,"ry":21,"label":"毛细血管襻","detail":"观察外周血管襻轮廓及壁的增厚感，细胞增生并不突出。"}],"note":"HE 图像不能可靠显示银染所见的钉突。"}},{"id":"g090","name":"慢性硬化性肾小球肾炎","kind":"镜下","system":"泌尿系统","image":"assets/g090.jpg","points":["肾小球硬化加小管萎缩、间质纤维化。","多个肾小球缩小、玻璃样变或完全硬化。","间质纤维化，伴慢性炎细胞，小管萎缩及扩张。"],"caution":"这是一组慢性瘢痕形态，不能仅凭此图追溯最初肾炎类型。","review":"reviewed","options":[{"text":"慢性硬化性肾小球肾炎","reason":"符合本图：肾小球硬化加小管萎缩、间质纤维化。"},{"text":"新月体性肾小球肾炎","reason":"鉴别要点：肾小囊腔新月体从外侧挤压毛细血管丛。"},{"text":"膜性肾病","reason":"鉴别要点：毛细血管壁弥漫增厚，细胞增生不突出。"},{"text":"急性肾盂肾炎","reason":"鉴别要点：中性粒细胞进入肾小管并形成白细胞管型。"}],"scope":"core","imageWidth":1267,"imageHeight":653,"annotations":{"marks":[{"x":61,"y":23,"rx":12,"ry":20,"label":"硬化的肾小球","detail":"此处被较均质的粉红物取代，正常开放毛细血管襻减少。"},{"x":57,"y":53,"rx":7,"ry":12,"label":"小管内蛋白性管型","detail":"扩张小管腔中可见圆形嗜酸性管型，与间质慢性炎症并存。"}],"note":""}},{"id":"g091","name":"慢性肾盂肾炎","kind":"大体","system":"泌尿系统","image":"assets/g091.jpg","points":["粗大不规则瘢痕配肾盂肾盏变形。","肾表面呈不规则、粗大的凹陷瘢痕。","切面可见肾盂肾盏扩张、变形及局部肾实质变薄。"],"caution":"","review":"reviewed","options":[{"text":"慢性肾盂肾炎","reason":"符合本图：粗大不规则瘢痕配肾盂肾盏变形。"},{"text":"急性肾盂肾炎","reason":"鉴别要点：肾表面多发黄白色小脓肿。"},{"text":"继发性颗粒性固缩肾","reason":"鉴别要点：常为双肾弥漫颗粒性萎缩，皮质变薄；不同于慢性肾盂肾炎的不规则粗大瘢痕和肾盏变形。"},{"text":"肾梗死","reason":"鉴别要点：通常形成楔形苍白灶，边缘可充血，不是多发小脓肿或不规则肾盂瘢痕。"}],"scope":"core","imageWidth":1065,"imageHeight":1085,"annotations":{"marks":[{"x":29,"y":45,"rx":16,"ry":11,"label":"变形扩张的肾盏","detail":"肾盏腔不规则、部分明显扩张，邻近肾实质厚薄不均。"}],"note":"同时观察整个肾的轮廓与实质不对称；不把图上每一处凹陷都定为瘢痕。"}},{"id":"g092","name":"急性肾盂肾炎","kind":"大体","system":"泌尿系统","image":"assets/g092.jpg","points":["肾表面多发黄白色小脓肿。","肾表面及实质散在多个黄白色小脓肿。","病灶为局灶化脓性改变，可沿小管和集合系统分布。"],"caution":"","review":"reviewed","options":[{"text":"急性肾盂肾炎","reason":"符合本图：肾表面多发黄白色小脓肿。"},{"text":"慢性肾盂肾炎","reason":"鉴别要点：粗大不规则瘢痕配肾盂肾盏变形。"},{"text":"肾结核（干酪样坏死）","reason":"鉴别要点：肾实质干酪样坏死并形成不规则空洞。"},{"text":"肾梗死","reason":"鉴别要点：通常形成楔形苍白灶，边缘可充血，不是多发小脓肿或不规则肾盂瘢痕。"}],"scope":"core","imageWidth":1123,"imageHeight":1057,"annotations":{"marks":[{"x":56,"y":47,"rx":21,"ry":24,"label":"散在灰白小脓灶","detail":"肾表面可见多个灰白或淡黄色小点状、隆起性病灶。"}],"note":"小脓灶需结合镜下中性粒细胞证据确认。"}},{"id":"g093","name":"急性肾盂肾炎","kind":"镜下","system":"泌尿系统","image":"assets/g093.jpg","points":["中性粒细胞进入肾小管并形成白细胞管型。","肾小管腔内充满中性粒细胞，形成白细胞管型。","管周间质也有大量中性粒细胞浸润。"],"caution":"慢性肾盂肾炎急性发作也可有同样形态；该图不能独立区分首次急性发病与慢性急性加重。","review":"reviewed","options":[{"text":"急性肾盂肾炎","reason":"符合本图：中性粒细胞进入肾小管并形成白细胞管型。"},{"text":"慢性硬化性肾小球肾炎","reason":"鉴别要点：肾小球硬化加小管萎缩、间质纤维化。"},{"text":"新月体性肾小球肾炎","reason":"鉴别要点：肾小囊腔新月体从外侧挤压毛细血管丛。"},{"text":"膜性肾病","reason":"鉴别要点：毛细血管壁弥漫增厚，细胞增生不突出。"}],"scope":"core","imageWidth":1267,"imageHeight":545,"annotations":{"marks":[{"x":49,"y":33,"rx":14,"ry":18,"label":"管腔内炎细胞团","detail":"肾小管腔内充满密集深染炎细胞，形成脓性管型样结构。"},{"x":42,"y":57,"rx":5,"ry":15,"label":"小管间炎细胞浸润","detail":"小管之间的间质亦有大量炎细胞，显示炎症不限于单一管腔。"}],"note":""}},{"id":"g094","name":"膀胱乳头状肿瘤","kind":"大体","system":"泌尿系统","image":"assets/g094.jpg","points":["膀胱腔面长出乳头状、菜花状肿物。","膀胱腔面可见向腔内突出的乳头状或菜花状肿物。","肿物表面不规则，病变可累及较广黏膜。"],"caution":"单凭大体乳头状外观不能区分乳头状瘤、低恶性潜能肿瘤及癌；本题只考乳头状肿瘤形态。","review":"reviewed","options":[{"text":"膀胱乳头状肿瘤","reason":"符合本图：膀胱腔面长出乳头状、菜花状肿物。"},{"text":"膀胱结石","reason":"鉴别要点：为腔内固体结石，不具有与膀胱黏膜相连的乳头状组织。"},{"text":"膀胱憩室","reason":"鉴别要点：是膀胱壁向外形成袋状突出，不是黏膜向腔内形成菜花样肿物。"},{"text":"慢性膀胱炎","reason":"鉴别要点：可有壁增厚、黏膜充血或颗粒状变化，但不能代替本图明确的乳头状肿物。"}],"scope":"core","imageWidth":1223,"imageHeight":1077,"annotations":{"marks":[{"x":57,"y":56,"rx":23,"ry":33,"label":"乳头状、菜花样肿块","detail":"膀胱腔内有灰白分支状隆起，明显突出于相邻较平整的黏膜。"}],"note":"大体外观不能单独判定浸润深度或分级。"}},{"id":"g095","name":"乳头状尿路上皮癌","kind":"镜下","system":"泌尿系统","image":"assets/g095.jpg","points":["乳头轴心外覆盖拥挤、异常的尿路上皮。","可见纤维血管轴心及其表面多层尿路上皮。","上皮层次增厚，细胞排列拥挤，极性和核形有异常。"],"caution":"上皮增厚、细胞增多；浸润深度与高低级别需完整组织学评估。","review":"reviewed","options":[{"text":"乳头状尿路上皮癌","reason":"符合本图：乳头轴心外覆盖拥挤、异常的尿路上皮。"},{"text":"膀胱鳞状细胞癌","reason":"鉴别要点：典型镜下为鳞状癌巢、细胞间桥及角化，不是由尿路上皮覆盖的细长乳头轴心。"},{"text":"膀胱黏膜慢性炎症","reason":"鉴别要点：以间质炎细胞浸润为主，不能解释有纤维血管轴心的多层上皮乳头性肿瘤。"},{"text":"肾透明细胞癌","reason":"鉴别要点：透明胞质癌细胞巢加细薄血管网。"}],"scope":"core","imageWidth":914,"imageHeight":730,"annotations":{"marks":[{"x":10,"y":27,"rx":8,"ry":17,"label":"乳头纤维血管轴心","detail":"较淡染的间质位于乳头内部，其外包覆多层上皮。"},{"x":36,"y":30,"rx":15,"ry":19,"label":"增厚的异型上皮","detail":"上皮细胞层次增多，核拥挤、排列不整齐。"}],"note":"分级和浸润判断须结合完整组织学证据。"}},{"id":"g096","name":"肾透明细胞癌","kind":"镜下","system":"泌尿系统","image":"assets/g096.jpg","points":["透明胞质癌细胞巢加细薄血管网。","瘤细胞胞质透亮，成巢状、团块或腺泡样排列。","细胞巢间有丰富、细薄的毛细血管网。"],"caution":"","review":"reviewed","options":[{"text":"肾透明细胞癌","reason":"符合本图：透明胞质癌细胞巢加细薄血管网。"},{"text":"肾嗜酸细胞瘤","reason":"鉴别要点：瘤细胞通常胞质丰富、颗粒状嗜酸性，而非大片透明胞质。"},{"text":"乳头状肾细胞癌","reason":"鉴别要点：以乳头或管乳头结构为主，轴心可含泡沫细胞；不同于透明细胞巢配细血管网。"},{"text":"嫌色性肾细胞癌","reason":"鉴别要点：常见明显细胞膜、核周晕及皱缩不规则核；不能只因胞质偏淡就归为透明细胞癌。"}],"scope":"core","imageWidth":1269,"imageHeight":682,"annotations":{"marks":[{"x":59,"y":37,"rx":19,"ry":24,"label":"透明细胞巢","detail":"肿瘤细胞胞质透亮，成巢或团块排列，其间有细薄血管间隔。"}],"note":"透明胞质只是形态线索，不能独立确定器官来源。"}},{"id":"g098","name":"流行性乙型脑炎（小胶质结节）","kind":"镜下","system":"神经系统","image":"assets/g098.jpg","points":["小胶质细胞局灶聚集成结节。","小胶质细胞局灶聚集形成细胞结节。","可围绕受损神经元，出现卫星现象或噬神经细胞现象。"],"caution":"小胶质结节也见于其他病毒性脑炎；不能仅凭此结构特异确定乙脑病毒。","review":"reviewed","options":[{"text":"流行性乙型脑炎（小胶质结节）","reason":"符合本图：小胶质细胞局灶聚集成结节。"},{"text":"神经元中央染色质溶解","reason":"鉴别要点：神经元胞体肿大、尼氏体减少、核偏位，属于神经元反应；不等于小胶质细胞结节。"},{"text":"脑膜瘤","reason":"鉴别要点：旋涡状细胞团，部分可形成砂粒体。"},{"text":"神经鞘瘤（Antoni A 区）","reason":"鉴别要点：整齐核栅栏加无核带，形成 Verocay 小体。"}],"scope":"core","imageWidth":1145,"imageHeight":765,"annotations":{"marks":[{"x":36,"y":55,"rx":24,"ry":31,"label":"小胶质细胞聚集灶","detail":"小而深染的细胞在局部集中，形成结节样聚集，与周围较疏的脑实质对照。"}],"note":"小胶质结节并非乙型脑炎特异性改变。"}},{"id":"g099","name":"流行性乙型脑炎（筛状软化灶）","kind":"镜下","system":"神经系统","image":"assets/g099.jpg","points":["脑实质多发小软化灶形成筛孔样外观。","脑实质内出现多发浅染、疏松或空洞样小灶。","软化灶大小不等，整体呈筛孔样外观。"],"caution":"本题给定乙型脑炎诊断；软化灶本身不能确定病原。","review":"reviewed","options":[{"text":"流行性乙型脑炎（筛状软化灶）","reason":"符合本图：脑实质多发小软化灶形成筛孔样外观。"},{"text":"化脓性脑膜炎","reason":"鉴别要点：脓性炎症主要位于脑膜和蛛网膜下腔。"},{"text":"脑梗死","reason":"鉴别要点：常形成符合血管分布的局灶软化，后期囊腔和胶质瘢痕；病因不能靠小软化灶直接定为感染。"},{"text":"胶质母细胞瘤（假栅栏样坏死）","reason":"鉴别要点：坏死边缘瘤细胞密集排列，形成假栅栏。"}],"scope":"core","imageWidth":1268,"imageHeight":652,"annotations":{"marks":[{"x":28,"y":34,"rx":7,"ry":9,"label":"浅染疏松小灶","detail":"此处较周围组织淡染、疏松，是多灶性软化的代表部位。"},{"x":41,"y":76,"rx":6,"ry":9,"label":"另一浅染软化灶","detail":"多个相似小灶散布在脑实质中，低倍观察其分布而非单个裂隙。"}],"note":"切割裂隙、血管腔须与软化灶区分；细胞反应需高倍确认。"}},{"id":"g100","name":"化脓性脑膜炎","kind":"大体","system":"神经系统","image":"assets/g100.jpg","points":["脑表面及脑沟被混浊脓性渗出物覆盖。","脑表面软脑膜及蛛网膜下腔覆盖灰黄、混浊的脓性渗出物。","渗出沿脑沟分布，使脑沟、血管轮廓变得不清。"],"caution":"","review":"reviewed","options":[{"text":"化脓性脑膜炎","reason":"符合本图：脑表面及脑沟被混浊脓性渗出物覆盖。"},{"text":"流行性乙型脑炎","reason":"鉴别要点：脑灰质附近散在针尖样软化灶。"},{"text":"结核性脑膜炎","reason":"鉴别要点：可见脑底部较明显的渗出，镜下可有结核性肉芽肿；与以中性粒细胞为主的化脓性炎症区分。"},{"text":"脑脓肿","reason":"鉴别要点：典型为局限脓腔、周围包膜和水肿，不是脑表面弥漫脓性渗出。"}],"scope":"core","imageWidth":1233,"imageHeight":967,"annotations":{"marks":[{"x":43,"y":45,"rx":24,"ry":28,"label":"浑浊的脑膜及渗出","detail":"表面灰白浑浊，脑沟间可见覆盖性物质，血管与脑沟轮廓不如正常清楚。"}],"note":"脓性性质需镜下中性粒细胞证据支持。"}},{"id":"g101","name":"化脓性脑膜炎","kind":"镜下","system":"神经系统","image":"assets/g101.jpg","points":["脓性炎症主要位于脑膜和蛛网膜下腔。","脑表面的软脑膜及蛛网膜下腔明显增宽。","该处聚集大量炎性渗出物，典型以中性粒细胞为主。"],"caution":"本图倍率低，细胞分类需高倍核实，不能根据一层紫染就认定具体病原。","review":"reviewed","options":[{"text":"化脓性脑膜炎","reason":"符合本图：脓性炎症主要位于脑膜和蛛网膜下腔。"},{"text":"流行性乙型脑炎（小胶质结节）","reason":"鉴别要点：小胶质细胞局灶聚集成结节。"},{"text":"流行性乙型脑炎（筛状软化灶）","reason":"鉴别要点：脑实质多发小软化灶形成筛孔样外观。"},{"text":"结核性脑膜炎","reason":"鉴别要点：可见脑底部较明显的渗出，镜下可有结核性肉芽肿；与以中性粒细胞为主的化脓性炎症区分。"}],"scope":"core","imageWidth":1267,"imageHeight":467,"annotations":{"marks":[{"x":18,"y":32,"rx":14,"ry":25,"label":"脑膜腔隙内密集渗出","detail":"脑组织表面的腔隙内可见成片深染炎细胞，与旁侧脑实质分界可辨。"},{"x":62,"y":82,"rx":16,"ry":13,"label":"沿软脑膜分布的炎症","detail":"炎性渗出沿脑表面及血管周围分布，强调病变位置在脑膜。"}],"note":"低倍观察炎症分布，单个中性粒细胞需更高倍确认。"}},{"id":"g102","name":"弥漫性星形细胞肿瘤","kind":"大体","system":"神经系统","image":"assets/g102.jpg","points":["脑实质内见灰白色、边界不清的占位病灶。","病变与周围脑组织相互交错，呈浸润性生长。","可挤压脑室并造成中线移位；区别边界清楚、脑外压迫的脑膜瘤。"],"caution":"大体只能识别浸润性胶质肿瘤；确切分型和分级需结合组织学与分子结果。","review":"reviewed","options":[{"text":"弥漫性星形细胞肿瘤","reason":"符合本图：脑实质内见灰白色、边界不清的占位病灶。"},{"text":"胶质母细胞瘤","reason":"鉴别要点：脑实质内不规则肿物，与周围脑组织边界不清。"},{"text":"脑膜瘤","reason":"鉴别要点：脑外界清肿物压迫邻近脑实质。"},{"text":"流行性乙型脑炎","reason":"鉴别要点：脑灰质附近散在针尖样软化灶。"}],"scope":"core","imageWidth":741,"imageHeight":1069,"annotations":{"marks":[{"x":38,"y":27,"rx":24,"ry":21,"label":"边界不清的脑内病灶","detail":"灰白病灶与邻近脑组织交错，局部正常结构被替代。"}],"note":"具体胶质肿瘤分型不能只凭大体图完成。"}},{"id":"g103","name":"胶质母细胞瘤","kind":"大体","system":"神经系统","image":"assets/g103.jpg","points":["脑实质内不规则肿物，与周围脑组织边界不清。","病灶切面斑杂，可有灰白肿瘤、出血及坏死混合。","浸润性占位伴明显坏死提示高级别胶质肿瘤；本题给定胶质母细胞瘤诊断。"],"caution":"大体不足以确定现代整合诊断和分子分型。","review":"reviewed","options":[{"text":"胶质母细胞瘤","reason":"符合本图：脑实质内不规则肿物，与周围脑组织边界不清。"},{"text":"弥漫性星形细胞肿瘤","reason":"鉴别要点：脑实质内见灰白色、边界不清的占位病灶。"},{"text":"脑膜瘤","reason":"鉴别要点：脑外界清肿物压迫邻近脑实质。"},{"text":"流行性乙型脑炎","reason":"鉴别要点：脑灰质附近散在针尖样软化灶。"}],"scope":"core","imageWidth":1268,"imageHeight":822,"annotations":{"marks":[{"x":71,"y":27,"rx":17,"ry":18,"label":"斑杂的脑内肿块","detail":"此处肿块灰白、色泽不均，可见局部坏死样改变，与周围脑组织不同。"}],"note":""}},{"id":"g104","name":"胶质母细胞瘤（假栅栏样坏死）","kind":"镜下","system":"神经系统","image":"assets/g104.jpg","points":["坏死边缘瘤细胞密集排列，形成假栅栏。","可见坏死区域及其周围密集的肿瘤细胞。","瘤细胞沿坏死边缘成列聚集，形成假栅栏样排列。"],"caution":"微血管增生和坏死为关键组织学线索，但完整胶质瘤诊断还需分子信息。","review":"reviewed","options":[{"text":"胶质母细胞瘤（假栅栏样坏死）","reason":"符合本图：坏死边缘瘤细胞密集排列，形成假栅栏。"},{"text":"神经鞘瘤（Antoni A 区）","reason":"鉴别要点：整齐核栅栏加无核带，形成 Verocay 小体。"},{"text":"脑膜瘤","reason":"鉴别要点：旋涡状细胞团，部分可形成砂粒体。"},{"text":"神经纤维瘤","reason":"鉴别要点：疏松梭形细胞配波浪状核与胶原。"}],"scope":"core","imageWidth":875,"imageHeight":671,"annotations":{"marks":[{"x":48,"y":49,"rx":14,"ry":36,"label":"假栅栏样排列","detail":"较密集的深染肿瘤细胞沿坏死区域边缘排列。"},{"x":78,"y":65,"rx":16,"ry":27,"label":"坏死区域","detail":"此处细胞核减少，组织呈较淡染的颗粒或疏松坏死样改变。"}],"note":"先找坏死边缘，再看细胞是否沿边缘密集排列。"}},{"id":"g105","name":"脑膜瘤","kind":"大体","system":"神经系统","image":"assets/g105.jpg","points":["脑外界清肿物压迫邻近脑实质。","脑表面或脑外见界限清楚、圆形或分叶状实性肿物。","肿物压迫邻近脑组织，形成清楚的压迹。"],"caution":"大体不能决定脑膜瘤分级，亦不能仅凭边界清楚就排除所有恶性可能。","review":"reviewed","options":[{"text":"脑膜瘤","reason":"符合本图：脑外界清肿物压迫邻近脑实质。"},{"text":"弥漫性星形细胞肿瘤","reason":"鉴别要点：脑实质内见灰白色、边界不清的占位病灶。"},{"text":"胶质母细胞瘤","reason":"鉴别要点：脑实质内不规则肿物，与周围脑组织边界不清。"},{"text":"流行性乙型脑炎","reason":"鉴别要点：脑灰质附近散在针尖样软化灶。"}],"scope":"core","imageWidth":1268,"imageHeight":938,"annotations":{"marks":[{"x":53,"y":34,"rx":18,"ry":18,"label":"边界清楚的脑外肿块","detail":"灰白实性肿块推压下方脑组织，边界较清楚。"}],"note":"同时观察下方脑实质受压，而非与肿块弥漫交错。"}},{"id":"g106","name":"脑膜瘤","kind":"镜下","system":"神经系统","image":"assets/g106.jpg","points":["旋涡状细胞团，部分可形成砂粒体。","瘤细胞排列成多个同心圆样、旋涡状细胞团。","部分旋涡中央可钙化形成砂粒体。"],"caution":"","review":"reviewed","options":[{"text":"脑膜瘤","reason":"符合本图：旋涡状细胞团，部分可形成砂粒体。"},{"text":"神经鞘瘤（Antoni A 区）","reason":"鉴别要点：整齐核栅栏加无核带，形成 Verocay 小体。"},{"text":"神经纤维瘤","reason":"鉴别要点：疏松梭形细胞配波浪状核与胶原。"},{"text":"胶质母细胞瘤（假栅栏样坏死）","reason":"鉴别要点：坏死边缘瘤细胞密集排列，形成假栅栏。"}],"scope":"core","imageWidth":1261,"imageHeight":867,"annotations":{"marks":[{"x":73,"y":42,"rx":10,"ry":13,"label":"旋涡样细胞团","detail":"瘤细胞围绕中心同心性排列，形成旋涡结构。"},{"x":23,"y":27,"rx":9,"ry":11,"label":"另一旋涡结构","detail":"多个类似同心性结构散布于肿瘤内，是识别脑膜瘤的重要线索。"}],"note":"旋涡结构不等同于砂粒体。"}},{"id":"g107","name":"神经鞘瘤（Antoni A 区）","kind":"镜下","system":"神经系统","image":"assets/g107.jpg","points":["整齐核栅栏加无核带，形成 Verocay 小体。","瘤细胞排列紧密，核栅栏间为嗜酸性少核或无核带。"],"caution":"典型神经鞘瘤为良性肿瘤；Antoni A 是组织区域，而非癌分型。","review":"reviewed","options":[{"text":"神经鞘瘤（Antoni A 区）","reason":"符合本图：整齐核栅栏加无核带，形成 Verocay 小体。"},{"text":"神经纤维瘤","reason":"鉴别要点：疏松梭形细胞配波浪状核与胶原。"},{"text":"胶质母细胞瘤（假栅栏样坏死）","reason":"鉴别要点：坏死边缘瘤细胞密集排列，形成假栅栏。"},{"text":"脑膜瘤","reason":"鉴别要点：旋涡状细胞团，部分可形成砂粒体。"}],"scope":"core","imageWidth":1135,"imageHeight":875,"annotations":{"marks":[{"x":40,"y":40,"rx":22,"ry":17,"label":"栅栏状核与核稀少带","detail":"梭形细胞核成排聚集，两排之间可见较淡染、核较少的带状区。"}],"note":""}},{"id":"g108","name":"神经纤维瘤","kind":"镜下","system":"神经系统","image":"assets/g108.jpg","points":["疏松梭形细胞配波浪状核与胶原。","瘤细胞为细长梭形，细胞核弯曲、波浪状。","细胞分布较疏松，夹杂波浪状胶原纤维。"],"caution":"","review":"reviewed","options":[{"text":"神经纤维瘤","reason":"符合本图：疏松梭形细胞配波浪状核与胶原。"},{"text":"神经鞘瘤（Antoni A 区）","reason":"鉴别要点：整齐核栅栏加无核带，形成 Verocay 小体。"},{"text":"脑膜瘤","reason":"鉴别要点：旋涡状细胞团，部分可形成砂粒体。"},{"text":"胶质母细胞瘤（假栅栏样坏死）","reason":"鉴别要点：坏死边缘瘤细胞密集排列，形成假栅栏。"}],"scope":"core","imageWidth":1268,"imageHeight":754,"annotations":{"marks":[{"x":54,"y":57,"rx":18,"ry":19,"label":"波浪状梭形细胞","detail":"细长、弯曲的细胞核散布于疏松的胶原背景中。"}],"note":""}},{"id":"g109","name":"肝脂肪变性","kind":"大体","system":"肝胆系统","image":"assets/g109.jpg","points":["肝弥漫黄变、边缘圆钝。","肝脏体积增大，边缘较圆钝。","切面呈黄或土黄色、较均匀，质地较软。"],"caution":"","review":"reviewed","options":[{"text":"肝脂肪变性","reason":"符合本图：肝弥漫黄变、边缘圆钝。"},{"text":"慢性肝淤血（槟榔肝）","reason":"鉴别要点：肝切面红黄相间的槟榔样斑纹。"},{"text":"小结节性肝硬化","reason":"鉴别要点：肝表面弥漫密布细小结节。"},{"text":"原发性肝癌（巨块型）","reason":"鉴别要点：肝切面由一个巨大、边界不规则的肿块主导。"}],"scope":"core","imageWidth":669,"imageHeight":1031,"annotations":{"marks":[{"x":50,"y":38,"rx":22,"ry":26,"label":"弥漫黄色肝切面","detail":"切面广泛发黄、色泽较均一，结合肝细胞脂滴镜下图理解。"}],"note":"油腻感属于触诊/切面描述，照片仅能显示颜色与整体外观。"}},{"id":"g110","name":"肾结核（干酪样坏死）","kind":"大体","system":"感染与寄生虫","image":"assets/g110.jpg","points":["肾实质干酪样坏死并形成不规则空洞。","肾实质内有多个不规则腔隙及灰黄坏死区。","坏死物呈干燥、松碎、干酪样，肾结构遭破坏。"],"caution":"本题为已知诊断标本；结核病原的确认仍需相应检查。","review":"reviewed","options":[{"text":"肾结核（干酪样坏死）","reason":"符合本图：肾实质干酪样坏死并形成不规则空洞。"},{"text":"慢性肾盂肾炎","reason":"鉴别要点：粗大不规则瘢痕配肾盂肾盏变形。"},{"text":"急性肾盂肾炎","reason":"鉴别要点：肾表面多发黄白色小脓肿。"},{"text":"肾梗死","reason":"鉴别要点：通常形成楔形苍白灶，边缘可充血，不是多发小脓肿或不规则肾盂瘢痕。"}],"scope":"core","imageWidth":1047,"imageHeight":1081,"annotations":{"marks":[{"x":14,"y":70,"rx":11,"ry":11,"label":"灰白干酪样物","detail":"局部腔隙内可见灰白、较均质的坏死样物质。"},{"x":78,"y":20,"rx":11,"ry":12,"label":"组织破坏形成空腔","detail":"肾实质内可见不规则空腔，邻近区域亦有类似破坏。"}],"note":"空腔与坏死不是结核的特异证据。"}},{"id":"g111","name":"干酪样坏死","kind":"镜下","system":"感染与寄生虫","image":"assets/g111.jpg","points":["无正常结构、无核的大片嗜酸性坏死物。","大片区域呈均质或颗粒状嗜酸性红染。","原组织结构完全消失，细胞核破坏、消失。"],"caution":"干酪样坏死常见于结核，也可见于某些真菌感染；不能单靠坏死形态确定病原。","review":"reviewed","options":[{"text":"干酪样坏死","reason":"符合本图：无正常结构、无核的大片嗜酸性坏死物。"},{"text":"硅肺（硅结节）","reason":"鉴别要点：致密胶原玻璃样变形成同心圆或旋涡状硅结节。"},{"text":"动脉粥样硬化（粥样斑块）","reason":"鉴别要点：针状胆固醇裂隙和坏死脂质核心。"},{"text":"风湿小体（Aschoff 小体）","reason":"鉴别要点：心肌间质风湿细胞围绕中央纤维素样坏死。"}],"scope":"core","imageWidth":1218,"imageHeight":898,"annotations":{"marks":[{"x":60,"y":56,"rx":29,"ry":35,"label":"无结构坏死区","detail":"大片粉红色颗粒样物中缺少正常组织轮廓及细胞核。"},{"x":78,"y":12,"rx":15,"ry":9,"label":"坏死周边细胞反应","detail":"坏死外围较深染、细胞较多，与中央缺少细胞核的区域形成对照。"}],"note":"宽大白色裂隙是制片或组织分离空隙，不是干酪样坏死。"}},{"id":"g112","name":"慢性肝淤血（槟榔肝）","kind":"大体","system":"肝胆系统","image":"assets/g112.jpg","points":["肝切面红黄相间的槟榔样斑纹。","肝切面红褐色区域与黄褐色区域交错。","暗红区对应小叶中央淤血，浅黄区多为周边脂肪变。"],"caution":"颜色受固定影响；应以交错斑纹配合器官整体结构识别。","review":"reviewed","options":[{"text":"慢性肝淤血（槟榔肝）","reason":"符合本图：肝切面红黄相间的槟榔样斑纹。"},{"text":"肝脂肪变性","reason":"鉴别要点：肝弥漫黄变、边缘圆钝。"},{"text":"小结节性肝硬化","reason":"鉴别要点：肝表面弥漫密布细小结节。"},{"text":"原发性肝癌（弥漫型）","reason":"鉴别要点：肝切面弥漫分布许多细小肿瘤结节。"}],"scope":"core","imageWidth":579,"imageHeight":1129,"annotations":{"marks":[{"x":44,"y":40,"rx":25,"ry":25,"label":"红褐与浅黄相间","detail":"切面呈细密斑杂，深色淤血区与浅色区域交错，形成槟榔样外观。"}],"note":"小叶中央与周边的精确定位需镜下观察。"}},{"id":"g113","name":"白喉（假膜性炎）","kind":"大体","system":"感染与寄生虫","image":"assets/g113.jpg","points":["呼吸道黏膜表面附着灰白假膜。","咽喉或气管黏膜表面覆盖灰白色假膜。","假膜由坏死组织、纤维蛋白及炎细胞等构成。"],"caution":"假膜并非白喉独有，照片不能独立确定白喉杆菌感染。","review":"reviewed","options":[{"text":"白喉（假膜性炎）","reason":"符合本图：呼吸道黏膜表面附着灰白假膜。"},{"text":"化脓性扁桃体炎","reason":"鉴别要点：脓性渗出常突出于扁桃体隐窝，需与紧附黏膜的大片假膜区分。"},{"text":"非角化性咽黏膜炎","reason":"鉴别要点：以黏膜充血、水肿和炎细胞浸润为主，不应把表面所有淡色物都称白喉假膜。"},{"text":"结核性脑膜炎","reason":"鉴别要点：可见脑底部较明显的渗出，镜下可有结核性肉芽肿；与以中性粒细胞为主的化脓性炎症区分。"}],"scope":"core","imageWidth":809,"imageHeight":1164,"annotations":{"marks":[{"x":46,"y":38,"rx":14,"ry":18,"label":"灰白膜样覆盖物","detail":"喉及上段气道黏膜表面可见较厚的灰白膜样物。"}],"note":"仅凭假膜的大体外观不能确定病原。"}},{"id":"g114","name":"成熟性畸胎瘤","kind":"大体","system":"生殖与乳腺","image":"assets/g114.jpg","points":["囊实混合肿物内有多种成熟组织成分。","肿物兼有囊性及实性部分，切面成分复杂。","可出现脂肪、皮脂样物、毛发或不同成熟组织。"],"caution":"本题未给定器官部位；成熟与否仍需镜下确认。","review":"reviewed","options":[{"text":"成熟性畸胎瘤","reason":"符合本图：囊实混合肿物内有多种成熟组织成分。"},{"text":"卵巢黏液性囊腺瘤","reason":"鉴别要点：多房囊性肿物加黏液样内容物。"},{"text":"卵巢浆液性囊性肿瘤","reason":"鉴别要点：囊内明显乳头增生提示浆液性肿瘤类别，良恶性另判。"},{"text":"成熟脂肪瘤","reason":"鉴别要点：以均一成熟脂肪为主，缺乏多种胚层组织混杂及复杂囊实性结构。"}],"scope":"core","imageWidth":709,"imageHeight":1069,"annotations":{"marks":[{"x":69,"y":27,"rx":18,"ry":14,"label":"囊性区域","detail":"上部可见较大的囊腔与光滑内面，呈囊性结构。"},{"x":60,"y":73,"rx":24,"ry":20,"label":"混杂实性组织","detail":"下部有颜色、结构不同的实性成分和多样腔隙，体现组织构成复杂。"}],"note":"仅凭大体外观不能确定各成分的胚层或组织类型。"}},{"id":"g115","name":"尿路上皮乳头状肿瘤","kind":"镜下","system":"泌尿系统","image":"assets/g115.jpg","points":["纤维血管轴心外覆盖多层尿路上皮的乳头。","多个乳头突起以纤维血管组织为轴心。","乳头表面覆盖多层尿路上皮，须继续检查厚度、极性和核异型。"],"caution":"本视野可识别尿路上皮乳头状结构，但不足以可靠区分良性与癌。","review":"reviewed","options":[{"text":"尿路上皮乳头状肿瘤","reason":"符合本图：纤维血管轴心外覆盖多层尿路上皮的乳头。"},{"text":"膀胱鳞状细胞癌","reason":"鉴别要点：典型镜下为鳞状癌巢、细胞间桥及角化，不是由尿路上皮覆盖的细长乳头轴心。"},{"text":"膀胱黏膜慢性炎症","reason":"鉴别要点：以间质炎细胞浸润为主，不能解释有纤维血管轴心的多层上皮乳头性肿瘤。"},{"text":"肾透明细胞癌","reason":"鉴别要点：透明胞质癌细胞巢加细薄血管网。"}],"scope":"core","imageWidth":1064,"imageHeight":770,"annotations":{"marks":[{"x":57,"y":38,"rx":23,"ry":25,"label":"分支乳头状结构","detail":"多个细长分支突起向腔内伸展，内部有较淡染轴心，表面覆上皮。"}],"note":"低倍可识别乳头结构，分级及浸润仍需高倍和完整切片。"}},{"id":"s001","name":"肌细胞萎缩","kind":"镜下","system":"细胞适应与损伤","image":"assets/s001.jpg","points":["识别关键词：肌细胞变小、肌束变细，间质所占比例相对增加。","可见较细的嗜酸性肌纤维，肌细胞胞质量相对较少。","肌束间有较多淡红色纤维间质；细胞核仍保存，区别于核消失的坏死。"],"options":[{"text":"肌细胞萎缩","reason":"肌细胞体积缩小、肌束变细，并伴间质相对增多。"},{"text":"肌细胞肥大","reason":"肥大时单个肌细胞体积增大、胞质丰富，与本图对照性改变不同。"},{"text":"肌细胞凝固性坏死","reason":"坏死需见核固缩、碎裂或消失；本图多数细胞核保存。"},{"text":"淀粉样物沉积","reason":"淀粉样物为细胞外均质淡红沉积，并非带核肌细胞缩小。"}],"caution":"本题只考肌细胞萎缩，不要求从局部视野定位器官。大小判断依赖倍率和对照，不能仅凭核密度。","review":"reviewed","scope":"core","prompt":"与本套肥大标本对照，图中肌细胞的主要适应性改变是什么？","imageWidth":1800,"imageHeight":772,"annotations":{"marks":[{"x":28,"y":34,"rx":22,"ry":25,"label":"较细肌束与间质","detail":"肌细胞胞质相对较少，肌束之间有淡染纤维间质。"}],"note":"细胞大小须结合倍率与对照判断。"}},{"id":"s002","name":"肌细胞肥大","kind":"镜下","system":"细胞适应与损伤","image":"assets/s002.jpg","points":["识别关键词：单个肌细胞体积增大、胞质丰富，肌纤维增粗。","可见较粗的嗜酸性肌纤维，部分细胞核也增大。","细胞核仍保存；主要改变是细胞变大，不能等同于细胞数量增加。"],"options":[{"text":"肌细胞肥大","reason":"肌纤维增粗、胞质丰富，伴部分细胞核增大。"},{"text":"肌细胞萎缩","reason":"萎缩为单个细胞和肌纤维变小，胞质量减少。"},{"text":"肌细胞水变性","reason":"水变性以肿胀伴胞质疏松淡染为主；本图肌纤维胞质丰富且较强嗜酸。"},{"text":"肌细胞凝固性坏死","reason":"凝固性坏死出现细胞核消失及结构影子，不是保存细胞核的增粗肌纤维。"}],"caution":"本题只考肌细胞肥大，不要求从局部视野定位器官。大小判断须结合倍率和对照。","review":"reviewed","scope":"core","prompt":"与本套萎缩标本对照，图中肌细胞的主要适应性改变是什么？","imageWidth":1016,"imageHeight":1400,"annotations":{"marks":[{"x":41,"y":82,"rx":32,"ry":13,"label":"粗大肌细胞","detail":"这一组肌纤维胞质丰富、嗜酸性较强，部分细胞核增大。"}],"note":"只考肌细胞肥大形态，不要求凭该高倍视野确定器官；注意与萎缩图的倍率差异。"}},{"id":"s003","name":"心肌淀粉样变性","kind":"镜下","system":"细胞适应与损伤","image":"assets/s003.jpg","points":["识别关键词：血管壁及其周围细胞外出现均质、淡红色无结构物质。","小血管周围可见较厚的均质嗜酸性沉积，细胞少，与周围心外膜脂肪/间质区分。","沉积以细胞外及血管周围为主，不是心肌细胞胞质内的空泡。"],"options":[{"text":"心肌淀粉样变性","reason":"识别关键词：血管壁及其周围细胞外出现均质、淡红色无结构物质。"},{"text":"心肌脂肪浸润","reason":"脂肪细胞呈大而透明的空泡并有周边细胞核，不是均质淡红沉积。"},{"text":"心肌细胞水变性","reason":"水变性位于细胞内，细胞肿胀、胞质淡染；本图改变突出于血管周围。"},{"text":"纤维素性心包炎","reason":"纤维素多附着于心包表面形成网状、丝状渗出，本图为血管周围沉积。"}],"caution":"确认淀粉样物通常需刚果红染色及偏振光检查；本图不能显示苹果绿色双折光。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":812,"annotations":{"marks":[{"x":80,"y":53,"rx":15,"ry":32,"label":"血管壁周围均质沉积","detail":"血管周围较厚的淡红色、细胞较少的均质物与旁侧脂肪组织不同。"},{"x":21,"y":79,"rx":13,"ry":18,"label":"另一处嗜酸性沉积","detail":"这里亦可见均质淡红物，显示沉积并非单一视野偶然结构。"}],"note":"HE 形态不能替代刚果红染色或偏振光确证。"}},{"id":"s004","name":"淋巴结结核（结核性肉芽肿）","kind":"镜下","system":"炎症与修复","image":"assets/s004.jpg","points":["识别关键词：上皮样细胞结节伴多核巨细胞和周围淋巴细胞。","可见胞质较丰富、淡染的上皮样细胞聚集，与周围深染小淋巴细胞形成对比。","结节内有多核巨细胞；结合本套相邻视野的干酪样坏死支持结核性肉芽肿。"],"options":[{"text":"淋巴结结核（结核性肉芽肿）","reason":"识别关键词：上皮样细胞结节伴多核巨细胞和周围淋巴细胞。"},{"text":"异物肉芽肿","reason":"应寻找异物及围绕异物的巨细胞；本图为上皮样细胞结节，未见明确异物。"},{"text":"化脓性炎症","reason":"化脓以大量中性粒细胞和液化坏死为主，不形成这样的上皮样细胞结节。"},{"text":"反应性淋巴滤泡增生","reason":"滤泡以淋巴细胞及生发中心为主，不应以多核巨细胞和上皮样细胞为中心。"}],"caution":"朗汉斯型巨细胞并非结核特异，需结合上皮样细胞结节与干酪样坏死判断。","review":"reviewed","scope":"core","imageWidth":947,"imageHeight":1400,"annotations":{"marks":[{"x":34,"y":31,"rx":29,"ry":23,"label":"多核巨细胞","detail":"一个较大胞体内可见多个细胞核，部分核位于周边。"},{"x":83,"y":43,"rx":13,"ry":25,"label":"周围淋巴细胞","detail":"外侧有大量胞质少、深染的小淋巴细胞，与巨细胞区形成对照。"}],"note":"多核巨细胞并不特异，需结合上皮样细胞结节与干酪样坏死判断。"}},{"id":"s005","name":"肝细胞脂肪变性","kind":"镜下","system":"细胞适应与损伤","image":"assets/s005.jpg","points":["识别关键词：肝细胞内大小不等的空泡，较大空泡可将细胞核挤向一侧。","肝细胞胞质出现边界较清楚的透明脂滴空隙，大小不一，有的融合占据大部分胞体。","仍可辨认肝细胞索及肝窦；改变发生在肝细胞内，而非细胞外沉积。"],"options":[{"text":"肝细胞脂肪变性","reason":"识别关键词：肝细胞内大小不等的空泡，较大空泡可将细胞核挤向一侧。"},{"text":"肝细胞水变性","reason":"水变性通常为细胞肿胀、胞质淡染或细小空泡，典型大脂滴可把核挤向一侧。"},{"text":"肝淤血","reason":"淤血核心是中央静脉与肝窦扩张充满红细胞；本图突出的是胞内透明脂滴。"},{"text":"肝细胞凝固性坏死","reason":"坏死表现为胞质嗜酸性增强及核固缩、碎裂或消失，不是大量清亮脂滴。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":712,"annotations":{"marks":[{"x":62,"y":53,"rx":18,"ry":31,"label":"肝细胞内脂滴空泡","detail":"许多细胞内有大小不一、边界较清楚的透明空泡，部分占据大半胞体。"}],"note":""}},{"id":"s006","name":"肾小管上皮细胞水变性","kind":"镜下","system":"细胞适应与损伤","image":"assets/s006.jpg","points":["识别关键词：肾小管上皮肿胀、胞质疏松淡染，管腔受挤变窄。","可见小管上皮细胞体积增大，胞质内出现细小淡染空泡样改变。","细胞核大多仍在；以细胞肿胀为主而非整片核消失、组织坏死。"],"options":[{"text":"肾小管上皮细胞水变性","reason":"识别关键词：肾小管上皮肿胀、胞质疏松淡染，管腔受挤变窄。"},{"text":"肾贫血性梗死","reason":"梗死为成片凝固性坏死，可见管状轮廓残留但核消失。"},{"text":"肾淀粉样变性","reason":"淀粉样沉积主要在肾小球、血管等细胞外部位，呈均质淡红色。"},{"text":"肾小管上皮脂肪变性","reason":"脂肪变性以较清楚的脂滴空泡为特点，本标本主要是弥漫细胞肿胀和疏松。"}],"caution":"依据细胞肿胀识别水变性；单凭 HE 中的空泡不能判定其化学成分。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":700,"annotations":{"marks":[{"x":49,"y":64,"rx":16,"ry":28,"label":"肿胀的小管上皮","detail":"小管上皮胞质淡染、疏松，细胞肿胀并使管腔相对变窄。"}],"note":"小管腔与细胞内淡染区需分开观察。"}},{"id":"s007","name":"肉芽组织","kind":"镜下","system":"炎症与修复","image":"assets/s007.jpg","points":["识别关键词：新生毛细血管＋成纤维细胞＋炎细胞。","可见薄壁小血管，内皮细胞较饱满，部分管腔含红细胞。","血管间散在梭形成纤维细胞和炎细胞，间质较疏松，尚未形成致密成熟瘢痕。"],"options":[{"text":"肉芽组织","reason":"识别关键词：新生毛细血管＋成纤维细胞＋炎细胞。"},{"text":"结核性肉芽肿","reason":"肉芽肿是上皮样细胞/巨噬细胞结节；与修复中的肉芽组织不同。"},{"text":"成熟瘢痕组织","reason":"成熟瘢痕以致密胶原为主，血管和细胞较少。"},{"text":"纤维肉瘤","reason":"纤维肉瘤以异型梭形肿瘤细胞密集增生为主，不是三种修复成分的组合。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":740,"annotations":{"marks":[{"x":44,"y":35,"rx":15,"ry":29,"label":"新生毛细血管","detail":"薄壁小管腔内有红细胞，周围内皮细胞较饱满。"},{"x":31,"y":81,"rx":9,"ry":10,"label":"梭形成纤维细胞","detail":"可见较长的梭形胞体和细长核，处在疏松间质中。"},{"x":41.5,"y":80,"rx":4.5,"ry":9,"label":"中性粒细胞","detail":"可见较小细胞的深染分叶核，提示修复组织内伴炎细胞。"}],"note":"三种成分结合识别肉芽组织，不等同于肉芽肿。"}},{"id":"s008","name":"肝淤血","kind":"镜下","system":"循环障碍","image":"assets/s008.jpg","points":["识别关键词：肝窦扩张、充满红细胞，邻近肝细胞受压。","肝细胞索之间可见较宽的红细胞聚集区，即扩张充血的肝窦。","部分肝细胞索变窄、排列疏松；同组低倍视野改变以小叶中央区域较突出。"],"options":[{"text":"肝淤血","reason":"识别关键词：肝窦扩张、充满红细胞，邻近肝细胞受压。"},{"text":"肝细胞脂肪变性","reason":"脂肪变性为肝细胞内透明空泡；本图主要改变在肝窦内。"},{"text":"肝脓肿","reason":"脓肿应见大量中性粒细胞和肝组织液化破坏。"},{"text":"肝硬化","reason":"肝硬化需见纤维间隔包绕再生结节形成假小叶，本图未呈现该结构。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":836,"annotations":{"marks":[{"x":63,"y":41,"rx":11,"ry":20,"label":"肝窦内红细胞聚集","detail":"肝细胞之间的窦隙可见较多小而无核的红细胞，提示淤血。"}],"note":"中央静脉与小叶分布需低倍视野观察。"}},{"id":"s009","name":"慢性肺淤血","kind":"镜下","system":"循环障碍","image":"assets/s009.jpg","points":["识别关键词：肺泡壁淤血增厚，肺泡腔见水肿液与含铁血黄素细胞。","肺泡间隔内毛细血管扩张、红细胞增多；部分肺泡腔有淡红色均质液体。","腔内可见含棕黄色颗粒的巨噬细胞，即常称的心衰细胞。"],"options":[{"text":"慢性肺淤血","reason":"识别关键词：肺泡壁淤血增厚，肺泡腔见水肿液与含铁血黄素细胞。"},{"text":"大叶性肺炎","reason":"大叶性肺炎突出肺泡腔内大量中性粒细胞及纤维素，不以含铁血黄素细胞为主。"},{"text":"肺气肿","reason":"肺气肿为气腔扩大、肺泡间隔破坏，与本图间隔淤血增厚不同。"},{"text":"肺脓肿","reason":"肺脓肿出现局灶液化坏死和大量脓细胞、组织结构破坏。"}],"caution":"含铁血黄素细胞提示既往肺泡出血，不能单独确定心衰病因。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":553,"annotations":{"marks":[{"x":76,"y":53,"rx":7,"ry":19,"label":"含棕黄色颗粒的细胞","detail":"肺泡内巨噬细胞含粗大棕黄色颗粒，符合含铁血黄素细胞形态。"},{"x":48,"y":75,"rx":7,"ry":18,"label":"肺泡腔淡红液体","detail":"肺泡腔内有较均匀淡红色物质，与水肿液相符。"}],"note":"含铁血黄素细胞反映既往肺泡出血，不单凭一个细胞确定心衰病因。"}},{"id":"s010","name":"肾贫血性梗死（凝固性坏死）","kind":"镜下","system":"循环障碍","image":"assets/s010.jpg","points":["识别关键词：细胞核消失，而肾小管和肾小球轮廓仍可辨。","坏死组织呈均一淡红色，可见残存的小管样影子，缺少正常清晰的细胞核。","这是组织结构暂存的凝固性坏死，区别于液化成脓腔的坏死。"],"options":[{"text":"肾贫血性梗死（凝固性坏死）","reason":"识别关键词：细胞核消失，而肾小管和肾小球轮廓仍可辨。"},{"text":"肾小管水变性","reason":"水变性时多数细胞核保存，主要是上皮肿胀、胞质疏松。"},{"text":"肾脓肿","reason":"脓肿以大量中性粒细胞和液化性组织破坏为主，不保留整片肾单位影子。"},{"text":"肾结核干酪样坏死","reason":"典型干酪样坏死为无结构颗粒状物，通常不保留清楚的原组织轮廓。"}],"caution":"该组另有边缘中性粒细胞视野；不能把局部炎细胞聚集直接当作此标本的主要诊断。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":887,"annotations":{"marks":[{"x":44,"y":24,"rx":12,"ry":20,"label":"坏死肾小管轮廓","detail":"肾小管的粉红轮廓仍保留，而上皮细胞核明显减少或消失，是凝固性坏死的识别点。"},{"x":55,"y":71,"rx":14,"ry":23,"label":"结构影子","detail":"大片肾小管仍能辨认原来的形状，内部细胞结构变淡，区别于完全液化的坏死。"}],"note":"散在深染核可来自残存细胞或炎细胞。"}},{"id":"s011","name":"血栓机化","kind":"镜下","system":"循环障碍","image":"assets/s011.jpg","points":["识别关键词：肉芽组织从血管壁长入血栓，使血栓逐渐纤维化。","可见血栓成分与血管壁相邻，交界附近有较疏松、富细胞的修复组织。","修复区出现成纤维细胞及新生小血管；并非单纯红细胞或纤维蛋白堆积。"],"options":[{"text":"血栓机化","reason":"识别关键词：肉芽组织从血管壁长入血栓，使血栓逐渐纤维化。"},{"text":"新鲜混合血栓","reason":"新鲜混合血栓以血小板梁、纤维蛋白及红细胞分层为主，尚无明显修复组织长入。"},{"text":"血栓溶解","reason":"溶解是血栓被纤溶系统清除；本图出现的是组织性修复。"},{"text":"动脉粥样硬化","reason":"粥样硬化主要位于内膜，常见脂质核心、胆固醇裂隙及纤维帽。"}],"caution":"机化可伴再通，但并非看到任一新生毛细血管就能认定形成了与原血流沟通的再通通道。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":702,"annotations":{"marks":[{"x":15,"y":17,"rx":12,"ry":14,"label":"残留血栓成分","detail":"左上仍见较均一的红染凝血物，与周围长入的细胞性组织形成对比。"},{"x":67,"y":62,"rx":19,"ry":27,"label":"机化组织","detail":"大量梭形细胞及纤维性间质长入血栓，体现血栓被修复组织逐渐替代。"}],"note":"本图未清楚显示完整的再通管腔。"}},{"id":"s012","name":"混合血栓","kind":"镜下","system":"循环障碍","image":"assets/s012.jpg","points":["识别关键词：淡色血小板/纤维蛋白梁与深红色红细胞区交错。","淡红色分支或条带状结构中细胞较少，其周边可伴中性粒细胞。","条带之间为较密集红细胞和纤维蛋白，形成深浅相间的层状构成。"],"options":[{"text":"混合血栓","reason":"识别关键词：淡色血小板/纤维蛋白梁与深红色红细胞区交错。"},{"text":"透明血栓","reason":"透明血栓主要是微循环中的纤维蛋白性微血栓，无此明显红白相间构成。"},{"text":"单纯红色血栓","reason":"红色血栓以红细胞为主，缺少显著血小板梁交替。"},{"text":"肉芽组织","reason":"肉芽组织应有新生毛细血管、成纤维细胞及炎细胞的修复组合。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":714,"annotations":{"marks":[{"x":84,"y":39,"rx":12,"ry":29,"label":"红细胞丰富区","detail":"右侧呈密集红染成分，与左侧较淡的血小板纤维素区形成对比。"},{"x":35,"y":55,"rx":10,"ry":18,"label":"淡染纤维素区","detail":"左侧大片淡粉红物质夹杂细胞，与红细胞丰富区交替出现，帮助识别混合血栓。"}],"note":""}},{"id":"s013","name":"异物肉芽肿","kind":"镜下","system":"炎症与修复","image":"assets/s013.jpg","points":["识别关键词：异物周围聚集巨噬细胞及异物型多核巨细胞。","局部可见深染或折光样异物成分，周围有较大的多核细胞。","多核巨细胞的细胞核散布于胞质中，伴纤维间质及慢性炎细胞反应。"],"options":[{"text":"异物肉芽肿","reason":"识别关键词：异物周围聚集巨噬细胞及异物型多核巨细胞。"},{"text":"结核性肉芽肿","reason":"结核性肉芽肿常为上皮样细胞结节，需结合干酪样坏死及病原学；本图重点是围绕异物。"},{"text":"肉芽组织","reason":"肉芽组织的核心组合为新生毛细血管、成纤维细胞及炎细胞，不以异物和巨细胞为中心。"},{"text":"急性脓肿","reason":"急性脓肿以大量中性粒细胞及液化坏死为主。"}],"caution":"仅凭巨细胞核的位置不能绝对区分病因，必须同时寻找异物。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":765,"annotations":{"marks":[{"x":43,"y":55,"rx":12,"ry":20,"label":"多核巨细胞","detail":"同一大片胞质内可见多个细胞核聚集，提示异物周围的巨细胞反应。"},{"x":60,"y":36,"rx":5,"ry":20,"label":"异物样材料","detail":"巨细胞旁可见细长、浅色而有折光感的材料，是结合巨细胞反应观察的线索。"}],"note":"材料的具体种类不能由这幅照片确定。"}},{"id":"s014","name":"慢性胆囊炎","kind":"镜下","system":"炎症与修复","image":"assets/s014.jpg","points":["识别关键词：胆囊黏膜皱襞周围慢性炎细胞浸润，间质增厚。","可见分支皱襞及其上皮，皱襞固有层与壁内有较多深染小淋巴细胞。","间质胶原增多，局部黏膜结构不整齐，炎细胞以单个核细胞为主。"],"options":[{"text":"慢性胆囊炎","reason":"识别关键词：胆囊黏膜皱襞周围慢性炎细胞浸润，间质增厚。"},{"text":"急性化脓性胆囊炎","reason":"急性化脓性病变以大量中性粒细胞为主，可伴脓性渗出和明显坏死。"},{"text":"胆囊腺癌","reason":"腺癌需见明显异型的浸润性腺体，破坏原有结构；本图以炎症和皱襞改变为主。"},{"text":"正常胆囊黏膜","reason":"正常胆囊可有皱襞，但不应有如此明显的慢性炎细胞浸润和纤维增生。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":727,"annotations":{"marks":[{"x":31,"y":67,"rx":20,"ry":27,"label":"慢性炎细胞聚集","detail":"黏膜间质内密集小圆深染细胞聚集，支持慢性炎症。"},{"x":67,"y":64,"rx":9,"ry":30,"label":"胆囊黏膜上皮","detail":"保存的高柱状上皮与其旁的炎性间质一并观察，帮助辨认胆囊黏膜背景。"}],"note":"这处上皮不能仅凭局部视野命名为罗阿窦。"}},{"id":"s015","name":"急性蜂窝织炎性阑尾炎","kind":"镜下","system":"炎症与修复","image":"assets/s015.jpg","points":["识别关键词：大量中性粒细胞弥漫浸润阑尾壁，尤其进入肌层。","粉红色平滑肌束间可见成群深染、分叶核中性粒细胞。","炎症超出黏膜局部并累及肌层，这是判断急性阑尾炎的重要镜下证据。"],"options":[{"text":"急性蜂窝织炎性阑尾炎","reason":"识别关键词：大量中性粒细胞弥漫浸润阑尾壁，尤其进入肌层。"},{"text":"慢性阑尾炎","reason":"慢性炎症以淋巴细胞、浆细胞和纤维化为主，而不是肌层大量中性粒细胞。"},{"text":"单纯黏膜淋巴滤泡增生","reason":"淋巴滤泡可见于正常阑尾，但不等于肌层中性粒细胞浸润。"},{"text":"平滑肌瘤","reason":"平滑肌瘤为界限清楚的平滑肌肿瘤，不能解释肌束间弥漫脓细胞。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":619,"annotations":{"marks":[{"x":29,"y":28,"rx":18,"ry":24,"label":"肌层炎细胞浸润","detail":"粉红色平滑肌束之间散布大量深染炎细胞，炎症已进入肌层，是蜂窝织炎性阑尾炎的要点。"},{"x":85,"y":68,"rx":10,"ry":24,"label":"肌束间炎症","detail":"另一片肌束间同样可见炎细胞，强调浸润具有弥漫分布。"}],"note":""}},{"id":"s016","name":"肺脓肿","kind":"镜下","system":"炎症与修复","image":"assets/s016.jpg","points":["识别关键词：大量中性粒细胞伴肺组织液化坏死、原有结构破坏。","脓肿区域有密集深染炎细胞及碎屑，难以辨认正常肺泡轮廓。","周边残余肺组织可见充血和炎症反应，提示局灶化脓性破坏。"],"options":[{"text":"肺脓肿","reason":"识别关键词：大量中性粒细胞伴肺组织液化坏死、原有结构破坏。"},{"text":"慢性肺淤血","reason":"淤血通常仍保留肺泡结构，可见含铁血黄素细胞，不形成大片脓性破坏。"},{"text":"肺结核干酪样坏死","reason":"典型干酪样坏死为无结构颗粒状物，周围常有结核性肉芽肿，不以密集脓细胞为主要特征。"},{"text":"大叶性肺炎","reason":"大叶性肺炎主要是肺泡腔渗出，常较好保留肺泡间隔；脓肿则破坏肺实质。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":827,"annotations":{"marks":[{"x":16,"y":53,"rx":14,"ry":29,"label":"脓性炎症区","detail":"左侧密集深染炎细胞与组织碎屑聚集，正常肺结构明显破坏，是脓肿的重点。"},{"x":73,"y":66,"rx":14,"ry":21,"label":"残存肺组织","detail":"周边仍可辨认部分肺泡样间隙，并被炎症渗出物占据，帮助确定肺组织背景。"}],"note":"此倍率不能可靠辨认单个中性粒细胞。"}},{"id":"s017","name":"纤维素性心包炎","kind":"镜下","system":"炎症与修复","image":"assets/s017.jpg","points":["识别关键词：心包表面覆盖粉红色丝网状纤维素性渗出。","表面可见粗细不一、互相交织的嗜酸性纤维素条索，夹有炎细胞。","其下组织出现充血及修复反应；主要病变位于浆膜表面。"],"options":[{"text":"纤维素性心包炎","reason":"识别关键词：心包表面覆盖粉红色丝网状纤维素性渗出。"},{"text":"心肌淀粉样变性","reason":"淀粉样物主要沉积于细胞外和血管周围，呈均质块状，而非表面网状渗出。"},{"text":"化脓性心包炎","reason":"化脓性炎症应以大量中性粒细胞和脓液为主；本图以纤维素网为突出特征。"},{"text":"心包脂肪浸润","reason":"脂肪细胞是透明的大空泡状细胞，不呈丝网状嗜酸性物。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1346,"imageHeight":1400,"annotations":{"marks":[{"x":78,"y":37,"rx":15,"ry":26,"label":"表面纤维素渗出","detail":"心外膜表面覆盖明显红染、网状或层状的物质，是纤维素性炎的关键。"},{"x":12,"y":40,"rx":10,"ry":25,"label":"下方心肌","detail":"左侧保留成群红染心肌细胞，与右侧表面渗出层形成器官定位关系。"}],"note":"先看心肌—心外膜—表面渗出的空间关系。"}},{"id":"s018","name":"恶性黑色素瘤","kind":"镜下","system":"肿瘤","image":"assets/s018.jpg","points":["识别关键词：异型肿瘤细胞伴胞质内棕褐色黑色素颗粒。","肿瘤细胞大小不一、核增大深染，可见较明显核仁。","部分细胞含棕褐色颗粒；结合异型细胞增生，区别于单纯色素沉着。"],"options":[{"text":"恶性黑色素瘤","reason":"识别关键词：异型肿瘤细胞伴胞质内棕褐色黑色素颗粒。"},{"text":"色素痣","reason":"普通痣细胞通常较一致并随深度成熟，明显核异型及异常增殖提示恶性。"},{"text":"色素性基底细胞癌","reason":"基底细胞癌应见较一致的基底样细胞巢、外周栅栏及巢周裂隙；本图以异型含色素细胞为主。"},{"text":"含铁血黄素沉着","reason":"含铁血黄素常在巨噬细胞中，不应据此产生具有明显异型的肿瘤细胞群。"}],"caution":"色素并非黑色素瘤的必备条件；无色素病例需结合形态及免疫组化，不能只靠颜色诊断。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":641,"annotations":{"marks":[{"x":39,"y":74,"rx":8,"ry":17,"label":"棕褐色素","detail":"肿瘤细胞周围和胞质中可见棕褐色颗粒，结合细胞异型识别黑色素瘤。"},{"x":65,"y":55,"rx":10,"ry":19,"label":"异型肿瘤细胞","detail":"细胞和细胞核大小不一，核较大且形态不规则，不能只凭色素多少判断恶性。"}],"note":""}},{"id":"s019","name":"结肠腺癌","kind":"镜下","system":"肿瘤","image":"assets/s019.jpg","points":["识别关键词：异型腺体拥挤、形状不规则，腺腔可见污秽坏死。","腺上皮核增大深染、层次增多，正常规则平行的隐窝排列被破坏。","腺体大小不一且相互挤靠，腔内可见嗜酸性坏死碎屑与核碎片。"],"options":[{"text":"结肠腺癌","reason":"识别关键词：异型腺体拥挤、形状不规则，腺腔可见污秽坏死。"},{"text":"正常结肠黏膜","reason":"正常隐窝排列规则，杯状细胞较多，核位于基底且较一致。"},{"text":"结肠腺瘤","reason":"腺瘤可有上皮异型，但浸润性腺体、间质反应及破坏性生长支持癌；需综合全片判断。"},{"text":"低分化鳞状细胞癌","reason":"鳞癌应寻找鳞状细胞巢、细胞间桥或角化，本图呈明确异常腺体。"}],"caution":"浸润深度和分期需要完整切片，不能由单个视野确定。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":588,"annotations":{"marks":[{"x":31,"y":48,"rx":18,"ry":34,"label":"拥挤的异型腺体","detail":"腺体形状不规则且排列拥挤，细胞核深染、重叠和失去正常极性，是腺癌形态的重点。"},{"x":73,"y":38,"rx":11,"ry":30,"label":"腺腔坏死碎屑","detail":"扩大的腺腔中可见红染碎屑和脱落细胞，可与异常腺上皮一起观察。"}],"note":"局部癌腺与细胞异型不足以确定全瘤分级。"}},{"id":"s020","name":"卵巢黏液性囊腺瘤","kind":"镜下","system":"肿瘤","image":"assets/s020.jpg","points":["识别关键词：囊壁衬覆较规则的单层高柱状黏液上皮。","上皮胞质淡染、含黏液，细胞核较整齐地位于基底部。","其下为纤维性囊壁，所示视野未见明显复杂异型增生或破坏性间质浸润。"],"options":[{"text":"卵巢黏液性囊腺瘤","reason":"识别关键词：囊壁衬覆较规则的单层高柱状黏液上皮。"},{"text":"卵巢黏液性癌","reason":"黏液性癌需有明显复杂/融合腺体或破坏性浸润等证据，不能仅凭黏液性上皮命名为癌。"},{"text":"卵巢浆液性囊腺瘤","reason":"浆液性囊腺瘤多为输卵管型上皮，可见纤毛；本图上皮高柱状、黏液胞质明显。"},{"text":"成熟性囊性畸胎瘤","reason":"畸胎瘤需见不同胚层的成熟组织，如皮肤附属器、软骨等，非单一黏液性囊壁。"}],"caution":"本题给定良性诊断；卵巢黏液性肿瘤可有异质性，良恶性评价需充分取材。","review":"reviewed","scope":"core","imageWidth":1181,"imageHeight":703,"annotations":{"marks":[{"x":32,"y":50,"rx":8,"ry":32,"label":"黏液性柱状上皮","detail":"囊壁衬覆一层较高的柱状细胞，胞质浅染、核偏基底侧，是黏液性上皮的要点。"},{"x":49,"y":51,"rx":10,"ry":29,"label":"纤维性囊壁","detail":"上皮下为梭形细胞和胶原性间质，结合上皮与囊腔判断囊性肿瘤结构。"}],"note":"良恶性评价需充分观察完整囊壁。"}},{"id":"s021","name":"乳腺纤维腺瘤","kind":"镜下","system":"肿瘤","image":"assets/s021.jpg","points":["识别关键词：增生纤维间质挤压乳腺导管，使腔隙呈裂隙或分支状。","可见丰富淡红色纤维间质，间质细胞较均一，缺少明显恶性异型。","导管仍保留上皮衬覆，受压变扁或呈细长裂隙，体现上皮与间质双相结构。"],"options":[{"text":"乳腺纤维腺瘤","reason":"识别关键词：增生纤维间质挤压乳腺导管，使腔隙呈裂隙或分支状。"},{"text":"浸润性乳腺癌","reason":"浸润癌多为不规则异型腺管或细胞巢浸润间质，并破坏正常肌上皮层。"},{"text":"乳腺脂肪瘤","reason":"脂肪瘤主要由成熟脂肪细胞组成，不是纤维间质与受压导管组合。"},{"text":"乳腺叶状肿瘤","reason":"叶状肿瘤突出叶状裂隙、较富细胞间质和腺周间质凝集，需全片鉴别。"}],"caution":"与叶状肿瘤的边界需要结合整体结构和间质细胞性，不能仅凭一个裂隙状导管。","review":"reviewed","scope":"core","imageWidth":1266,"imageHeight":1400,"annotations":{"marks":[{"x":75,"y":24,"rx":21,"ry":6,"label":"受压裂隙状导管","detail":"导管仍有上皮衬覆，但被周围间质压成长而弯曲的裂隙，是纤维腺瘤常见线索。"},{"x":84,"y":48,"rx":11,"ry":14,"label":"增生纤维间质","detail":"大片纤维性间质内可见形态较温和的梭形细胞，与导管共同构成双相结构。"}],"note":"导管与间质要配合观察，不能把任何受压腺管都单独认定为纤维腺瘤。"}},{"id":"s022","name":"皮肤基底细胞癌","kind":"镜下","system":"肿瘤","image":"assets/s022.jpg","points":["识别关键词：基底样细胞巢＋外周栅栏状排列＋巢周裂隙。","肿瘤细胞核深染、胞质少，形成真皮内的大小不等细胞巢。","细胞巢边缘细胞核较整齐排列，巢与周围间质间可见收缩裂隙。"],"options":[{"text":"皮肤基底细胞癌","reason":"识别关键词：基底样细胞巢＋外周栅栏状排列＋巢周裂隙。"},{"text":"皮肤鳞状细胞癌","reason":"鳞癌细胞胞质相对丰富，应寻找角化珠和细胞间桥。"},{"text":"恶性黑色素瘤","reason":"黑色素瘤的细胞异型和核仁常突出，不呈典型基底样巢外周栅栏结构。"},{"text":"皮肤乳头状瘤","reason":"乳头状瘤为覆鳞状上皮的乳头状外生结构，有纤维血管轴心。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":792,"annotations":{"marks":[{"x":30,"y":50,"rx":23,"ry":31,"label":"基底样癌巢","detail":"成团细胞核深染、胞质少，形成较致密的基底样上皮细胞巢。"},{"x":45,"y":29,"rx":17,"ry":9,"label":"巢周浅染间隙","detail":"癌巢与周围间质之间存在浅染分离带，可结合基底样细胞巢识别。"}],"note":"本图癌巢较清楚，边缘栅栏排列不够清晰。"}},{"id":"s023","name":"皮肤高分化鳞状细胞癌","kind":"镜下","system":"肿瘤","image":"assets/s023.jpg","points":["识别关键词：浸润性鳞状细胞巢内形成角化珠。","细胞巢中央有同心圆层状、强嗜酸性的角化物，外围为鳞状肿瘤细胞。","肿瘤细胞胞质较丰富、核有异型；同组高倍视野可见细胞间桥。"],"options":[{"text":"皮肤高分化鳞状细胞癌","reason":"识别关键词：浸润性鳞状细胞巢内形成角化珠。"},{"text":"皮肤基底细胞癌","reason":"基底细胞癌以胞质少的深染细胞巢和外周栅栏为主，通常不形成典型角化珠。"},{"text":"皮肤乳头状瘤","reason":"乳头状瘤常有表面角化，但保持乳头状结构与上皮成熟层次，不呈浸润性癌巢。"},{"text":"腺癌","reason":"腺癌形成腺管或分泌黏液，不以角化珠和鳞状细胞巢为特征。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":1123,"annotations":{"marks":[{"x":55,"y":51,"rx":20,"ry":40,"label":"角化珠","detail":"癌巢中央呈同心层状、强红染的角化物，是高分化鳞癌最醒目的线索。"},{"x":86,"y":69,"rx":10,"ry":24,"label":"异型鳞状细胞","detail":"角化区周围细胞核大小与染色不均，结合癌巢内角化判断鳞状分化。"}],"note":"中央裂隙可有制片影响；重点看其外围的同心角化层。"}},{"id":"s024","name":"皮肤乳头状瘤","kind":"镜下","system":"肿瘤","image":"assets/s024.jpg","points":["识别关键词：鳞状上皮向表面形成乳头状突起，内含纤维血管轴心。","上皮增厚且表面角化增多，但仍可见较规则的成熟分层。","乳头内部为结缔组织与血管，未见本视野内的破坏性浸润癌巢。"],"options":[{"text":"皮肤乳头状瘤","reason":"识别关键词：鳞状上皮向表面形成乳头状突起，内含纤维血管轴心。"},{"text":"皮肤鳞状细胞癌","reason":"鳞癌应见异型鳞状细胞破坏性浸润，常有不规则癌巢和角化珠。"},{"text":"结肠管状腺瘤","reason":"结肠腺瘤由腺上皮构成，出现异型腺管；本图为分层鳞状上皮。"},{"text":"皮肤基底细胞癌","reason":"基底细胞癌形成真皮内基底样细胞巢，外周栅栏明显。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":963,"imageHeight":1400,"annotations":{"marks":[{"x":27,"y":24,"rx":16,"ry":12,"label":"乳头状上皮突起","detail":"增厚的成熟鳞状上皮向外形成分支状突起，是乳头状生长的结构线索。"},{"x":42,"y":47,"rx":9,"ry":10,"label":"纤维血管轴心","detail":"上皮突起内部有浅染间质伸入，需连同外覆上皮一起辨认乳头结构。"}],"note":"以低倍整体外生结构为主，不从局部角化厚度判断恶性。"}},{"id":"s025","name":"子宫平滑肌瘤","kind":"镜下","system":"肿瘤","image":"assets/s025.jpg","points":["识别关键词：均一梭形平滑肌细胞交织成束，细胞核呈雪茄状。","可见纵切与横切肌束相互交错，胞质丰富、嗜酸性。","细胞核两端较钝、大小较一致，所示视野缺乏明显异型及坏死。"],"options":[{"text":"子宫平滑肌瘤","reason":"识别关键词：均一梭形平滑肌细胞交织成束，细胞核呈雪茄状。"},{"text":"纤维瘤","reason":"纤维瘤胶原较丰富，梭形细胞核常较细长尖细，胞质不如平滑肌丰富。"},{"text":"平滑肌肉瘤","reason":"需结合明显细胞异型、核分裂活跃和肿瘤性坏死等标准；本图为较温和的束状肌细胞。"},{"text":"纤维肉瘤","reason":"纤维肉瘤常见密集异型梭形细胞，排列可呈鱼骨状，核异型较明显。"}],"caution":"本题给定平滑肌瘤诊断；良恶性评价仍需充分取材并观察高倍核分裂。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":651,"annotations":{"marks":[{"x":31,"y":56,"rx":25,"ry":30,"label":"交错平滑肌束","detail":"红染梭形细胞成束交错，细胞核较长而形态相对一致，支持平滑肌性肿瘤结构。"}],"note":"观察梭形细胞束的均一性；右侧血管腔不是肿瘤腺腔。"}},{"id":"s026","name":"纤维肉瘤","kind":"镜下","system":"肿瘤","image":"assets/s026.jpg","points":["识别关键词：密集异型梭形细胞交错成束，核深染且大小不一。","肿瘤细胞呈长梭形，束与束方向不同，间有不等量胶原。","与良性纤维瘤相比，细胞更密集、核拥挤深染且异型更明显。"],"options":[{"text":"纤维肉瘤","reason":"识别关键词：密集异型梭形细胞交错成束，核深染且大小不一。"},{"text":"卵巢纤维瘤","reason":"良性纤维瘤细胞通常较温和，胶原较丰富，明显异型与高细胞密度不突出。"},{"text":"平滑肌瘤","reason":"平滑肌瘤细胞胞质嗜酸性丰富，核两端较钝、大小较一致。"},{"text":"肉芽组织","reason":"肉芽组织有新生毛细血管、成纤维细胞和炎细胞混合，不是密集异型梭形细胞肿瘤。"}],"caution":"本题给定纤维肉瘤诊断；梭形细胞肉瘤的确切分型需结合免疫组化及必要的分子检测。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":577,"annotations":{"marks":[{"x":28,"y":53,"rx":14,"ry":30,"label":"密集梭形细胞","detail":"细胞密度增高，梭形细胞排列交错，是需要与良性纤维性病变对照的区域。"},{"x":63,"y":40,"rx":10,"ry":25,"label":"核异型代表区","detail":"细胞核深染、大小和形态不一，部分明显增大，提示恶性间叶性形态。"}],"note":"此高倍视野未展示完整人字形排列，可观察细胞密度与核异型。"}},{"id":"s027","name":"卵巢纤维瘤","kind":"镜下","system":"肿瘤","image":"assets/s027.jpg","points":["识别关键词：较温和的梭形细胞与丰富胶原纤维束交织。","细胞核细长、两端较尖，细胞间可见淡红色波浪状胶原。","细胞大小较一致，所示视野未见明显异型、异常核分裂或肿瘤坏死。"],"options":[{"text":"卵巢纤维瘤","reason":"识别关键词：较温和的梭形细胞与丰富胶原纤维束交织。"},{"text":"纤维肉瘤","reason":"纤维肉瘤通常细胞更密集，核异型、核分裂等恶性证据更明显。"},{"text":"平滑肌瘤","reason":"平滑肌瘤胞质更丰富嗜酸性，核常呈两端钝圆的雪茄状。"},{"text":"卵巢黏液性囊腺瘤","reason":"黏液性囊腺瘤需有囊腔和黏液上皮衬覆，不是单一梭形间质肿瘤。"}],"caution":"卵巢部位为题设条件；单张梭形细胞图不能独立确定器官来源。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":585,"annotations":{"marks":[{"x":36,"y":57,"rx":22,"ry":29,"label":"胶原丰富区","detail":"大片粉红胶原纤维之间夹有细长梭形细胞，是纤维性肿瘤的代表视野。"},{"x":77,"y":55,"rx":12,"ry":28,"label":"温和梭形细胞","detail":"细胞核较细长、形态较一致，缺少本图可见的显著多形性。"}],"note":"单凭纤维组织不能确定卵巢来源。"}},{"id":"s028","name":"乳腺浸润性癌（腺管形成型）","kind":"镜下","system":"肿瘤","image":"assets/s028.jpg","points":["识别关键词：不规则异型腺管及癌细胞巢浸润纤维间质。","腺体大小、形状不一，分布杂乱，周围有明显间质增生反应。","腺上皮细胞核深染、拥挤，正常乳腺小叶的整齐结构被破坏。"],"options":[{"text":"乳腺浸润性癌（腺管形成型）","reason":"识别关键词：不规则异型腺管及癌细胞巢浸润纤维间质。"},{"text":"乳腺纤维腺瘤","reason":"纤维腺瘤由温和纤维间质与保留衬覆的受压导管构成，整体较规则。"},{"text":"正常乳腺小叶","reason":"正常小叶腺泡成簇、排列规则且细胞温和，不形成破坏性浸润结构。"},{"text":"乳腺脂肪坏死","reason":"脂肪坏死应见坏死脂肪细胞、泡沫细胞和巨细胞等，不是异型浸润腺管。"}],"caution":"具体组织学分型、分级及肌上皮状态需结合全片和必要的免疫组化。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":601,"annotations":{"marks":[{"x":25,"y":31,"rx":12,"ry":23,"label":"异型腺管","detail":"腺管内细胞核较大、排列不整齐，腺体形状不规则，是浸润性腺癌的形态线索。"},{"x":85,"y":65,"rx":12,"ry":23,"label":"间质内癌管","detail":"不规则腺管分散在纤维性间质中，呈杂乱分布，区别于整齐的小叶腺泡。"}],"note":"本图不能确定肌上皮状态或具体分级。"}},{"id":"s029","name":"胃黏液癌（印戒细胞形态）","kind":"镜下","system":"肿瘤","image":"assets/s029.jpg","points":["识别关键词：胞质内黏液使细胞核偏位，形成印戒样细胞。","可见散在或小群肿瘤细胞，胞质淡染或空泡状，核被挤向细胞边缘。","背景含较多淡染黏液样物，缺少规则、成熟的正常胃腺体排列。"],"options":[{"text":"胃黏液癌（印戒细胞形态）","reason":"识别关键词：胞质内黏液使细胞核偏位，形成印戒样细胞。"},{"text":"胃高分化管状腺癌","reason":"管状腺癌以较明确的异型腺管为主，而本图突出散在印戒样细胞。"},{"text":"脂肪细胞","reason":"成熟脂肪细胞通常体积更大、核扁平，成片构成脂肪组织，而不是散在异型上皮细胞。"},{"text":"普通黏液细胞增生","reason":"良性黏液细胞多保持规则腺体结构和整齐细胞排列，不能解释散在异型细胞。"}],"caution":"本图识别印戒细胞形态；黏液腺癌与印戒细胞癌并非完全同义。","review":"reviewed","scope":"core","imageWidth":1800,"imageHeight":525,"annotations":{"marks":[{"x":37,"y":32,"rx":5.5,"ry":17,"label":"印戒样细胞","detail":"胞质内大空泡把深染细胞核挤向一侧，形成典型印戒外形。"},{"x":41.5,"y":60,"rx":6,"ry":17,"label":"偏位的细胞核","detail":"另一细胞的核被推到边缘，需把胞质空泡与偏位核看作同一个细胞。"}],"note":"印戒细胞形态不能代表黏液癌的全部表现。"}},{"id":"l008","name":"肾干酪样坏死（肾结核）","kind":"大体","system":"泌尿系统","image":"assets/l008.jpg","points":["核心词：肾内多发空洞＋灰黄、碎屑状坏死物。","肾原有结构遭破坏，多个不规则空腔内留有灰白至灰黄色坏死组织。","易混：肾积水以肾盂肾盏扩张、实质变薄为主；结核还有明显坏死碎屑和组织破坏。"],"options":[{"text":"肾干酪样坏死（肾结核）","reason":"符合本图：核心词：肾内多发空洞＋灰黄、碎屑状坏死物。"},{"text":"肾压迫性萎缩","reason":"重点是肾盂肾盏扩张及皮质变薄，不能解释本图多灶干酪样坏死。"},{"text":"肾贫血性梗死","reason":"典型是外周楔形灰白病灶，而不是多发含碎屑空洞。"},{"text":"肾透明细胞癌","reason":"通常见黄白色实体肿块，可伴出血坏死，本图以多灶空洞和坏死物为主。"}],"caution":"本题为已知诊断标本；结核病原的确认需结合镜检或病原学，不能只靠颜色。","review":"reviewed","scope":"extension","imageWidth":368,"imageHeight":405,"annotations":{"marks":[{"x":82,"y":27,"rx":12,"ry":14,"label":"空洞及坏死碎屑","detail":"肾实质内不规则空洞的壁和腔内留有灰白、松碎样组织，体现干酪样破坏。"},{"x":43,"y":58,"rx":14,"ry":12,"label":"灰黄坏死物","detail":"较实的灰黄碎屑状坏死物与其他空洞并存，区别于单纯光滑的积水扩张。"}],"note":"照片只显示大体形态，不能据颜色单独确认结核病原。"}},{"id":"l013","name":"鳞状上皮化生","kind":"镜下","system":"细胞适应与损伤","image":"assets/l013.jpg","points":["核心词：腺管周围出现成熟的复层鳞状上皮。","箭头处细胞层次增加，胞质较丰富，形成鳞状上皮样结构；邻近仍见柱状腺上皮。","易混：化生是成熟细胞类型改变；癌须寻找显著异型、基底膜破坏及间质浸润。"],"options":[{"text":"鳞状上皮化生","reason":"符合本图：核心词：腺管周围出现成熟的复层鳞状上皮。"},{"text":"鳞状细胞癌","reason":"应见浸润性异型癌巢，常有角化珠；单纯上皮类型改变不足以诊断癌。"},{"text":"肠上皮化生","reason":"关键是杯状细胞等肠型细胞，不是复层鳞状上皮。"},{"text":"腺癌","reason":"应有异型腺体浸润间质，本图考点是成熟上皮类型的替换。"}],"caution":"本题只考鳞状上皮化生，不能由局部视野单独确定器官。","review":"reviewed","scope":"extension","imageWidth":542,"imageHeight":405,"annotations":{"marks":[{"x":51,"y":49,"rx":12,"ry":21,"label":"鳞状上皮样细胞层","detail":"腺管旁出现较厚的多层上皮，胞质较丰富，形成成熟鳞状上皮样结构。"},{"x":73,"y":26,"rx":10,"ry":14,"label":"邻近腺上皮","detail":"旁边仍可见有腔的腺体，与变为多层鳞状结构的区域形成对照。"}],"note":"局部上皮类型变化不能单独确定器官或诊断癌。"}},{"id":"l014","name":"胃黏膜肠上皮化生","kind":"镜下","system":"消化系统","image":"assets/l014.jpg","points":["核心词：胃黏膜内出现杯状细胞。","可见胞质浅染、含黏液空泡的杯状细胞，夹在柱状细胞之间；旁边仍有胃腺组织。","易混：脂肪变是实质细胞内脂滴空泡；肠化生的浅染细胞位于腺体上皮并有杯状外形。"],"options":[{"text":"胃黏膜肠上皮化生","reason":"符合本图：核心词：胃黏膜内出现杯状细胞。"},{"text":"鳞状上皮化生","reason":"应形成多层鳞状上皮，不会以杯状细胞为特征。"},{"text":"胃腺癌","reason":"需要明显异型腺体及浸润证据，不能把出现杯状细胞直接等同于癌。"},{"text":"肝脂肪变性","reason":"空泡位于肝细胞内并呈小叶结构，本图为黏膜腺体和杯状细胞。"}],"caution":"照片未充分显示所有肠型细胞，不要求认出潘氏细胞。","review":"reviewed","scope":"extension","imageWidth":1000,"imageHeight":735,"annotations":{"marks":[{"x":73.5,"y":57,"rx":5,"ry":12,"label":"杯状细胞","detail":"腺上皮内多个黏液空泡样浅染细胞呈杯状外形，是肠上皮化生的关键。"},{"x":16,"y":59,"rx":14,"ry":22,"label":"邻近胃腺","detail":"左侧保留较红染的胃腺，与右侧出现杯状细胞的上皮相对照。"}],"note":"浅染杯状细胞位于腺体上皮内，注意与腺腔空白区区别。"}},{"id":"l015","name":"营养不良性钙化","kind":"镜下","system":"细胞适应与损伤","image":"assets/l015.jpg","points":["核心词：病变组织内深蓝紫色、不规则钙盐团块。","钙化区呈粗大嗜碱性颗粒或块状，周边是淡染纤维组织。","易混：玻璃样变通常均质粉红；营养不良性钙化发生在受损组织，血钙可以正常。"],"options":[{"text":"营养不良性钙化","reason":"符合本图：核心词：病变组织内深蓝紫色、不规则钙盐团块。"},{"text":"玻璃样变","reason":"典型为均质、嗜酸性粉红物质；本图是强嗜碱性蓝紫色团块。"},{"text":"含铁血黄素沉着","reason":"通常表现为棕黄色颗粒，普鲁士蓝可验证；不是大片蓝紫钙盐。"},{"text":"干酪样坏死","reason":"一般为无结构的粉红颗粒状坏死物，钙化可继发其上但不是同一个概念。"}],"caution":"转移性钙化与钙磷代谢异常有关，常累及原本未受损组织；本图不能反映血钙水平。","review":"reviewed","scope":"extension","imageWidth":894,"imageHeight":579,"annotations":{"marks":[{"x":56,"y":48,"rx":34,"ry":39,"label":"蓝紫色钙盐团块","detail":"病变区域出现大片强嗜碱性的粗颗粒及块状沉积，颜色与周边粉红纤维组织明显不同。"}],"note":"本图不能反映血钙水平。"}},{"id":"l018","name":"脾包膜玻璃样变","kind":"镜下","system":"细胞适应与损伤","image":"assets/l018.jpg","points":["核心词：表面包膜明显增厚＋均质粉红。","表层是宽厚、平滑、细胞很少的红染胶原带；下方为细胞丰富的脾实质。","易混：肉芽组织血管与细胞丰富；玻璃样变的包膜以均质胶原和细胞稀少为主。"],"options":[{"text":"脾包膜玻璃样变","reason":"符合本图：核心词：表面包膜明显增厚＋均质粉红。"},{"text":"肉芽组织","reason":"应见较多新生毛细血管、成纤维细胞和炎细胞，与均质少细胞胶原带不同。"},{"text":"脾小动脉玻璃样变","reason":"病变围绕小血管管腔，本图病变是器官表面的宽厚包膜。"},{"text":"干酪样坏死","reason":"通常为失去组织结构的颗粒状坏死灶，周围可有肉芽肿，不呈整齐的包膜胶原带。"}],"caution":"","review":"reviewed","scope":"extension","imageWidth":955,"imageHeight":456,"annotations":{"marks":[{"x":52,"y":37,"rx":39,"ry":18,"label":"增厚玻璃样包膜","detail":"表层为宽厚、均质粉红且细胞很少的胶原带，是包膜玻璃样变的重点。"},{"x":39,"y":78,"rx":30,"ry":14,"label":"下方脾实质","detail":"下方组织染色较深、细胞丰富，与上方均质少细胞包膜形成对照。"}],"note":"需按表面包膜与下方实质的位置关系判断，不把整张红染组织都叫玻璃样变。"}},{"id":"l019","name":"脾小动脉玻璃样变","kind":"镜下","system":"循环障碍","image":"assets/l019.jpg","points":["核心词：小血管壁均质红染增厚、管腔变小。","淋巴组织内多个圆形小血管，管壁呈无结构、嗜酸性的厚环。","易混：淀粉样变可呈嗜酸性沉积，但特殊染色证实不同；玻璃样小动脉硬化着重看管壁和狭小管腔。"],"options":[{"text":"脾小动脉玻璃样变","reason":"符合本图：核心词：小血管壁均质红染增厚、管腔变小。"},{"text":"脾包膜玻璃样变","reason":"累及表面包膜形成宽带，不是多个血管周围的同心厚环。"},{"text":"血栓机化","reason":"新生血管和纤维组织长入血栓，病变主体在原管腔；本图为管壁均质增厚。"},{"text":"营养不良性钙化","reason":"应为深蓝紫色嗜碱性颗粒团块，不是均质粉红管壁。"}],"caution":"仅识别玻璃样血管改变，不由照片推断患者是否患高血压。","review":"reviewed","scope":"extension","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":48,"y":62,"rx":6,"ry":10,"label":"玻璃样增厚管壁","detail":"小血管壁形成均质粉红的厚环，中央残余管腔明显变小。"},{"x":20,"y":24,"rx":9,"ry":9,"label":"另一受累小动脉","detail":"另一小动脉同样呈粉红厚壁和狭小管腔，说明改变涉及多个小血管。"}],"note":"玻璃样变位于管壁，不是管腔内血栓；不能据图推断血压。"}},{"id":"l027","name":"肺动脉血栓栓塞","kind":"大体","system":"循环障碍","image":"assets/l027.jpg","points":["核心词：肺动脉管腔内被暗红血栓样栓子堵塞。","心肺联合标本中，已剖开的肺动脉内可见长条状暗色凝血物，箭头指向管腔内堵塞部位。","易混：心脏附壁血栓贴附心腔壁；肺梗死是肺实质内的楔形坏死灶，本图重点在肺动脉腔内。"],"options":[{"text":"肺动脉血栓栓塞","reason":"符合本图：核心词：肺动脉管腔内被暗红血栓样栓子堵塞。"},{"text":"心脏附壁血栓","reason":"病变位于心腔壁表面，本图标示的是肺动脉管腔内的栓塞。"},{"text":"肺出血性梗死","reason":"主要表现为肺实质胸膜下暗红楔形病灶，本图箭头指向血管腔内的凝血物。"},{"text":"主动脉粥样硬化","reason":"主要是主动脉内膜黄白斑块及粥样物，本图为肺动脉腔内血栓样栓子。"}],"caution":"栓子来源、是否粘壁及堵塞程度不能由照片完全确定；“绝不粘壁”不是绝对标准。","review":"reviewed","scope":"extension","imageWidth":285,"imageHeight":405,"annotations":{"marks":[{"x":56,"y":40,"rx":10,"ry":14,"label":"肺动脉腔内栓子","detail":"剖开的肺动脉内可见长条状暗色凝血物，绿色原箭头也指向这一管腔内区域。"}],"note":"结合心肺联合标本整体定位；照片不能验证栓子是否粘壁及其具体来源。"}},{"id":"l038","name":"脉管内癌栓","kind":"镜下","system":"肿瘤","image":"assets/l038.jpg","points":["核心词：管腔内成团异型上皮细胞。","浅染间质中可见有边界的管腔，腔内为深染的上皮性肿瘤细胞团，并形成小腺腔。","易混：普通血栓主要由红细胞、纤维素和血小板构成，不形成异型上皮性细胞团。"],"options":[{"text":"脉管内癌栓","reason":"符合本图：核心词：管腔内成团异型上皮细胞。"},{"text":"混合血栓","reason":"应见血小板纤维素与红细胞的层状结构，缺乏成团腺样癌细胞。"},{"text":"血栓机化","reason":"应见成纤维细胞和新生毛细血管长入血栓，不是管腔内腺样上皮团。"},{"text":"淋巴结结核","reason":"应有肉芽肿与干酪样坏死，不能解释管腔内异型腺上皮细胞团。"}],"caution":"本图可辨认癌栓，但局部视野不足以确定胃原发，也不能强分血管或淋巴管。","review":"reviewed","scope":"extension","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":42,"y":59,"rx":11,"ry":24,"label":"管腔内癌细胞团","detail":"有边界的腔隙内出现异型上皮团并形成小腺腔，区别于普通红细胞纤维素血栓。"},{"x":70,"y":36,"rx":9,"ry":18,"label":"第二处癌栓","detail":"另一腔隙也被上皮性细胞团占据，需同时观察其周围的脉管边界。"}],"note":"本图不可靠区分血管与淋巴管，也不能确定肿瘤原发器官。"}},{"id":"l044","name":"浆液性炎（皮肤水疱）","kind":"大体","system":"炎症与修复","image":"assets/l044.jpg","points":["核心词：局限隆起水疱＋浅黄色清亮液体。","皮肤表面有完整疱顶，疱内液体较清亮，没有大量不透明脓液。","易混：脓疱含较多中性粒细胞、液体混浊；浆液性渗出相对清亮。"],"options":[{"text":"浆液性炎（皮肤水疱）","reason":"符合本图：核心词：局限隆起水疱＋浅黄色清亮液体。"},{"text":"化脓性炎","reason":"肉眼常见混浊、黏稠脓液，本图疱液清亮，以浆液性渗出为主。"},{"text":"纤维素性炎","reason":"主要形成灰白膜状或绒毛状纤维素渗出物，不以清亮皮肤水疱为标志。"},{"text":"干性坏疽","reason":"表现为黑褐色干燥皱缩坏死组织，与清亮水疱明显不同。"}],"caution":"水疱只是炎症形态线索，不据此确定烫伤、病毒或其他具体病因。","review":"reviewed","scope":"extension","imageWidth":648,"imageHeight":684,"annotations":{"marks":[{"x":53,"y":36,"rx":18,"ry":10,"label":"清亮水疱","detail":"局部隆起的完整疱顶内为浅黄色、相对清亮液体，提示浆液性渗出形态。"}],"note":"图中水疱能显示炎症形态，不能单凭外观判断具体病因。"}},{"id":"l050","name":"肺粟粒性结核","kind":"大体","system":"感染与寄生虫","image":"assets/l050.jpg","points":["核心词：肺内密集、大小相近的粟粒样灰白小结节。","结节广泛散布于肺切面，形态相似，通常约粟粒大小，而非少数巨大的肿块。","易混：肺转移癌也可多发，但常见结节大小不一；粟粒性结核更强调细小、均匀、弥漫。"],"options":[{"text":"肺粟粒性结核","reason":"符合本图：核心词：肺内密集、大小相近的粟粒样灰白小结节。"},{"text":"肺转移癌","reason":"常见大小不一、较大的灰白球形结节；本图呈均匀细小的粟粒分布。"},{"text":"肺脓肿","reason":"以局限脓腔、组织液化及坏死碎屑为主，不是均匀密集的实性小结节。"},{"text":"大叶性肺炎","reason":"常为一肺叶较均匀的实变，不形成满布切面的独立粟粒结节。"}],"caution":"本题为已知诊断标本。其他疾病也可呈粟粒样分布，病原诊断仍需结合镜下表现及检测。","review":"reviewed","scope":"extension","imageWidth":291,"imageHeight":405,"annotations":{"marks":[{"x":65,"y":36,"rx":15,"ry":20,"label":"均匀细小结节","detail":"肺切面散布密集、大小相近的浅色小结节，呈粟粒样分布。"},{"x":70,"y":79,"rx":12,"ry":12,"label":"另一肺区同类结节","detail":"较下方也有同类细小结节，强调病变分布广泛而非单个局限肿块。"}],"note":"并非每个浅色结节都能确认为结核灶。"}},{"id":"l059","name":"宫颈炎性息肉","kind":"镜下","system":"生殖与乳腺","image":"assets/l059.jpg","points":["核心词：息肉样黏膜＋良性腺体＋炎细胞和扩张血管。","表面及腺体有黏液性柱状上皮，间质疏松、血管丰富并有炎细胞。","易混：腺癌应寻找明显异型腺体及破坏性浸润；单纯腺体拥挤或炎症不是癌。"],"options":[{"text":"宫颈炎性息肉","reason":"符合本图：核心词：息肉样黏膜＋良性腺体＋炎细胞和扩张血管。"},{"text":"宫颈腺癌","reason":"常见细胞异型与不规则浸润性腺体，本图以良性息肉及炎症间质为主要特征。"},{"text":"皮肤乳头状瘤","reason":"主要是成熟复层鳞状上皮包绕纤维血管轴心，非黏液腺体性息肉。"},{"text":"血管瘤","reason":"主体是大量增生血管腔；本图还包含表面黏膜和宫颈样腺体及炎症。"}],"caution":"","review":"reviewed","scope":"extension","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":30,"y":38,"rx":9,"ry":20,"label":"黏膜与良性腺体","detail":"黏膜表面及向内延伸的腺体保留较规则上皮，结合息肉样组织结构观察。"},{"x":74,"y":80,"rx":13,"ry":10,"label":"扩张充血血管","detail":"间质内有显著红染、形状不规则的充血血管，伴周围炎性间质支持炎性息肉背景。"}],"note":"本图不能可靠区分炎细胞类型；宫颈部位为题设条件。"}},{"id":"l066","name":"子宫内膜癌","kind":"大体","system":"生殖与乳腺","image":"assets/l066.jpg","points":["核心词：宫腔内不规则、灰黄碎屑状肿块。","剖开的子宫内膜面被不平整肿物占据，表面粗糙、可见坏死样区域。","易混：平滑肌瘤常是肌壁内界清、实性旋涡状结节；本图病变以宫腔内膜面为中心。"],"options":[{"text":"子宫内膜癌","reason":"符合本图：核心词：宫腔内不规则、灰黄碎屑状肿块。"},{"text":"子宫平滑肌瘤","reason":"典型为界清、灰白、旋涡状的肌性结节，本图是宫腔内不规则坏死样肿物。"},{"text":"子宫腺肌病","reason":"表现为肌壁弥漫增厚并有细小出血灶，不以宫腔内巨大脆碎肿物为主要表现。"},{"text":"卵巢畸胎瘤","reason":"常含皮脂、毛发等多种组织且位于卵巢，本图器官为剖开的子宫。"}],"caution":"大体图只考子宫内膜癌；“内膜样”等组织学分型需镜下证据，不据此细分。","review":"reviewed","scope":"extension","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":51,"y":35,"rx":15,"ry":26,"label":"宫腔内不规则肿物","detail":"子宫腔内被灰黄、粗糙而有碎屑样表面的肿物占据，病变以内膜面为中心。"}],"note":"周围较完整的肌壁用来帮助定位；大体图不确定具体组织学亚型。"}},{"id":"l072","name":"宫颈高级别鳞状上皮内病变（CIN Ⅲ）","kind":"镜下","system":"生殖与乳腺","image":"assets/l072.jpg","points":["核心词：几乎全层核深染拥挤＋成熟层次消失。","上皮大部分厚度均见大而深染的核，细胞排列拥挤，向表面的正常成熟过程不明显。","易混：浸润性鳞癌须出现突破基底膜并进入间质的癌巢；本图显示上皮内异常而未见明确浸润。"],"options":[{"text":"宫颈高级别鳞状上皮内病变（CIN Ⅲ）","reason":"符合本图：核心词：几乎全层核深染拥挤＋成熟层次消失。"},{"text":"正常宫颈鳞状上皮","reason":"应由基底向表面逐渐成熟、核变小、细胞变扁，与本图全层核拥挤不符。"},{"text":"宫颈轻度鳞状上皮内病变（CIN Ⅰ）","reason":"异常主要局限于下约三分之一，上层仍成熟；本图受累厚度明显更多。"},{"text":"浸润性鳞状细胞癌","reason":"需要癌细胞突破基底膜并在间质中形成浸润癌巢，本图未显示这一关键证据。"}],"caution":"本视野符合高级别鳞状上皮内病变，但不能替代完整切片的浸润评估。","review":"reviewed","scope":"extension","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":59,"y":45,"rx":23,"ry":37,"label":"上皮全层成熟紊乱","detail":"由基底向表面仍有拥挤深染的大核，正常的逐层成熟明显减弱，是高级别上皮内病变的要点。"}],"note":"需纵向观察整个上皮厚度；局部视野不能完成基底膜与微小浸润评估。"}},{"id":"l073","name":"正常宫颈鳞状上皮","kind":"镜下","system":"生殖与乳腺","image":"assets/l073.jpg","points":["核心词：从基底到表层逐渐成熟。","基底细胞较小、核较深，向表面细胞变大变扁、胞质增多、核减小。","易混：CIN Ⅲ的深染异型细胞累及大部分或全层，上皮分层成熟被打乱。"],"options":[{"text":"正常宫颈鳞状上皮","reason":"符合本图：核心词：从基底到表层逐渐成熟。"},{"text":"宫颈高级别鳞状上皮内病变（CIN Ⅲ）","reason":"应见大部分或全层细胞核深染拥挤、成熟消失；本图保留逐层成熟。"},{"text":"浸润性鳞状细胞癌","reason":"应有间质内异型癌巢、角化或明显破坏性生长，此图未见。"},{"text":"宫颈腺癌","reason":"是异型腺体增生与浸润，本图显示的是有序复层鳞状上皮。"}],"caution":"","review":"reviewed","scope":"extension","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":34,"y":37,"rx":13,"ry":17,"label":"表层成熟细胞","detail":"靠表面的细胞逐渐变扁、胞质增多，细胞核相对变小。"},{"x":64,"y":61,"rx":10,"ry":17,"label":"较深的基底层","detail":"深层细胞较小、核较深，与表层形成有序的成熟梯度，区别于全层异型。"}],"note":"上皮走向为斜向，按左上表面至右下基底侧观察，不按图片水平线分层。"}},{"id":"l075","name":"脂肪瘤","kind":"镜下","system":"肿瘤","image":"assets/l075.jpg","points":["核心词：成片成熟脂肪细胞＋边界清楚。","细胞胞质呈大空泡，细胞核扁平位于边缘，大小较均匀；图边缘可见纤维组织。","易混：脂肪肉瘤要寻找显著核异型、脂肪母细胞等；正常脂肪和脂肪瘤还须结合包膜、结节性占位。"],"options":[{"text":"脂肪瘤","reason":"符合本图：核心词：成片成熟脂肪细胞＋边界清楚。"},{"text":"脂肪肉瘤","reason":"需核异型等恶性证据，不能仅因存在脂肪空泡就诊断肉瘤。"},{"text":"肝脂肪变性","reason":"空泡位于肝细胞内，仍有肝小叶和肝细胞索结构，本图是成熟脂肪组织。"},{"text":"纤维瘤","reason":"主要由梭形纤维细胞和胶原组成，不是成片单房成熟脂肪细胞。"}],"caution":"正常脂肪与脂肪瘤的区别需结合结节、边界和临床大体，不能仅靠脂肪细胞图诊断。","review":"reviewed","scope":"extension","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":31,"y":48,"rx":23,"ry":30,"label":"成熟脂肪细胞","detail":"成片较均一的大空泡样细胞构成主体，细胞边缘仅留很薄的胞质。"},{"x":82,"y":37,"rx":7,"ry":14,"label":"边缘纤维组织","detail":"脂肪组织边缘可见粉红纤维性组织，需结合整个结节边界理解肿瘤背景。"}],"note":"正常成熟脂肪可有相似细胞，需结合结节形态与边界识别脂肪瘤。"}},{"id":"l084","name":"大网膜种植性转移瘤","kind":"大体","system":"肿瘤","image":"assets/l084.jpg","points":["核心词：黄色脂肪网膜上散在多发灰白结节。","结节大小不一，部分融合成片，分布于表面或脂肪组织内，呈多灶播散。","易混：脂肪瘤通常为单个界清黄色结节；种植性转移表现为表面广泛多发结节。"],"options":[{"text":"大网膜种植性转移瘤","reason":"符合本图：核心词：黄色脂肪网膜上散在多发灰白结节。"},{"text":"脂肪瘤","reason":"通常以黄色成熟脂肪构成的界清肿块为主，不是黄脂肪上散布大量灰白结节。"},{"text":"单发纤维瘤","reason":"多为单个边界清楚的灰白实性肿块，本图为多发播散性结节。"},{"text":"卵巢黏液性囊腺瘤","reason":"主要表现为多房囊腔，图中未见薄壁多房囊性结构。"}],"caution":"该图可辨认种植性转移的分布模式，不能仅凭大体确定胃、卵巢等原发来源。","review":"reviewed","scope":"extension","imageWidth":1000,"imageHeight":715,"annotations":{"marks":[{"x":29,"y":38,"rx":11,"ry":15,"label":"灰白种植结节","detail":"黄色网膜脂肪上出现与脂肪颜色不同的实性灰白结节。"},{"x":82,"y":54,"rx":15,"ry":24,"label":"多发融合结节","detail":"另一片区域有多个结节相连，体现网膜表面广泛播散的分布方式。"}],"note":"重点是多发、表面分布和与黄色脂肪的对比，不从大体推断原发部位。"}},{"id":"l089","name":"皮肤恶性黑色素瘤","kind":"大体","system":"肿瘤","image":"assets/l089.jpg","points":["核心词：局灶黑褐色、不规则皮肤肿块。","足背可见突出皮肤的局灶深色病变，边缘不规则，周围皮肤仍保留。","易混：足干性坏疽通常是肢端一整段黑褐色、干燥皱缩，且有相对清楚的坏死分界。"],"options":[{"text":"皮肤恶性黑色素瘤","reason":"符合本图：核心词：局灶黑褐色、不规则皮肤肿块。"},{"text":"足干性坏疽","reason":"通常累及远端一整段组织并干燥皱缩；本图是局灶色素性肿块。"},{"text":"皮肤乳头状瘤","reason":"常呈乳头状或疣状突起，不以不规则深色肿块为典型外观。"},{"text":"皮下脂肪瘤","reason":"通常为皮下柔软黄色结节，不呈表面黑褐色色素性肿块。"}],"caution":"本题给定恶性黑色素瘤诊断；恶性性质需组织学确认，颜色深不能单独证明恶性。","review":"reviewed","scope":"extension","imageWidth":836,"imageHeight":1000,"annotations":{"marks":[{"x":32,"y":64,"rx":12,"ry":12,"label":"局灶深色皮肤肿物","detail":"足趾皮肤上有突出、不规则的黑褐色肿物，周围皮肤仍保留，区别于整段肢端坏疽。"}],"note":"颜色和边界只提供大体线索，恶性性质需组织学确认。"}},{"id":"w038","name":"肾贫血性梗死（陈旧灶）","kind":"大体","system":"循环障碍","image":"assets/w038.jpg","points":["核心词：肾外周楔形灰白病灶、局部凹陷。","病变底朝肾表面、尖端指向髓质，部分区域已瘢痕化、收缩。","新鲜梗死通常灰白或灰黄并有充血边缘；陈旧灶更强调灰白凹陷瘢痕。"],"options":[{"text":"肾贫血性梗死（陈旧灶）","reason":"符合本图：核心词：肾外周楔形灰白病灶、局部凹陷。"},{"text":"肾压迫性萎缩","reason":"该项重点是肾盂肾盏扩张与实质弥漫变薄；本图重点是肾外周楔形灰白病灶、局部凹陷。"},{"text":"慢性肾盂肾炎","reason":"该项重点是粗大不规则瘢痕伴肾盂肾盏变形；本图重点是肾外周楔形灰白病灶、局部凹陷。"},{"text":"肾结核","reason":"该项重点是干酪样坏死与不规则空洞；本图重点是肾外周楔形灰白病灶、局部凹陷。"}],"caution":"凹陷瘢痕提示陈旧改变。","review":"reviewed","scope":"core","imageWidth":284,"imageHeight":405,"annotations":{"marks":[{"x":86,"y":53,"rx":7,"ry":10,"label":"外周浅色梗死灶","detail":"肾外周可见与周围实质色调不同的浅色楔形区域，原箭头指向其附近，表面局部收缩。"}],"note":"原图较小，按外周病灶、楔形走向和瘢痕收缩综合观察，不据颜色判断精确时间。"}},{"id":"w039","name":"肺脓肿","kind":"大体","system":"炎症与修复","image":"assets/w039.jpg","points":["核心词：肺组织内局限性坏死空腔。","肺切面有不规则腔隙，腔壁粗糙并残留坏死碎屑。","与肺出血性梗死相比，脓肿强调局限液化破坏和脓腔；梗死典型为实性的胸膜下楔形出血区。"],"options":[{"text":"肺脓肿","reason":"符合本图：核心词：肺组织内局限性坏死空腔。"},{"text":"肺出血性梗死","reason":"该项重点是胸膜下暗红楔形实变灶；本图重点是肺组织内局限性坏死空腔。"},{"text":"肺转移癌","reason":"该项重点是多发大小不等的界清球形结节；本图重点是肺组织内局限性坏死空腔。"},{"text":"肺粟粒性结核","reason":"该项重点是广泛均匀的细小粟粒结节；本图重点是肺组织内局限性坏死空腔。"}],"caution":"病原及急慢性不能由此图单独确定。","review":"reviewed","scope":"core","imageWidth":300,"imageHeight":405,"annotations":{"marks":[{"x":65,"y":23,"rx":8,"ry":6,"label":"局限坏死腔隙","detail":"肺实质内可见局限不规则腔隙及粗糙浅色腔壁，原箭头指示这一病灶。"},{"x":48,"y":79,"rx":7,"ry":7,"label":"另一脓肿灶","detail":"较下方另有粗糙的小腔隙，结合多个局限破坏灶识别肺脓肿。"}],"note":"中央较规则的大管腔是支气管、血管等解剖结构，不能把肺切面所有孔洞都当作脓肿。"}},{"id":"w041","name":"骨肉瘤","kind":"大体","system":"骨与软组织","image":"assets/w041.jpg","points":["核心词：长骨干骺端破坏性肿块。","剖开的股骨远端有巨大灰白肿物，破坏骨皮质并延伸至周围软组织。","与骨折骨痂相比，肿瘤呈明显破坏和不规则扩张；确诊依靠瘤细胞直接形成骨样组织。"],"options":[{"text":"骨肉瘤","reason":"符合本图：核心词：长骨干骺端破坏性肿块。"},{"text":"软骨肉瘤","reason":"该项重点是软骨样分叶肿块，需组织学证明恶性；本图重点是长骨干骺端破坏性肿块。"},{"text":"骨折修复骨痂","reason":"该项重点是围绕骨折部位的修复组织及新生骨；本图重点是长骨干骺端破坏性肿块。"},{"text":"骨髓白血病浸润","reason":"该项重点是髓腔弥漫灰白组织增多，需镜下辨细胞；本图重点是长骨干骺端破坏性肿块。"}],"caution":"大体支持骨恶性肿瘤；骨肉瘤的定义性证据是镜下恶性瘤细胞产骨样组织，本图不能显示X线征。","review":"reviewed","scope":"core","imageWidth":281,"imageHeight":405,"annotations":{"marks":[{"x":53,"y":72,"rx":40,"ry":25,"label":"破坏性骨肿块","detail":"长骨下端被巨大、不规则实性肿块取代，肿物向骨外扩张，是恶性骨肿瘤的大体要点。"},{"x":54,"y":28,"rx":8,"ry":18,"label":"长骨与肿物关系","detail":"残存长骨结构向下与巨大肿物相连，帮助定位病变在长骨端附近。"}],"note":"恶性瘤细胞形成骨样组织需镜下证据。"}},{"id":"w044","name":"足干性坏疽","kind":"大体","system":"细胞适应与损伤","image":"assets/w044.jpg","points":["核心词：肢端黑褐色、干燥皱缩、分界较清。","足趾及远端组织变黑，表面干缩，与近端较正常组织有清楚过渡。","与湿性坏疽相比，重点是干缩而非明显肿胀；不能从照片判断臭味或宣称完全无细菌。"],"options":[{"text":"足干性坏疽","reason":"符合本图：核心词：肢端黑褐色、干燥皱缩、分界较清。"},{"text":"湿性坏疽","reason":"该项重点是坏死组织明显肿胀、湿润，分界往往不清；本图重点是肢端黑褐色、干燥皱缩、分界较清。"},{"text":"皮肤恶性黑色素瘤","reason":"该项重点是局灶不规则色素性肿物；本图重点是肢端黑褐色、干燥皱缩、分界较清。"},{"text":"浆液性炎（皮肤水疱）","reason":"该项重点是清亮液体充填的表浅水疱；本图重点是肢端黑褐色、干燥皱缩、分界较清。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":287,"imageHeight":405,"annotations":{"marks":[{"x":64,"y":35,"rx":27,"ry":25,"label":"黑褐干缩肢端","detail":"远端组织发黑、表面皱缩并保留足趾外形，符合干性坏疽的肉眼线索。"},{"x":64,"y":65,"rx":27,"ry":8,"label":"坏死分界区域","detail":"黑色肢端与近端较正常组织之间有明显过渡，结合干缩外观识别。"}],"note":""}},{"id":"w045","name":"静脉血栓","kind":"大体","system":"循环障碍","image":"assets/w045.jpg","points":["核心词：剖开的静脉管腔内有条索状血凝物。","血栓随管腔延伸，可占据大部分管腔并与局部管壁相连。","与死后凝血区别须综合表面粗糙、附着及分层；照片本身不能验证是否容易剥离。"],"options":[{"text":"静脉血栓","reason":"符合本图：核心词：剖开的静脉管腔内有条索状血凝物。"},{"text":"动脉粥样硬化","reason":"该项重点是动脉内膜黄白斑块、纤维帽及粥样物；本图重点是剖开的静脉管腔内有条索状血凝物。"},{"text":"死后血凝块","reason":"该项重点是通常湿润光滑、不牢固附着，但需实际检查；本图重点是剖开的静脉管腔内有条索状血凝物。"},{"text":"脉管内癌栓","reason":"该项重点是管腔内异型肿瘤细胞团，依靠镜下确认；本图重点是剖开的静脉管腔内有条索状血凝物。"}],"caution":"静脉部位为题设条件；动静脉性质需结合解剖位置或管壁结构确认。","review":"reviewed","scope":"core","imageWidth":386,"imageHeight":218,"annotations":{"marks":[{"x":28,"y":56,"rx":22,"ry":13,"label":"管腔内条索状血栓","detail":"剖开的静脉腔内有沿管道延伸的棕褐色凝血物，占据较大部分管腔。"},{"x":73,"y":68,"rx":16,"ry":13,"label":"延续的血栓成分","detail":"另一段管腔内也可见延续性凝血物，需结合管壁与腔内位置观察。"}],"note":"照片不能验证血栓附着是否牢固。"}},{"id":"w047","name":"肝海绵状血管瘤","kind":"大体","system":"肝胆系统","image":"assets/w047.jpg","points":["核心词：肝内界清、暗红海绵状肿块。","肿块与周围肝实质有清楚对比，切面呈细小血腔聚集的海绵样外观。","与肝癌灰白或黄白实体灶相比，该瘤以血腔组成；镜下看扩张血管和单层内皮。"],"options":[{"text":"肝海绵状血管瘤","reason":"符合本图：核心词：肝内界清、暗红海绵状肿块。"},{"text":"原发性肝癌","reason":"该项重点是灰白或黄白实体性肿块，可伴出血坏死；本图重点是肝内界清、暗红海绵状肿块。"},{"text":"阿米巴肝脓肿","reason":"该项重点是粗糙破絮状坏死空腔；本图重点是肝内界清、暗红海绵状肿块。"},{"text":"肝脂肪变性","reason":"该项重点是肝脏弥漫较均匀的土黄色改变；本图重点是肝内界清、暗红海绵状肿块。"}],"caution":"固定后可呈灰绿或灰褐色，不能只凭红色识别血管瘤。","review":"reviewed","scope":"core","imageWidth":1000,"imageHeight":378,"annotations":{"marks":[{"x":46,"y":40,"rx":10,"ry":27,"label":"界清海绵样肿块","detail":"肝实质内有边界较清楚、色调较暗且细孔密集的结节，与周围肝组织对比明显。"}],"note":"固定后的血管瘤可偏灰绿，不要求一定鲜红；细孔结构需结合完整视野观察。"}},{"id":"w048","name":"慢性纤维素性胸膜炎（机化）","kind":"大体","system":"炎症与修复","image":"assets/w048.jpg","points":["核心词：胸膜增厚、粘连、纤维性包裹。","肺表面可见厚而灰白的纤维组织，原光滑胸膜变粗糙。","与心包炎先定位器官：本图包绕的是肺；长期纤维素渗出可机化为粘连和增厚。"],"options":[{"text":"慢性纤维素性胸膜炎（机化）","reason":"符合本图：核心词：胸膜增厚、粘连、纤维性包裹。"},{"text":"纤维素性心包炎","reason":"该项重点是心脏外表面的粗糙绒毛状纤维素渗出；本图重点是胸膜增厚、粘连、纤维性包裹。"},{"text":"肺脓肿","reason":"该项重点是局限液化脓腔及粗糙坏死腔壁；本图重点是胸膜增厚、粘连、纤维性包裹。"},{"text":"肺转移癌","reason":"该项重点是多发大小不等的界清球形结节；本图重点是胸膜增厚、粘连、纤维性包裹。"}],"caution":"本图主要显示胸膜机化增厚，未显示保留的浆液。","review":"reviewed","scope":"core","imageWidth":172,"imageHeight":254,"annotations":{"marks":[{"x":82,"y":47,"rx":9,"ry":24,"label":"增厚的胸膜","detail":"肺外侧可见宽而浅色的覆盖组织，与内部肺切面不同，提示胸膜纤维性增厚。"}],"note":"照片不能确认保留的浆液或全部粘连界面。"}},{"id":"w049","name":"脑液化性坏死","kind":"大体","system":"神经系统","image":"assets/w049.jpg","points":["核心词：脑实质软化、溶解并形成不规则缺损。","脑切面局部呈灰黄或红褐的软化区，组织结构模糊，可见腔隙。","与肾脾凝固性坏死比较，脑坏死更易液化，不能保持完整组织轮廓。"],"options":[{"text":"脑液化性坏死","reason":"符合本图：核心词：脑实质软化、溶解并形成不规则缺损。"},{"text":"化脓性脑膜炎","reason":"该项重点是脑表面及脑沟内覆盖脓性渗出物；本图重点是脑实质软化、溶解并形成不规则缺损。"},{"text":"脑膜瘤","reason":"该项重点是脑外界清实体肿块，压迫邻近脑组织；本图重点是脑实质软化、溶解并形成不规则缺损。"},{"text":"脑出血","reason":"该项重点是脑实质内以凝血或血肿为主的破坏灶；本图重点是脑实质软化、溶解并形成不规则缺损。"}],"caution":"本题给定脑液化性坏死诊断；照片不能确定梗死病因或精确时间。","review":"reviewed","scope":"core","imageWidth":326,"imageHeight":274,"annotations":{"marks":[{"x":47,"y":43,"rx":20,"ry":32,"label":"脑软化破坏区","detail":"一侧脑实质出现大片黄褐、结构模糊的异常区域，与右侧相对完整脑组织形成对照。"}],"note":"脑室是正常解剖空腔，不是液化坏死形成的空洞。"}},{"id":"w050","name":"肾压迫性萎缩（肾积水）","kind":"大体","system":"泌尿系统","image":"assets/w050.jpg","points":["核心词：肾盂肾盏扩张＋肾实质明显变薄。","多个扩张腔隙相互连通，残存皮质变成薄层，肾盂附近可见结石样物。","长期梗阻导致实质受压萎缩；肾整体可因积水增大，不要把实质萎缩误记成器官必然缩小。"],"options":[{"text":"肾压迫性萎缩（肾积水）","reason":"符合本图：核心词：肾盂肾盏扩张＋肾实质明显变薄。"},{"text":"肾贫血性梗死（陈旧灶）","reason":"该项重点是肾外周楔形灰白凹陷瘢痕；本图重点是肾盂肾盏扩张＋肾实质明显变薄。"},{"text":"慢性肾盂肾炎","reason":"该项重点是粗大不规则瘢痕伴肾盂肾盏变形；本图重点是肾盂肾盏扩张＋肾实质明显变薄。"},{"text":"肾结核","reason":"该项重点是干酪样坏死与不规则空洞；本图重点是肾盂肾盏扩张＋肾实质明显变薄。"}],"caution":"","review":"reviewed","scope":"core","imageWidth":410,"imageHeight":405,"annotations":{"marks":[{"x":70,"y":25,"rx":19,"ry":16,"label":"扩张肾盂肾盏","detail":"肾内多个大腔隙相连，正常实质被扩张腔隙替代，是积水的关键。"},{"x":85,"y":9,"rx":10,"ry":5,"label":"残存薄层肾实质","detail":"扩张腔隙外仅剩较薄的实质边缘，体现长期受压后的萎缩。"}],"note":"先辨扩张腔隙再看实质厚度；实质萎缩不等于肾整体一定缩小。"}},{"id":"w051","name":"肺转移癌","kind":"大体","system":"肿瘤","image":"assets/w051.jpg","points":["核心词：肺内多发、大小不等、界清球形结节。","结节散布在肺切面和胸膜下，部分突出表面。","与粟粒性结核比较，转移结节大小更悬殊、常更大；不能由此判断原发肿瘤来自哪里。"],"options":[{"text":"肺转移癌","reason":"符合本图：核心词：肺内多发、大小不等、界清球形结节。"},{"text":"肺粟粒性结核","reason":"该项重点是广泛均匀的细小粟粒结节；本图重点是肺内多发、大小不等、界清球形结节。"},{"text":"肺出血性梗死","reason":"该项重点是胸膜下暗红楔形实变灶；本图重点是肺内多发、大小不等、界清球形结节。"},{"text":"肺脓肿","reason":"该项重点是局限液化脓腔及粗糙坏死腔壁；本图重点是肺内多发、大小不等、界清球形结节。"}],"caution":"本图不能独立确定原发肿瘤类型；本题仅考肺转移癌。","review":"reviewed","scope":"core","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":18,"y":36,"rx":10,"ry":11,"label":"胸膜下灰白结节","detail":"肺表面可见较大的界清灰白结节，部分向外突出。"},{"x":70,"y":75,"rx":17,"ry":15,"label":"大小不等的多发结节","detail":"同一肺上同时有多枚大小悬殊的结节，符合转移性分布的教学形态。"}],"note":"需整体观察两肺结节分布，不能据大体判断原发肿瘤来自哪里。"}},{"id":"w055","name":"慢性胆囊炎","kind":"大体","system":"肝胆系统","image":"assets/w055.jpg","points":["核心词：胆囊壁纤维性增厚、腔缩小，可伴结石。","剖开的囊状器官为胆囊，壁较厚、黏膜粗糙，腔内见深色结石样内容物。","与急性阑尾炎先按器官外形区分；慢性胆囊炎镜下为慢性炎细胞和纤维化，可见罗阿窦。"],"options":[{"text":"慢性胆囊炎","reason":"符合本图：核心词：胆囊壁纤维性增厚、腔缩小，可伴结石。"},{"text":"急性阑尾炎","reason":"该项重点是阑尾充血肿胀、浆膜脓性渗出；本图重点是胆囊壁纤维性增厚、腔缩小，可伴结石。"},{"text":"假膜性结肠炎","reason":"该项重点是黏膜表面附着灰黄假膜；本图重点是胆囊壁纤维性增厚、腔缩小，可伴结石。"},{"text":"胆囊癌","reason":"该项重点是胆囊不规则实体肿物和浸润，需镜下确定；本图重点是胆囊壁纤维性增厚、腔缩小，可伴结石。"}],"caution":"图像较模糊，壁厚和结石仅供辅助判断；慢性炎症与癌的鉴别需组织学。","review":"reviewed","scope":"core","imageWidth":180,"imageHeight":114,"annotations":{"marks":[],"note":"图像模糊，囊壁、黏膜及内容物难以精确区分，不能可靠定位结石或囊壁层次。"}},{"id":"w057","name":"脾贫血性梗死","kind":"大体","system":"循环障碍","image":"assets/w057.jpg","points":["核心词：脾外周浅色楔形灶。","梗死灶灰白或灰黄，底面朝脾包膜、尖端朝脾门方向。","与脾淤血的弥漫暗红相比，贫血性梗死是局限且形状与血供区域相关的苍白灶。"],"options":[{"text":"脾贫血性梗死","reason":"符合本图：核心词：脾外周浅色楔形灶。"},{"text":"肾贫血性梗死（陈旧灶）","reason":"该项重点是肾外周楔形灰白凹陷瘢痕；本图重点是脾外周浅色楔形灶。"},{"text":"脾淤血","reason":"该项重点是脾弥漫暗红肿大；本图重点是脾外周浅色楔形灶。"},{"text":"脾淋巴瘤","reason":"该项重点是脾内灰白肿瘤结节，需镜下分型；本图重点是脾外周浅色楔形灶。"}],"caution":"图像没有比例尺，不把病灶大小作为诊断标准。","review":"reviewed","scope":"core","imageWidth":540,"imageHeight":405,"annotations":{"marks":[{"x":81,"y":47,"rx":13,"ry":25,"label":"脾外周浅色病灶","detail":"右侧外周较浅色区域与中央较深色脾实质形成分界，整体呈外宽内窄的血供区形态。"}],"note":"固定后颜色可偏灰绿，需结合病灶形状与外周位置判断。"}},{"id":"w058","name":"肺出血性梗死","kind":"大体","system":"循环障碍","image":"assets/w058.jpg","points":["核心词：胸膜下暗红、楔形出血实变区。","病灶与周围较正常肺组织对比明显，呈大片深红至黑红色。","肺双重血供及淤血背景使梗死可明显出血；区别浅色的肾脾贫血性梗死。"],"options":[{"text":"肺出血性梗死","reason":"符合本图：核心词：胸膜下暗红、楔形出血实变区。"},{"text":"肺脓肿","reason":"该项重点是局限液化脓腔及粗糙坏死腔壁；本图重点是胸膜下暗红、楔形出血实变区。"},{"text":"肺转移癌","reason":"该项重点是多发大小不等的界清球形结节；本图重点是胸膜下暗红、楔形出血实变区。"},{"text":"大叶性肺炎","reason":"该项重点是肺叶较均匀的实变，不以单个楔形区为核心；本图重点是胸膜下暗红、楔形出血实变区。"}],"caution":"必须结合整体器官和病灶形态，单凭红黑颜色不能区分梗死与其他出血性病变。","review":"reviewed","scope":"core","imageWidth":328,"imageHeight":247,"annotations":{"marks":[{"x":56,"y":55,"rx":23,"ry":35,"label":"暗红出血实变区","detail":"肺切面局部呈深红至黑红色、近楔形区域，与周围较红组织有明显对比。"}],"note":"表面反光不是病灶；结合肺组织与楔形出血区判断，不能只看黑红色。"}},{"id":"w059","name":"鼻息肉","kind":"大体","system":"呼吸系统","image":"assets/w059.jpg","points":["核心词：鼻腔内光滑、苍白半透明的息肉状隆起。","内镜图可见一枚表面光滑的圆钝肿物，外观较水肿。","与乳头状瘤粗糙分叶表面相区别；镜下常见高度水肿间质及炎细胞。"],"options":[{"text":"鼻息肉","reason":"符合本图：核心词：鼻腔内光滑、苍白半透明的息肉状隆起。"},{"text":"皮肤乳头状瘤","reason":"该项重点是皮肤局限外生乳头状肿物；本图重点是鼻腔内光滑、苍白半透明的息肉状隆起。"},{"text":"鼻腔恶性肿瘤","reason":"该项重点是可有不规则、浸润、出血肿物，最终需活检；本图重点是鼻腔内光滑、苍白半透明的息肉状隆起。"},{"text":"化脓性炎","reason":"该项重点是大量中性粒细胞及混浊脓性渗出物；本图重点是鼻腔内光滑、苍白半透明的息肉状隆起。"}],"caution":"鼻腔内镜外观不能完全排除其他鼻腔肿物。","review":"reviewed","scope":"core","imageWidth":194,"imageHeight":180,"annotations":{"marks":[{"x":57,"y":35,"rx":13,"ry":25,"label":"光滑息肉样隆起","detail":"鼻腔内有表面圆钝、光滑、较苍白半透明的隆起，是鼻息肉的外观线索。"}],"note":"仅凭隆起外观不能可靠判断鼻腔肿物的性质。"}},{"id":"w062","name":"心脏附壁血栓","kind":"大体","system":"循环障碍","image":"assets/w062.jpg","points":["核心词：心腔内附着于内膜的凝血团块。","剖开的心脏内有灰褐、暗红团块，位于心腔内并贴靠腔壁。","与赘生物按位置区分：附壁血栓在腔壁，感染性或风湿性赘生物多位于瓣膜。"],"options":[{"text":"心脏附壁血栓","reason":"符合本图：核心词：心腔内附着于内膜的凝血团块。"},{"text":"感染性心内膜炎赘生物","reason":"该项重点是瓣膜上的不规则易碎血栓性赘生物；本图重点是心腔内附着于内膜的凝血团块。"},{"text":"死后血凝块","reason":"该项重点是通常湿润光滑、不牢固附着，但需实际检查；本图重点是心腔内附着于内膜的凝血团块。"},{"text":"心肌梗死","reason":"该项重点是心肌壁内缺血坏死灶；本图重点是心腔内附着于内膜的凝血团块。"}],"caution":"此切面不能可靠区分心房与心室；是否牢固附着需实物观察。","review":"reviewed","scope":"core","imageWidth":340,"imageHeight":405,"annotations":{"marks":[{"x":61,"y":31,"rx":27,"ry":18,"label":"心腔内凝血团块","detail":"打开的心腔内有粗糙、灰褐至暗红团块，与平滑腔壁及下方肌性结构不同。"}],"note":"此切面不能可靠区分心房与心室，不能据此定位为心尖血栓。"}},{"id":"w063","name":"心肌梗死","kind":"大体","system":"循环障碍","image":"assets/w063.jpg","points":["核心词：心室壁内局灶苍白或黄白区域。","心脏横切面中局部心肌与周围红色存活心肌形成明显对比。","病灶位于心肌壁而非心腔内；与附壁血栓按解剖位置区分。"],"options":[{"text":"心肌梗死","reason":"符合本图：核心词：心室壁内局灶苍白或黄白区域。"},{"text":"心室附壁血栓","reason":"该项重点是心腔壁表面附着的血栓；本图重点是心室壁内局灶苍白或黄白区域。"},{"text":"心脏肥大","reason":"该项重点是心室壁增厚、乳头肌和肉柱粗大；本图重点是心室壁内局灶苍白或黄白区域。"},{"text":"纤维素性心包炎","reason":"该项重点是心脏外表面的粗糙绒毛状纤维素渗出；本图重点是心室壁内局灶苍白或黄白区域。"}],"caution":"不同时间的梗死颜色不同；此图不要求判断精确天数或陈旧阶段。","review":"reviewed","scope":"core","imageWidth":214,"imageHeight":164,"annotations":{"marks":[{"x":79,"y":22,"rx":15,"ry":12,"label":"心肌黄白病灶","detail":"心室壁内有局灶黄白区域，与周围较红的心肌形成对比，病灶位于肌壁而非心腔。"}],"note":"照片不能确定心肌梗死的精确天数。"}},{"id":"w065","name":"肠出血性梗死","kind":"大体","system":"循环障碍","image":"assets/w065.jpg","points":["核心词：一段肠管暗红坏死并明显肿胀。","肠段外表呈暗红、肿胀，与邻近较正常组织有颜色对比。","与假膜性肠炎的黏膜表面覆膜不同，出血性梗死强调肠壁缺血坏死和出血。"],"options":[{"text":"肠出血性梗死","reason":"符合本图：核心词：一段肠管暗红坏死并明显肿胀。"},{"text":"假膜性结肠炎","reason":"该项重点是黏膜表面附着灰黄假膜；本图重点是一段肠管暗红坏死并明显肿胀。"},{"text":"小肠淋巴瘤","reason":"该项重点是肠壁灰白较均一的浸润增厚；本图重点是一段肠管暗红坏死并明显肿胀。"},{"text":"急性阑尾炎","reason":"该项重点是阑尾充血肿胀、浆膜脓性渗出；本图重点是一段肠管暗红坏死并明显肿胀。"}],"caution":"照片来自手术视野，外观不能直接确认所有肠壁层次；不能仅凭大体确定动脉阻塞、静脉阻塞或绞窄等具体机制。","review":"reviewed","scope":"core","imageWidth":251,"imageHeight":138,"annotations":{"marks":[{"x":43,"y":42,"rx":25,"ry":25,"label":"暗红肿胀肠段","detail":"手术视野中一段肠管表面深红、肿胀，结合受累肠段分布识别出血性梗死形态。"}],"note":"仅见肠管外表，不能确定全部肠壁层次均已坏死或具体血管机制。"}},{"id":"w067","name":"脂肪瘤","kind":"大体","system":"肿瘤","image":"assets/w067.jpg","points":["核心词：界清、分叶、黄色脂肪性肿块。","切面呈淡黄色，类似成熟脂肪，可有薄纤维分隔。","与纤维瘤灰白实性切面相比，脂肪瘤黄而柔软；脂肪肉瘤需镜下异型证据，不能仅靠颜色排除。"],"options":[{"text":"脂肪瘤","reason":"符合本图：核心词：界清、分叶、黄色脂肪性肿块。"},{"text":"纤维瘤","reason":"该项重点是界清灰白实性纤维性结节；本图重点是界清、分叶、黄色脂肪性肿块。"},{"text":"平滑肌瘤","reason":"该项重点是灰白实性、编织或旋涡状切面，镜下为束状平滑肌；本图重点是界清、分叶、黄色脂肪性肿块。"},{"text":"皮肤乳头状瘤","reason":"该项重点是皮肤局限外生乳头状肿物；本图重点是界清、分叶、黄色脂肪性肿块。"}],"caution":"质软和油腻感属于教科书触感，照片本身不能实际触诊；本图以黄色、边界和脂肪样切面为线索。","review":"reviewed","scope":"core","imageWidth":333,"imageHeight":405,"annotations":{"marks":[{"x":40,"y":49,"rx":32,"ry":38,"label":"脂肪样肿块切面","detail":"肿块界限清楚，切面以黄褐色脂肪样组织为主，可见分叶与薄分隔。"}],"note":"固定会改变色调，不能单靠颜色排除脂肪性恶性肿瘤。"}},{"id":"w068","name":"心脏褐色萎缩","kind":"大体","system":"细胞适应与损伤","image":"assets/w068.jpg","points":["核心词：心肌变薄、心脏缩小、心表面动脉迂曲。","心壁相对薄，冠状动脉可因心体积缩小而相对弯曲，心肌色调较深。","褐色来自心肌细胞脂褐素，镜下在核两端；不能把含铁血黄素与脂褐素混为一谈。"],"options":[{"text":"心脏褐色萎缩","reason":"符合本图：核心词：心肌变薄、心脏缩小、心表面动脉迂曲。"},{"text":"心脏肥大","reason":"该项重点是心室壁增厚、乳头肌和肉柱粗大；本图重点是心肌变薄、心脏缩小、心表面动脉迂曲。"},{"text":"心肌梗死","reason":"该项重点是心肌壁内缺血坏死灶；本图重点是心肌变薄、心脏缩小、心表面动脉迂曲。"},{"text":"纤维素性心包炎","reason":"该项重点是心脏外表面的粗糙绒毛状纤维素渗出；本图重点是心肌变薄、心脏缩小、心表面动脉迂曲。"}],"caution":"缺少正常对照和称重，无法据图确定体积、重量或证实脂褐素沉积。","review":"reviewed","scope":"core","imageWidth":325,"imageHeight":405,"annotations":{"marks":[{"x":69,"y":68,"rx":9,"ry":17,"label":"表面迂曲血管","detail":"原箭头附近的表面血管呈较弯曲走行，可作为心脏缩小后相对迂曲的辅助线索。"}],"note":"缺少正常对照和称重，不能据图确认心脏体积；脂褐素需镜下观察。"}},{"id":"w018","name":"卵巢成熟性畸胎瘤（镜下）","kind":"镜下","system":"生殖与乳腺","image":"assets/w018.jpg","points":["核心词：卵巢肿物中出现成熟皮肤及皮肤附属器。","本图两处视野显示成熟复层鳞状上皮、毛囊及皮脂腺等皮肤样结构。","结合题设的卵巢囊性肿物、毛发及皮脂，支持成熟性畸胎瘤；这两个视野不能代表所有胚层成分。"],"options":[{"text":"卵巢成熟性畸胎瘤（镜下）","reason":"符合本图：核心词：卵巢肿物中出现成熟皮肤及皮肤附属器。"},{"text":"卵巢黏液性囊腺瘤","reason":"该项重点是多房囊腔与黏液性内容物；本图重点是卵巢肿物中出现成熟皮肤及皮肤附属器。"},{"text":"卵巢浆液性囊腺瘤","reason":"该项重点是囊壁由输卵管样立方至柱状上皮衬覆；本图重点是卵巢肿物中出现成熟皮肤及皮肤附属器。"},{"text":"卵巢纤维瘤","reason":"该项重点是成束梭形纤维母细胞及胶原组成的实性肿瘤；本图重点是卵巢肿物中出现成熟皮肤及皮肤附属器。"}],"caution":"卵巢部位为题设条件；此视野主要显示成熟皮肤及附属器，不能单独确定器官来源。","review":"reviewed","scope":"core","imageWidth":609,"imageHeight":149,"annotations":{"marks":[{"x":32,"y":63,"rx":4,"ry":25,"label":"成熟毛囊","detail":"可见中央较深的毛干及周围分层毛囊结构，说明肿物中含成熟皮肤附属器。"},{"x":11,"y":47,"rx":7,"ry":28,"label":"皮脂腺样小叶","detail":"毛囊附近有成小叶的浅染腺体，结合成熟毛囊体现皮肤组织成分。"}],"note":"此视野仅见成熟皮肤及附属器，未展示全部胚层成分；卵巢部位为题设条件。"}},{"id":"w019","name":"皮肤毛细血管瘤","kind":"镜下","system":"肿瘤","image":"assets/w019.jpg","points":["核心词：大量小而薄壁的毛细血管腔密集增生。","真皮内可见许多由内皮衬覆的小血管，腔内有红细胞，部分血管挤靠在一起。","与海绵状血管瘤的大而扩张血腔相比，本图血管细小密集；与肉芽组织比较，重点是成团毛细血管增生而非修复创面。"],"options":[{"text":"皮肤毛细血管瘤","reason":"符合本图：核心词：大量小而薄壁的毛细血管腔密集增生。"},{"text":"海绵状血管瘤","reason":"该项重点是多个显著扩张、内含血液的薄壁血管腔；本图重点是大量小而薄壁的毛细血管腔密集增生。"},{"text":"淋巴管瘤","reason":"该项重点是扩张淋巴管腔，内容通常以淋巴液为主；本图重点是大量小而薄壁的毛细血管腔密集增生。"},{"text":"肉芽组织","reason":"该项重点是新生毛细血管、成纤维细胞和炎细胞组成的修复组织；本图重点是大量小而薄壁的毛细血管腔密集增生。"}],"caution":"以血管腔内红细胞、小管径和总体结构综合识别；不要把密集小血管误认成癌腺。","review":"reviewed","scope":"core","imageWidth":478,"imageHeight":191,"annotations":{"marks":[{"x":35,"y":49,"rx":16,"ry":29,"label":"密集小血管群","detail":"代表区域内有大量紧密排列的小血管腔，部分腔内可辨红染红细胞，是毛细血管增生的重点。"}],"note":"右侧较大的皮肤附属器样结构不能误认作海绵状血管腔。"}},{"id":"w020","name":"淋巴结转移性腺癌","kind":"镜下","system":"肿瘤","image":"assets/w020.jpg","points":["核心词：淋巴组织中出现异型上皮性腺管和癌细胞团。","淋巴细胞背景中可见不规则腺样结构，腺上皮细胞核较大、深染且排列失序。","淋巴结正常不具有这类腺体；与淋巴瘤相比，转移性腺癌形成有上皮性结构的癌巢。"],"options":[{"text":"淋巴结转移性腺癌","reason":"符合本图：核心词：淋巴组织中出现异型上皮性腺管和癌细胞团。"},{"text":"反应性淋巴结增生","reason":"该项重点是淋巴滤泡或其他淋巴区增生，缺乏异型癌腺；本图重点是淋巴组织中出现异型上皮性腺管和癌细胞团。"},{"text":"淋巴结结核","reason":"该项重点是干酪样坏死和结核性肉芽肿；本图重点是淋巴组织中出现异型上皮性腺管和癌细胞团。"},{"text":"淋巴瘤","reason":"该项重点是异常淋巴细胞增殖，通常不形成上皮性腺管；本图重点是淋巴组织中出现异型上皮性腺管和癌细胞团。"}],"caution":"本图支持淋巴结内转移性腺癌；不能仅靠这幅图确定胃、结直肠等原发部位。","review":"reviewed","scope":"core","imageWidth":675,"imageHeight":257,"annotations":{"marks":[{"x":39,"y":86,"rx":9,"ry":12,"label":"异常上皮性腺管","detail":"淋巴细胞背景中出现较大的上皮性细胞围成不规则腺管，正常淋巴结不应有此类癌腺。"},{"x":33,"y":41,"rx":12,"ry":23,"label":"淋巴组织背景","detail":"周围为密集、细小、深染的淋巴细胞，与较大的腺上皮细胞形成对照。"}],"note":"癌腺与淋巴组织共同支持转移性腺癌，不能由此确定原发器官。"}},{"id":"w027","name":"涂片中的癌细胞","kind":"镜下","system":"肿瘤","image":"assets/w027.jpg","points":["核心词：成团细胞核明显异型、大小悬殊、深染。","可见核形不规则的大细胞，部分多核或核重叠，细胞群排列失去均一性。","与成熟鳞状上皮、正常间皮细胞相比，重点在多项显著核异型并存；与中性粒细胞的分叶小核不同。"],"options":[{"text":"涂片中的癌细胞","reason":"符合本图：核心词：成团细胞核明显异型、大小悬殊、深染。"},{"text":"成熟鳞状上皮细胞","reason":"该项重点是胞质较丰富、核相对小而规则；本图重点是成团细胞核明显异型、大小悬殊、深染。"},{"text":"中性粒细胞","reason":"该项重点是体积较小、具有分叶核；本图重点是成团细胞核明显异型、大小悬殊、深染。"},{"text":"正常间皮细胞","reason":"该项重点是细胞形态相对均一、核轮廓较规则，不能以单项核大小作判断；本图重点是成团细胞核明显异型、大小悬殊、深染。"}],"caution":"不能仅凭核大判断癌；细胞学诊断需结合完整涂片和临床。","review":"reviewed","scope":"core","imageWidth":331,"imageHeight":236,"annotations":{"marks":[{"x":67,"y":63,"rx":25,"ry":27,"label":"成团异型细胞","detail":"细胞成团聚集，核明显增大、深染且大小不一，可见核重叠和不规则轮廓。"},{"x":44,"y":22,"rx":21,"ry":19,"label":"核大小不均","detail":"上方细胞群也显示核大小悬殊，需结合多项核异型而非单看某个大核。"}],"note":"局部显著异型不足以替代完整细胞学诊断，也不能排除所有反应性改变。"}}]};
